function ns.EnsureClassQuestInfo()
    ns.EnsureClassQuestInfo = function() return ns.ClassQuestInfo end
    if ns.ClassQuestInfo then return ns.ClassQuestInfo end
    ns.ClassQuestInfo = {
    [26] = { n = "A Lesson to Learn", cn = "A Lesson to Learn", l = 16, r = 16, f = "A", races = { 4, 95 }, s = { { 4217, "Mathrengyl Bearwalker", "Darnassus", 35.2, 8, 1457 } }, e = { 11802, "Dendrite Starblaze", "Moonglade", 56.2, 30.4, 1450 }, note = "After Lv 16 you can learn Aquatic Form directly from your class trainer, so this chain becomes optional; do it for the chain reward or the experience; teleporting to Moonglade is the easiest way back for follow-ups." },
    [27] = { n = "A Lesson to Learn", cn = "A Lesson to Learn", l = 16, r = 16, f = "H", races = { 6, 96 }, s = { { 3033, "Turak Runetotem", "Thunder Bluff", 76.4, 27.6, 1456 } }, e = { 11802, "Dendrite Starblaze", "Moonglade", 56.2, 30.4, 1450 }, note = "Available at 16: Alliance see Mathrengyl Bearwalker in Darnassus, Horde see Turak Runetotem in Thunder Bluff; Aquatic Form can now be learned directly from the trainer, so this chain is optional and skipping it doesn't affect using the form." },
    [28] = { n = "Trial of the Lake", cn = "Trial of the Lake", l = 16, r = 16, f = "H", races = { 6, 96 }, s = { { 11802, "Dendrite Starblaze", "Moonglade", 56.2, 30.4, 1450 } }, e = { 11799, "Tajarri", "Moonglade", 36.4, 40.2, 1450 }, note = "Dive into Lake Elune'ara south of Moonglade; the underwater bubble fissure is around (51,51), though some players report (55,53). Swim northeast over the underwater hill; the bottle-shaped container at the bottom is the target, with a fixed spawn point." },
    [29] = { n = "Trial of the Lake", cn = "Trial of the Lake", l = 16, r = 16, f = "A", races = { 4, 95 }, s = { { 11802, "Dendrite Starblaze", "Moonglade", 56.2, 30.4, 1450 } }, e = { 11799, "Tajarri", "Moonglade", 36.4, 40.2, 1450 }, note = "The Horde version works the same as the Alliance one: dive into the lake to find the bubble fissure; the bottle-shaped container has a fixed spawn (some players report (47,47)). After retrieving the charm, go to the tree beside the giant satyr statue, stand directly behind the statue and right-click to use it to complete." },
    [30] = { n = "Trial of the Sea Lion", cn = "Trial of the Sea Lion", l = 16, r = 16, f = "H", races = { 6, 96 }, s = { { 11799, "Tajarri", "Moonglade", 36.4, 40.2, 1450 } }, e = { 11802, "Dendrite Starblaze", "Moonglade", 56.2, 30.4, 1450 }, note = "The halfway trial requires one trinket from each of two bodies of water: Alliance at Darkshore around (48,11) and Westfall around (17,33); Horde at The Barrens around (56,8) and Silverpine Forest around (29,29). There are no map markers underwater, so watch your breath; if you die along the way you'll resurrect as a ghost at the Crossroads." },
    [31] = { n = "Aquatic Form", cn = "Aquatic Form", l = 16, r = 16, f = "H", races = { 6, 96 }, s = { { 11802, "Dendrite Starblaze", "Moonglade", 56.2, 30.4, 1450 } }, e = { 3033, "Turak Runetotem", "Thunder Bluff", 76.4, 27.6, 1456 }, items = { 16608, 263411 }, spells = { 1066 }, note = "Turn-in grants Aquatic Form: faster swimming and unlimited underwater breathing; not a combat form, but very useful for diving and in battleground rivers." },
    [63] = { n = "Call of Water", cn = "Call of Water", l = 23, r = 20, f = "H", races = { 2, 6, 8, 96 }, s = { { 5901, "Islen Waterseer", "The Barrens", 65.8, 43.8, 1413 } }, e = { 113791, "Artifact quest progress", "Silverpine Forest", 38.2, 44.5, 1421 }, note = "Go to the Silverpine Forest shrine at about (38,44), use the elixir in front of the shrine, defeat an attackable elemental, then light the brazier and talk to the water elemental that appears to complete. Fastest route: from behind the Sepulcher inn, go around the big tree and jump down; on the way back, follow the coast north around the hill." },
    [96] = { n = "Call of Water", cn = "Call of Water", l = 23, r = 20, f = "H", races = { 2, 6, 8, 96 }, s = { { 5895, "Minor Manifestation of Water", "Silverpine Forest", 38.6, 44.6, 1421 } }, e = { 5901, "Islen Waterseer", "The Barrens", 65.8, 43.8, 1413 }, items = { 5177 }, spells = { 5394 }, note = "A cross-zone errand: following the prompts, hand off first at the Crossroads and then at Tarren Mill, and finally turn in at about (66,44); no need to kill mobs on the way, and turning in both quests advances you to the end." },
    [100] = { n = "Call of Water", cn = "Call of Water", l = 23, r = 20, f = "H", races = { 2, 6, 8, 96 }, s = { { 113791, "Artifact quest progress", "Silverpine Forest", 38.2, 44.5, 1421 } }, e = { 5895, "Minor Manifestation of Water", "Silverpine Forest", 38.6, 44.6, 1421 }, note = "Don't panic if you fail: you can pick it up again from the troll behind you (requires another trip to Ratchet); the shrine can't be entered directly from the crypt side — go around along the coastline, or jump down from the big tree behind the inn." },
    [220] = { n = "Call of Water", cn = "Call of Water", l = 23, r = 20, f = "H", races = { 2, 6, 8, 96 }, s = { { 5899, "Brine", "The Barrens", 43.4, 77.4, 1413 } }, e = { 5901, "Islen Waterseer", "The Barrens", 65.8, 43.8, 1413 }, items = { 6637 } },
    [272] = { n = "Trial of the Sea Lion", cn = "Trial of the Sea Lion", l = 16, r = 16, f = "A", races = { 4, 95 }, s = { { 11799, "Tajarri", "Moonglade", 36.4, 40.2, 1450 } }, e = { 11802, "Dendrite Starblaze", "Moonglade", 56.2, 30.4, 1450 }, note = "Alliance half: grab one trinket underwater at each of Darkshore around (48,11) and Westfall around (17,33). Darkshore has many deep-water giants underwater; the Westfall one is in an underwater chest where the reefs meet. Get both, then turn in at Moonglade." },
    [335] = { n = "A Noble Brew", cn = "A Noble Brew", l = 30, r = 25, f = "A", s = { { 1435, "Zardeth of the Black Claw", "Stormwind City", 40.1, 85.3, 1453 } }, e = { 1435, "Zardeth of the Black Claw", "Stormwind City", 40.1, 85.3, 1453 }, note = "The Tear of Tilloa is a small bouquet inside the fence of the Duskwood manor, next to Stalvan's house (around 78,36), easy to overlook; Musquash Root is by the lake in the Wetlands at around (65,75)." },
    [336] = { n = "A Noble Brew", cn = "A Noble Brew", l = 30, r = 25, f = "A", s = { { 1435, "Zardeth of the Black Claw", "Stormwind City", 40.1, 85.3, 1453 } }, e = { 1439, "Lord Baurles K. Wishock", "Stormwind City", 77.9, 49.0, 1453 }, note = "The Hall of Petitioners is inside Stormwind Keep; it's the first corridor on the right after entering." },
    [364] = { n = "The Mindless Ones", cn = "The Mindless Ones", l = 2, r = 1, f = "H", s = { { 1569, "Shadow Priest Sarvis", "Tirisfal Glades", 30.8, 66.2, 1420 } }, e = { 1569, "Shadow Priest Sarvis", "Tirisfal Glades", 30.8, 66.2, 1420 }, note = "The target mobs are just outside town and don't aggro, so you can pull them one at a time with enough downtime to regen health and mana; note the target is Plagued Ghouls, not plague zombies." },
    [397] = { n = "You Have Served Us Well", cn = "You Have Served Us Well", l = 30, r = 25, f = "A", races = { 1, 7 }, s = { { 1435, "Zardeth of the Black Claw", "Stormwind City", 40.1, 85.3, 1453 } }, e = { 1733, "Zggi", "Stormwind City", 40.2, 85.3, 1453 }, items = { 3556 }, note = "Warlock-only quest, a follow-up in the \"Fine Brew\" chain; in practice you can take and finish it around Lv 25." },
    [972] = { n = "Water Sapta", cn = "Water Sapta", l = 20, r = 20, f = "H", s = { { 5901, "Islen Waterseer", "The Barrens", 65.8, 43.8, 1413 } }, e = { 5901, "Islen Waterseer", "The Barrens", 65.8, 43.8, 1413 }, items = { 6637 } },
    [1103] = { n = "Call of Water", cn = "Call of Water", l = 23, r = 20, f = "H", races = { 2, 6, 8, 96 }, s = { { 7007, "Tiev Mordune", "Silverpine Forest", 37.4, 44, 1421 } }, e = { 7007, "Tiev Mordune", "Silverpine Forest", 37.4, 44, 1421 }, note = "Talk to the troll beside you first - he'll re-summon the water elemental for you, so you don't have to run back to Ratchet, saving a long round trip." },
    [1442] = { n = "Seeking the Kor Gem", cn = "Seeking the Kor Gem", l = 22, r = 20, f = "A", races = { 1, 3 }, s = { { 3649, "Thundris Windweaver", "Darkshore", 37.4, 40.2, 1439 } }, e = { 3649, "Thundris Windweaver", "Darkshore", 37.4, 40.2, 1439 }, items = { 7083 }, note = "Take the quest before farming so you don't kill for nothing; Corrupted Kor Gems drop from Blackfathom naga inside and outside the dungeon, usually within a few kills." },
    [1462] = { n = "Earth Sapta", cn = "Earth Sapta", l = 4, r = 4, f = "H", s = { { 5888, "Seer Ravenfeather", "Mulgore", 44.8, 76.2, 1412 } }, e = { 5888, "Seer Ravenfeather", "Mulgore", 44.8, 76.2, 1412 }, items = { 6635 } },
    [1463] = { n = "Earth Sapta", cn = "Earth Sapta", l = 4, r = 4, f = "H", s = { { 5887, "Canaga Earthcaller", "Durotar", 42.4, 69, 1411 } }, e = { 5887, "Canaga Earthcaller", "Durotar", 42.4, 69, 1411 }, items = { 6635 } },
    [1464] = { n = "Fire Sapta", cn = "Fire Sapta", l = 13, r = 10, f = "H", s = { { 5900, "Telf Joolam", "Durotar", 38.6, 58.8, 1411 } }, e = { 5900, "Telf Joolam", "Durotar", 38.6, 58.8, 1411 }, items = { 6636 } },
    [1470] = { n = "Piercing the Veil", cn = "Piercing the Veil", l = 3, r = 1, f = "H", races = { 2, 5 }, s = { { 5667, "Venya Marthand", "Tirisfal Glades", 31, 66.2, 1420 } }, e = { 5667, "Venya Marthand", "Tirisfal Glades", 31, 66.2, 1420 }, spells = { 688 }, note = "The target skeletons are only Lv 3 and the skull drop rate is average (about three per five kills); farm them in the graveyard outside town." },
    [1471] = { n = "The Binding", cn = "The Binding", l = 10, r = 10, f = "H", races = { 2, 5 }, s = { { 5675, "Carendin Halgar", "Undercity", 85, 25.6, 1458 } }, e = { 5675, "Carendin Halgar", "Undercity", 85, 25.6, 1458 }, spells = { 697 }, note = "Stand in the purple summoning circle, use the Rune of Summoning to summon a voidwalker, then kill it with Shadow Bolt and Immolate; watch out for passing patrol guards killing it first, which won't count." },
    [1472] = { n = "Devourer of Souls", cn = "Devourer of Souls", l = 20, r = 20, f = "H", races = { 2, 5, 8 }, s = { { 5675, "Carendin Halgar", "Undercity", 85, 25.6, 1458 } }, e = { 5693, "Godrick Farsan", "Undercity", 85, 14.8, 1458 }, note = "The second kill is on the main road from Hillsbrad to Arathi; pick a quiet time and move carefully along the road; Horde players will find the Orgrimmar succubus quest much easier." },
    [1473] = { n = "Creature of the Void", cn = "Creature of the Void", l = 10, r = 10, f = "H", races = { 2, 5 }, s = { { 5675, "Carendin Halgar", "Undercity", 85, 25.6, 1458 } }, e = { 5675, "Carendin Halgar", "Undercity", 85, 25.6, 1458 }, note = "Exit through the Undercity sewers to reach the target tower directly; the quest item is in a small chest inside the tower, easy at Lv 10 or so." },
    [1474] = { n = "The Binding", cn = "The Binding", l = 20, r = 20, f = "H", races = { 2, 5 }, s = { { 5675, "Carendin Halgar", "Undercity", 85, 25.6, 1458 } }, e = { 5675, "Carendin Halgar", "Undercity", 85, 25.6, 1458 }, items = { 22243 }, spells = { 712 } },
    [1476] = { n = "Hearts of the Pure", cn = "Hearts of the Pure", l = 20, r = 20, f = "H", races = { 2, 5 }, s = { { 5693, "Godrick Farsan", "Undercity", 85, 14.8, 1458 } }, e = { 5675, "Carendin Halgar", "Undercity", 85, 25.6, 1458 }, note = "Komar Vilar is past the bridge at the Wetlands north entrance (Wetlands 50,12); talking to him forces PvP on; Darrin is near the Greymane Wall in Silverpine Forest (Silverpine Forest 46,86)." },
    [1478] = { n = "Halgar's Summons", cn = "Halgar's Summons", l = 10, r = 10, f = "H", races = { 2, 5 }, s = { { 5724, "Ageron Kargal", "Tirisfal Glades", 61.6, 52.6, 1420 } }, e = { 5675, "Carendin Halgar", "Undercity", 85, 25.6, 1458 }, note = "Starting NPC Ageron Kargal (Tirisfal Glades - Brill 61,52), next to the warlock trainer on the inn's second floor; turn in to Carendin Halgar back in Undercity (Undercity 84,24)." },
    [1485] = { n = "Vile Familiars", cn = "Vile Familiars", l = 4, r = 1, f = "H", races = { 2, 5, 8 }, s = { { 5765, "Ruzan", "Durotar", 42.6, 69, 1411 } }, e = { 5765, "Ruzan", "Durotar", 42.6, 69, 1411 }, spells = { 688 } },
    [1498] = { n = "Path of Defense", cn = "Path of Defense", l = 10, r = 10, f = "H", s = { { 5810, "Uzzek", "The Barrens", 61.4, 21, 1413 } }, e = { 5810, "Uzzek", "The Barrens", 61.4, 21, 1413 }, spells = { 71 }, note = "The Thunder Lizard is in Durotar (Durotar 39,30); besides Defensive Stance, completing it also teaches Sunder Armor and Taunt." },
    [1499] = { n = "Vile Familiars", cn = "Vile Familiars", l = 4, r = 1, f = "H", races = { 2, 5, 8 }, s = { { 5765, "Ruzan", "Durotar", 42.6, 69, 1411 } }, e = { 3145, "Zureetha Fargaze", "Durotar", 42.8, 69, 1411 }, items = { 4925, 5778 } },
    [1501] = { n = "Creature of the Void", cn = "Creature of the Void", l = 11, r = 10, f = "H", races = { 2, 5, 8 }, s = { { 5875, "Gan'rul Bloodeye", "Orgrimmar", 48.2, 45.6, 1454 } }, e = { 5875, "Gan'rul Bloodeye", "Orgrimmar", 48.2, 45.6, 1454 }, note = "Follow the path up the right side of the cave to the end; the slab is in the chest at the top; the cave is dense with fast-respawning mobs, so bring plenty of food and water; it's tough at low level." },
    [1502] = { n = "Thun'grim Firegaze", cn = "Thun'grim Firegaze", l = 10, r = 10, f = "H", s = { { 5810, "Uzzek", "The Barrens", 61.4, 21, 1413 } }, e = { 5878, "Thun'grim Firegaze", "The Barrens", 57.2, 30.2, 1413 }, note = "Thun'grim is on the hilltop (The Barrens 57,30), with a forge and anvil beside him; the hill can be climbed from any side, (The Barrens 54,29) is the shortest way up, and there's basically no fighting on the way." },
    [1503] = { n = "Forged Steel", cn = "Forged Steel", l = 10, r = 10, f = "H", s = { { 5878, "Thun'grim Firegaze", "The Barrens", 57.2, 30.2, 1413 } }, e = { 5878, "Thun'grim Firegaze", "The Barrens", 57.2, 30.2, 1413 }, items = { 7326, 7328, 7327, 7329 }, note = "The forged steel bars are at the quillboar camp below the hill northwest of Thun'grim (The Barrens 55,26), right under the broken wagon (The Barrens 56,27); you can clear \"Disrupt the Attacks\" on the way." },
    [1504] = { n = "The Binding", cn = "The Binding", l = 11, r = 10, f = "H", races = { 2, 5, 8 }, s = { { 5875, "Gan'rul Bloodeye", "Orgrimmar", 48.2, 45.6, 1454 } }, e = { 5875, "Gan'rul Bloodeye", "Orgrimmar", 48.2, 45.6, 1454 }, spells = { 697 }, note = "The summoning spot is in Neeru Fireblade's hut (Orgrimmar - next to the Ragefire Chasm entrance); go inside, use the summoning item to summon a Voidwalker and defeat it, then return to Gan'rul to turn in." },
    [1505] = { n = "Veteran Uzzek", cn = "Veteran Uzzek", l = 10, r = 10, f = "H", s = { { 3041, "Torm Ragetotem", "Thunder Bluff", 57.6, 87.2, 1456 }, { 3063, "Krang Stonehoof", "Mulgore", 49.4, 60.4, 1412 }, { 3169, "Tarshaw Jaggedscar", "Durotar", 54.2, 42.4, 1411 }, { 3354, "Sorek", "Orgrimmar", 80.2, 32.4, 1454 } }, e = { 5810, "Uzzek", "The Barrens", 61.4, 21, 1413 }, note = "Uzzek is on the Barrens side after crossing the bridge (The Barrens 61,21), standing by the big tree behind Far Watch Post; the Tauren warrior version starts at Hunter Rise in Thunder Bluff." },
    [1506] = { n = "Gan'rul's Summons", cn = "Gan'rul's Summons", l = 10, r = 10, f = "H", races = { 2, 5, 8 }, s = { { 3294, "Ophek", "Durotar", 54.2, 41.2, 1411 } }, e = { 5875, "Gan'rul Bloodeye", "Orgrimmar", 48.2, 45.6, 1454 }, note = "The target NPC is next to the Orgrimmar warlock trainer; even if you've already done the same-named demon quest elsewhere, you can still pick it up here (no second demon, but you get XP and gold)." },
    [1507] = { n = "Devourer of Souls", cn = "Devourer of Souls", l = 20, r = 20, f = "H", races = { 2, 5, 8 }, s = { { 5875, "Gan'rul Bloodeye", "Orgrimmar", 48.2, 45.6, 1454 } }, e = { 5909, "Cazul", "Orgrimmar", 47.2, 46.6, 1454 } },
    [1508] = { n = "Blind Cazul", cn = "Blind Cazul", l = 20, r = 20, f = "H", races = { 2, 5, 8 }, s = { { 5909, "Cazul", "Orgrimmar", 47.2, 46.6, 1454 } }, e = { 5910, "Zankaja", "Orgrimmar", 37, 59.6, 1454 }, note = "Located to the right as you come down the wooden bridge from the flight point (The Barrens - Ratchet 37,60); you can still take this quest even if you've already learned Summon Succubus." },
    [1509] = { n = "News of Dogran", cn = "News of Dogran", l = 20, r = 20, f = "H", races = { 2, 5, 8 }, s = { { 5910, "Zankaja", "Orgrimmar", 37, 59.6, 1454 } }, e = { 3464, "Gazrog", "The Barrens", 51.8, 30.2, 1413 }, note = "The target NPC is right in the Crossroads (The Barrens - Crossroads 51,30), next to the flight point; you can't miss it." },
    [1510] = { n = "News of Dogran", cn = "News of Dogran", l = 20, r = 20, f = "H", races = { 2, 5, 8 }, s = { { 3464, "Gazrog", "The Barrens", 51.8, 30.2, 1413 } }, e = { 4197, "Ken'zigla", "Stonetalon Mountains", 73.2, 95, 1442 }, note = "Ken'zigla is at the Malaka'jin camp in the Stonetalon Mountains (Stonetalon Mountains 73,95); after entering Stonetalon, take the path along the cliff south to get there with no fighting, and turn left once you see the buildings on your left." },
    [1511] = { n = "Ken'zigla's Draught", cn = "Ken'zigla's Draught", l = 20, r = 20, f = "H", races = { 2, 5 }, s = { { 4197, "Ken'zigla", "Stonetalon Mountains", 73.2, 95, 1442 } }, e = { 5911, "Grunt Logmar", "The Barrens", 44.6, 59.2, 1413 }, note = "The turn-in is at Camp Taurajo (The Barrens 46,60); the coordinates are in The Barrens, don't confuse this with the same-named NPC in the Stonetalon Mountains." },
    [1512] = { n = "Love's Gift", cn = "Love's Gift", l = 20, r = 20, f = "H", races = { 2, 5 }, s = { { 5908, "Grunt Dogran", "The Barrens", 43.2, 47.8, 1413 } }, e = { 5875, "Gan'rul Bloodeye", "Orgrimmar", 48.2, 45.6, 1454 }, note = "The target NPC is in the hut in the Cleft of Shadow in Orgrimmar (Orgrimmar 48,45), the one who guides you to obtain new minions." },
    [1513] = { n = "The Binding", cn = "The Binding", l = 20, r = 20, f = "H", races = { 2, 5 }, s = { { 5875, "Gan'rul Bloodeye", "Orgrimmar", 48.2, 45.6, 1454 } }, e = { 5875, "Gan'rul Bloodeye", "Orgrimmar", 48.2, 45.6, 1454 }, items = { 22243 }, spells = { 712 }, note = "The summoning spot is in Neeru Fireblade's tent (Orgrimmar, next to the Ragefire Chasm entrance); the succubus is very easy to kill." },
    [1515] = { n = "Dogran's Captivity", cn = "Dogran's Captivity", l = 20, r = 20, f = "H", races = { 2, 5 }, s = { { 5911, "Grunt Logmar", "The Barrens", 44.6, 59.2, 1413 } }, e = { 5908, "Grunt Dogran", "The Barrens", 43.2, 47.8, 1413 }, note = "Dogran (The Barrens 43,47) may be guarded by Lv 22 elites nearby; the easiest approach is to send your voidwalker in first to grab aggro, then rescue him." },
    [1516] = { n = "Call of Earth", cn = "Call of Earth", l = 4, r = 4, f = "H", races = { 2, 6, 8 }, s = { { 5887, "Canaga Earthcaller", "Durotar", 42.4, 69, 1411 } }, e = { 5887, "Canaga Earthcaller", "Durotar", 42.4, 69, 1411 }, note = "The felhounds are at the Burning Blade Coven (Durotar 45,56), the same spot as the \"Vile Familiars\" quest - clear them together." },
    [1517] = { n = "Call of Earth", cn = "Call of Earth", l = 4, r = 4, f = "H", races = { 2, 6, 8 }, s = { { 5887, "Canaga Earthcaller", "Durotar", 42.4, 69, 1411 } }, e = { 5891, "Minor Manifestation of Earth", "Durotar", 44, 76, 1411 }, note = "The hidden path entrance is on the south side of the Valley of Trials (Durotar 41,73); follow it up to Spirit Rock (Durotar 44,76)." },
    [1518] = { n = "Call of Earth", cn = "Call of Earth", l = 4, r = 4, f = "H", races = { 2, 6, 8 }, s = { { 5891, "Minor Manifestation of Earth", "Dun Morogh", 24.8, 61.8, 1426 }, { 5891, "Minor Manifestation of Earth", "Durotar", 44, 76, 1411 }, { 5891, "Minor Manifestation of Earth", "Mulgore", 53.8, 80.4, 1412 } }, e = { 5887, "Canaga Earthcaller", "Durotar", 42.4, 69, 1411 }, items = { 5175 }, spells = { 8071 }, note = "Return to the village and turn in to the question-mark NPC to get your first Earth Totem and the Stoneskin Totem ability; keep the totem in your bags, it's needed to cast totems of that element." },
    [1519] = { n = "Call of Earth", cn = "Call of Earth", l = 4, r = 4, f = "H", races = { 2, 6 }, s = { { 5888, "Seer Ravenfeather", "Mulgore", 44.8, 76.2, 1412 } }, e = { 5888, "Seer Ravenfeather", "Mulgore", 44.8, 76.2, 1412 }, note = "Kill Bristleback Shamans in the ravine north of Camp Narache and collect 2 salves; the drop rate isn't 100%, so you may need to kill a few more." },
    [1520] = { n = "Call of Earth", cn = "Call of Earth", l = 4, r = 4, f = "H", races = { 2, 6, 8 }, s = { { 5888, "Seer Ravenfeather", "Mulgore", 44.8, 76.2, 1412 } }, e = { 5891, "Minor Manifestation of Earth", "Mulgore", 53.8, 80.4, 1412 }, note = "The Kodo Rock is due east of the well where Grandmother Hawkwind is (Mulgore 53,80); after talking to the Minor Manifestation of Earth you only have 20 minutes, don't let it despawn or you'll have to redo it." },
    [1521] = { n = "Call of Earth", cn = "Call of Earth", l = 4, r = 4, f = "H", races = { 2, 6, 8 }, s = { { 5891, "Minor Manifestation of Earth", "Dun Morogh", 24.8, 61.8, 1426 }, { 5891, "Minor Manifestation of Earth", "Durotar", 44, 76, 1411 }, { 5891, "Minor Manifestation of Earth", "Mulgore", 53.8, 80.4, 1412 } }, e = { 5888, "Seer Ravenfeather", "Mulgore", 44.8, 76.2, 1412 }, items = { 5175 }, spells = { 8071 } },
    [1522] = { n = "Call of Fire", cn = "Call of Fire", l = 10, r = 10, f = "H", races = { 2, 6, 8 }, s = { { 5892, "Searn Firewarder", "Orgrimmar", 37.8, 37.4, 1454 } }, e = { 5907, "Kranal Fiss", "The Barrens", 55.8, 20, 1413 }, note = "Kranal Fiss is at the farm northeast of the Crossroads (The Barrens 56,20); leave town heading north and take the right fork." },
    [1523] = { n = "Call of Fire", cn = "Call of Fire", l = 10, r = 10, f = "H", races = { 2, 6, 8 }, s = { { 5906, "Xanis Flameweaver", "Thunder Bluff", 25.2, 21, 1456 } }, e = { 5907, "Kranal Fiss", "The Barrens", 55.8, 20, 1413 } },
    [1524] = { n = "Call of Fire", cn = "Call of Fire", l = 11, r = 10, f = "H", races = { 2, 6, 8 }, s = { { 5907, "Kranal Fiss", "The Barrens", 55.8, 20, 1413 } }, e = { 5900, "Telf Joolam", "Durotar", 38.6, 58.8, 1411 }, note = "Telf Joolam is actually in Durotar (Durotar 39,59): follow the road to the Barrens, turn left before the big river without crossing the bridge; a black rock at the foot of the mountain marks the entrance up the cliff." },
    [1525] = { n = "Call of Fire", cn = "Call of Fire", l = 12, r = 10, f = "H", races = { 2, 6, 8 }, s = { { 5900, "Telf Joolam", "Durotar", 38.6, 58.8, 1411 } }, e = { 5900, "Telf Joolam", "Durotar", 38.6, 58.8, 1411 }, items = { 6636 }, note = "Reagent Pouches drop from Burning Blade cultists north of Razor Hill (Durotar 51,26, cave entrance at 52,29 — don't go down into the ravine); Fire Tar drops from Razormane caster mobs at Thorn Hill east of the Crossroads (The Barrens 55,26) — the guards and hunters don't drop it." },
    [1526] = { n = "Call of Fire", cn = "Call of Fire", l = 13, r = 10, f = "H", races = { 2, 6, 8 }, s = { { 5900, "Telf Joolam", "Durotar", 38.6, 58.8, 1411 } }, e = { 61934, "Lizardfolk Healer", "Durotar", 38.9, 58.2, 1411 }, items = { 6654 }, note = "Use the quest potion near the big rock next to Telf to summon the Minor Manifestation of Fire; fight with Rockbiter Weapon plus Earth Shock (fire spells are weak against it), and after defeating it, loot the Glowing Ember and put it in the brazier to complete." },
    [1527] = { n = "Call of Fire", cn = "Call of Fire", l = 13, r = 10, f = "H", races = { 2, 6, 8 }, s = { { 61934, "Lizardfolk Healer", "Durotar", 38.9, 58.2, 1411 }, { 61934, "Lizardfolk Healer", "Loch Modan", 31.9, 64.5, 1432 } }, e = { 5907, "Kranal Fiss", "The Barrens", 55.8, 20, 1413 }, items = { 5176, 263412 }, spells = { 3599 }, note = "Kranal Fiss (The Barrens 55,20), a bit east of the child being chased by bees by the road; note the coordinates are in The Barrens, don't go looking in Durotar." },
    [1528] = { n = "Call of Water", cn = "Call of Water", l = 20, r = 20, f = "H", races = { 2, 6, 8 }, s = { { 5892, "Searn Firewarder", "Orgrimmar", 37.8, 37.4, 1454 } }, e = { 5901, "Islen Waterseer", "The Barrens", 65.8, 43.8, 1413 }, note = "Islen Waterseer is in the fisherman's hut (The Barrens 65,43); fly to Ratchet and walk from there; Call of Water is a classic long shaman chain with lots of running, so plan your route ahead." },
    [1529] = { n = "Call of Water", cn = "Call of Water", l = 20, r = 20, f = "H", races = { 2, 6, 8 }, s = { { 5906, "Xanis Flameweaver", "Thunder Bluff", 25.2, 21, 1456 } }, e = { 5901, "Islen Waterseer", "The Barrens", 65.8, 43.8, 1413 } },
    [1530] = { n = "Call of Water", cn = "Call of Water", l = 22, r = 20, f = "H", races = { 2, 6, 8, 96 }, s = { { 5901, "Islen Waterseer", "The Barrens", 65.8, 43.8, 1413 } }, e = { 5899, "Brine", "The Barrens", 43.4, 77.4, 1413 }, note = "The brine elementals are at Blackthorn Ridge (The Barrens 43,77), south of Camp Taurajo; on the way, watch for the level 25 thunderhawk Washte Pawne, whose quest item drop can be turned in at the camp for extra XP." },
    [1531] = { n = "Call of Air", cn = "Call of Air", l = 30, r = 30, f = "H", races = { 2, 6, 8 }, s = { { 5892, "Searn Firewarder", "Orgrimmar", 37.8, 37.4, 1454 } }, e = { 5905, "Prate Cloudseer", "Thousand Needles", 53.6, 42.8, 1441 }, items = { 5178 }, note = "Pratt the Wanderer is at the cave mouth on the cliff (Thousand Needles 54,43); follow the path up to the plateau to talk to him; completing it grants a strong 1-hour buff: +40% run speed and +30% attack speed." },
    [1532] = { n = "Call of Air", cn = "Call of Air", l = 30, r = 30, f = "H", races = { 2, 6, 8 }, s = { { 5906, "Xanis Flameweaver", "Thunder Bluff", 25.2, 21, 1456 } }, e = { 5905, "Prate Cloudseer", "Thousand Needles", 53.6, 42.8, 1441 }, items = { 5178 } },
    [1534] = { n = "Call of Water", cn = "Call of Water", l = 23, r = 20, f = "H", races = { 2, 6, 8, 96 }, s = { { 5899, "Brine", "The Barrens", 43.4, 77.4, 1413 } }, e = { 5899, "Brine", "The Barrens", 43.4, 77.4, 1413 }, note = "The fountain is on the island in the middle of the lake (Ashenvale 33,67), surrounded by level 23-34 mobs that root, making escape hard; the guardian wandering by the lake is a ?? elite, steer clear of it." },
    [1535] = { n = "Call of Water", cn = "Call of Water", l = 22, r = 20, f = "H", races = { 2, 6, 8, 96 }, s = { { 5899, "Brine", "The Barrens", 43.4, 77.4, 1413 } }, e = { 5899, "Brine", "The Barrens", 43.4, 77.4, 1413 }, note = "The water spot is just below the east side of the hut; drawing water spawns a quilboar that's easy to kill - or skip it and run up the slope to turn in." },
    [1536] = { n = "Call of Water", cn = "Call of Water", l = 22, r = 20, f = "H", races = { 2, 6, 8, 96 }, s = { { 5899, "Brine", "The Barrens", 43.4, 77.4, 1413 } }, e = { 5899, "Brine", "The Barrens", 43.4, 77.4, 1413 }, note = "The well is outside the church in the center of Tarren Mill (Hillsbrad Foothills - Tarren Mill); before setting out you can pick up \"Journey to Hillsbrad Foothills\" from the crypt inn on the way for some free XP." },
    [1598] = { n = "The Stolen Tome", cn = "The Stolen Tome", l = 4, r = 1, f = "A", races = { 1, 7 }, s = { { 459, "Drusilla La Salle", "Elwynn Forest", 49.8, 42.6, 1429 } }, e = { 459, "Drusilla La Salle", "Elwynn Forest", 49.8, 42.6, 1429 }, spells = { 688 }, note = "The tome is at the tent on the north side of the vineyard (Elwynn Forest 56,43); the three Defias are linked and can't be pulled singly; you can duck into the tent so the mobs get stuck, then grab the book through the tent." },
    [1599] = { n = "Beginnings", cn = "Beginnings", l = 4, r = 1, f = "A", races = { 1, 7 }, s = { { 460, "Alamar Grimm", "Dun Morogh", 28.6, 66.2, 1426 } }, e = { 460, "Alamar Grimm", "Dun Morogh", 28.6, 66.2, 1426 }, spells = { 688 }, note = "The feathers drop from the Frostmane Novices deep in the cave; only two or three are up at a time, respawning about every two minutes; enter on the left side of the entrance to avoid extra pulls." },
    [1638] = { n = "A Warrior's Training", cn = "A Warrior's Training", l = 10, r = 10, f = "A", s = { { 913, "Lyria Du Lac", "Elwynn Forest", 41, 65.8, 1429 }, { 5480, "Ilsa Corbin", "Stormwind City", 80.4, 59.8, 1453 } }, e = { 6089, "Harry Burlguard", "Stormwind City", 77.1, 53.3, 1453 }, note = "The Pig and Whistle Tavern is in Stormwind's Old Town (Stormwind City 77,53), next to the mailbox; get the mug from Harry Burlguard to start the Alliance warrior Defensive Stance chain." },
    [1639] = { n = "Bartleby the Drunk", cn = "Bartleby the Drunk", l = 10, r = 10, f = "A", s = { { 6089, "Harry Burlguard", "Stormwind City", 77.1, 53.3, 1453 } }, e = { 6090, "Bartleby", "Stormwind City", 76.8, 52.5, 1453 }, note = "Completing this quest forcibly turns on PvP; if you mind, take the Gnome/Dwarf line instead; it's simple: teach Bartleby a lesson and get the mug back." },
    [1640] = { n = "Beat Bartleby", cn = "Beat Bartleby", l = 10, r = 10, f = "A", s = { { 6090, "Bartleby", "Stormwind City", 76.8, 52.5, 1453 } }, e = { 6090, "Bartleby", "Stormwind City", 76.8, 52.5, 1453 } },
    [1641] = { n = "The Tome of Divinity", cn = "The Tome of Divinity", l = 12, r = 12, f = "A", races = { 1 }, s = { { 6171, "Duthorian Rall", "Stormwind City", 50.5, 47.5, 1453 } }, e = { 6171, "Duthorian Rall", "Stormwind City", 50.5, 47.5, 1453 }, items = { 6775 } },
    [1642] = { n = "The Tome of Divinity", cn = "The Tome of Divinity", l = 12, r = 12, f = "A", races = { 1 }, e = { 6171, "Duthorian Rall", "Stormwind City", 50.5, 47.5, 1453 }, note = "The starting NPC differs by race: the human version starts with Brother Wilhelm behind the Goldshire blacksmith, delivering the book to the Stormwind Cathedral; available at 12, this chain ultimately teaches Resurrection." },
    [1643] = { n = "The Tome of Divinity", cn = "The Tome of Divinity", l = 12, r = 12, f = "A", races = { 1 }, s = { { 6171, "Duthorian Rall", "Stormwind City", 50.5, 47.5, 1453 } }, e = { 6174, "Stephanie Turner", "Stormwind City", 63.8, 72.2, 1453 }, note = "The turn-in NPC is at the grocery stall next to the cheese shop in Stormwind's Trade District (Stormwind City 64,72)." },
    [1644] = { n = "The Tome of Divinity", cn = "The Tome of Divinity", l = 13, r = 12, f = "A", races = { 1 }, s = { { 6174, "Stephanie Turner", "Stormwind City", 63.8, 72.2, 1453 } }, e = { 6174, "Stephanie Turner", "Stormwind City", 63.8, 72.2, 1453 }, note = "Requires 10 Linen Cloth; have it ready before turning in so the trip isn't wasted." },
    [1645] = { n = "The Tome of Divinity", cn = "The Tome of Divinity", l = 12, r = 12, f = "A", races = { 3 }, s = { { 6179, "Tiza Battleforge", "Ironforge", 27.4, 12, 1455 } }, e = { 6179, "Tiza Battleforge", "Ironforge", 27.4, 12, 1455 }, items = { 6916 } },
    [1646] = { n = "The Tome of Divinity", cn = "The Tome of Divinity", l = 12, r = 12, f = "A", races = { 3 }, e = { 6179, "Tiza Battleforge", "Ironforge", 27.4, 12, 1455 } },
    [1647] = { n = "The Tome of Divinity", cn = "The Tome of Divinity", l = 12, r = 12, f = "A", races = { 3 }, s = { { 6179, "Tiza Battleforge", "Ironforge", 27.4, 12, 1455 } }, e = { 6175, "John Turner", "Ironforge", 23.3, 61.9, 1455 }, note = "John Turner usually stands at the auction house entrance: leave the Mystic Ward, turn right and follow the outer ring south to run into him." },
    [1648] = { n = "The Tome of Divinity", cn = "The Tome of Divinity", l = 13, r = 12, f = "A", races = { 3 }, s = { { 6175, "John Turner", "Ironforge", 23.3, 61.9, 1455 } }, e = { 6175, "John Turner", "Ironforge", 23.3, 61.9, 1455 } },
    [1649] = { n = "The Tome of Valor", cn = "The Tome of Valor", l = 20, r = 20, f = "A", e = { 6171, "Duthorian Rall", "Stormwind City", 50.5, 47.5, 1453 }, note = "This chain begins by obtaining the \"Tome of Valor\" at the Stormwind Cathedral; after reading the book, find Daphne Stilwell in Westfall; an important step for Paladins." },
    [1650] = { n = "The Tome of Valor", cn = "The Tome of Valor", l = 23, r = 20, f = "A", races = { 1, 3 }, s = { { 6171, "Duthorian Rall", "Stormwind City", 50.5, 47.5, 1453 } }, e = { 6182, "Daphne Stilwell", "Westfall", 42.2, 88.6, 1436 }, note = "From the Deadmines exit, follow the path beside the mine around the back of the hill to reach Daphne's farm (Westfall 41,89)." },
    [1651] = { n = "The Tome of Valor", cn = "The Tome of Valor", l = 25, r = 20, f = "A", races = { 1, 3 }, s = { { 6182, "Daphne Stilwell", "Westfall", 42.2, 88.6, 1436 } }, e = { 6182, "Daphne Stilwell", "Westfall", 42.2, 88.6, 1436 }, note = "Daphne walks back to the house first before the spawns start: three waves of level 16-18 Defias attack; Retribution Aura makes it safer. First go back to the Cathedral to get the book from Duthorian Rall before finding her — don't be fooled by the blue question mark." },
    [1652] = { n = "The Tome of Valor", cn = "The Tome of Valor", l = 25, r = 20, f = "A", races = { 1, 3 }, s = { { 6182, "Daphne Stilwell", "Westfall", 42.2, 88.6, 1436 } }, e = { 6171, "Duthorian Rall", "Stormwind City", 50.5, 47.5, 1453 }, items = { 9607 }, spells = { 5502 } },
    [1653] = { n = "The Test of Righteousness", cn = "The Test of Righteousness", l = 21, r = 20, f = "A", races = { 1, 3 }, s = { { 6171, "Duthorian Rall", "Stormwind City", 50.5, 47.5, 1453 } }, e = { 6181, "Jordan Stilwell", "Dun Morogh", 52.4, 36.8, 1426 }, note = "The target NPC is right outside the gates of Ironforge (Dun Morogh 52,36)." },
    [1654] = { n = "The Test of Righteousness", cn = "The Test of Righteousness", l = 22, r = 20, f = "A", races = { 1, 3 }, s = { { 6181, "Jordan Stilwell", "Dun Morogh", 52.4, 36.8, 1426 } }, e = { 6181, "Jordan Stilwell", "Dun Morogh", 52.4, 36.8, 1426 }, note = "You need four items, two of which require separate quests: White Stone Oak drops from goblin woodworkers in the Deadmines Mast Room; the smithing hammer is in Shadowfang Keep — soloable at 22 but safer in a group; for the naga, kill the tide naga in Blackfathom, not the Wrathtail naga." },
    [1655] = { n = "Bailor's Ore Shipment", cn = "Bailor's Ore Shipment", l = 22, r = 20, f = "A", races = { 1, 3 }, s = { { 6241, "Bailor Stonehand", "Loch Modan", 36, 45, 1432 } }, e = { 6241, "Bailor Stonehand", "Loch Modan", 36, 45, 1432 }, items = { 6993 } },
    [1661] = { n = "The Tome of Nobility", cn = "The Tome of Nobility", l = 40, r = 40, f = "A", races = { 1, 3 }, s = { { 6171, "Duthorian Rall", "Stormwind City", 50.5, 47.5, 1453 } }, e = { 6171, "Duthorian Rall", "Stormwind City", 50.5, 47.5, 1453 }, spells = { 13819 } },
    [1665] = { n = "Bartleby's Mug", cn = "Bartleby's Mug", l = 10, r = 10, f = "A", s = { { 6090, "Bartleby", "Stormwind City", 76.8, 52.5, 1453 } }, e = { 6089, "Harry Burlguard", "Stormwind City", 77.1, 53.3, 1453 }, spells = { 71 }, note = "Completing it teaches Defensive Stance, Taunt and Sunder Armor - core starting warrior skills; next, go see Marshal Haggard." },
    [1666] = { n = "Marshal Haggard", cn = "Marshal Haggard", l = 10, r = 10, f = "A", s = { { 6089, "Harry Burlguard", "Stormwind City", 77.1, 53.3, 1453 } }, e = { 294, "Marshal Haggard", "Elwynn Forest", 84.6, 69.4, 1429 }, note = "Hajad is at the southeast corner of the Eastvale Logging Camp (Elwynn Forest 84,69); finish the follow-up quickly, as there are reports that the quest may disappear from the quest log after logging out." },
    [1667] = { n = "Dead-tooth Jack", cn = "Dead-tooth Jack", l = 10, r = 10, f = "A", s = { { 294, "Marshal Haggard", "Elwynn Forest", 84.6, 69.4, 1429 } }, e = { 294, "Marshal Haggard", "Elwynn Forest", 84.6, 69.4, 1429 }, items = { 6979, 6983, 6980, 6985 }, note = "Toothrot Jack (Elwynn Forest 89,78) has two followers; bring a ranged weapon to pull them back one at a time; a rare also spawns here, so check your target before engaging." },
    [1678] = { n = "Vejrek", cn = "Vejrek", l = 11, r = 10, f = "A", s = { { 6114, "Muren Stormpike", "Ironforge", 70.6, 90.4, 1455 } }, e = { 6114, "Muren Stormpike", "Ironforge", 70.6, 90.4, 1455 }, spells = { 71 }, note = "Vejrek's hut is south of Frostmane Hold: head south to the foot of the mountain, then turn east and look for a short slope running south; completing it also teaches Defensive Stance, Taunt and Sunder Armor." },
    [1679] = { n = "Muren Stormpike", cn = "Muren Stormpike", l = 10, r = 10, f = "A", races = { 1, 3, 7 }, s = { { 1229, "Granis Swiftaxe", "Dun Morogh", 47.2, 52.6, 1426 } }, e = { 6114, "Muren Stormpike", "Ironforge", 70.6, 90.4, 1455 } },
    [1680] = { n = "Tormus Deepforge", cn = "Tormus Deepforge", l = 11, r = 10, f = "A", s = { { 6114, "Muren Stormpike", "Ironforge", 70.6, 90.4, 1455 } }, e = { 6031, "Tormus Deepforge", "Ironforge", 48.6, 43, 1455 }, note = "Thomas Deepforge is in the very center of the Great Forge in Ironforge, right beside Grumnus Steelshaper." },
    [1681] = { n = "Ironband's Compound", cn = "Ironband's Compound", l = 11, r = 10, f = "A", s = { { 6031, "Tormus Deepforge", "Ironforge", 48.6, 43, 1455 } }, e = { 6031, "Tormus Deepforge", "Ironforge", 48.6, 43, 1455 }, note = "Ironband's camp is on the south side of Helm's Bed Lake (Dun Morogh 78,62); the Shadow Ore is in the building on the south side of the camp." },
    [1682] = { n = "Grey Iron Weapons", cn = "Grey Iron Weapons", l = 10, r = 10, f = "A", s = { { 6031, "Tormus Deepforge", "Ironforge", 48.6, 43, 1455 } }, e = { 6031, "Tormus Deepforge", "Ironforge", 48.6, 43, 1455 }, items = { 6978, 6982, 6981, 6984 } },
    [1683] = { n = "Vorlus Vilehoof", cn = "Vorlus Vilehoof", l = 10, r = 10, f = "A", s = { { 4088, "Elanaria", "Darnassus", 57.4, 34.8, 1457 } }, e = { 4088, "Elanaria", "Darnassus", 57.4, 34.8, 1457 }, spells = { 71 }, note = "The path entrance is west of Dolanaar (Teldrassil 49,59), lit by lanterns all the way so it's easy to spot; the level 10 demon is easy, loot the horn and go back to learn Defensive Stance." },
    [1684] = { n = "Elanaria", cn = "Elanaria", l = 10, r = 10, f = "A", s = { { 2151, "Moon Priestess Amara", "Teldrassil", 52.9, 57.2, 1438 }, { 3598, "Kyra Windblade", "Teldrassil", 56.2, 59.2, 1438 } }, e = { 4088, "Elanaria", "Darnassus", 57.4, 34.8, 1457 } },
    [1685] = { n = "Gakin's Summons", cn = "Gakin's Summons", l = 10, r = 10, f = "A", races = { 1, 7 }, s = { { 6121, "Remen Marcot", "Elwynn Forest", 44.4, 66.2, 1429 } }, e = { 6122, "Gakin the Darkbinder", "Stormwind City", 39.2, 85.2, 1453 }, note = "Gakin the Darkbinder is in the Slaughtered Lamb inn in Stormwind's Mage Quarter (Stormwind City 39,85); the summoning circle is in the inn's basement." },
    [1686] = { n = "The Shade of Elura", cn = "The Shade of Elura", l = 10, r = 10, f = "A", s = { { 4088, "Elanaria", "Darnassus", 57.4, 34.8, 1457 } }, e = { 4088, "Elanaria", "Darnassus", 57.4, 34.8, 1457 }, note = "The crates are scattered around the Darkshore shipwreck (Darkshore 31,45), underwater near the giant turtle corpse by the dock; a Water Breathing potion makes it much easier." },
    [1688] = { n = "Surena Caledon", cn = "Surena Caledon", l = 10, r = 10, f = "A", races = { 1, 7 }, s = { { 6122, "Gakin the Darkbinder", "Stormwind City", 39.2, 85.2, 1453 } }, e = { 6122, "Gakin the Darkbinder", "Stormwind City", 39.2, 85.2, 1453 }, note = "Surena is in the house at the pumpkin field east of Goldshire (Elwynn Forest 71,80); the target of \"The Collector\" is in the same house, so clear both together." },
    [1689] = { n = "The Binding", cn = "The Binding", l = 10, r = 10, f = "A", races = { 1, 7 }, s = { { 6122, "Gakin the Darkbinder", "Stormwind City", 39.2, 85.2, 1453 } }, e = { 6122, "Gakin the Darkbinder", "Stormwind City", 39.2, 85.2, 1453 }, spells = { 697 }, note = "The summoning circle is hard to find: go down the ramp opposite Gakin's room, take two flights of stairs keeping right both times, then turn right and go down the last flight; summoning needs a Soul Shard, so have one ready." },
    [1692] = { n = "Smith Mathiel", cn = "Smith Mathiel", l = 10, r = 10, f = "A", s = { { 4088, "Elanaria", "Darnassus", 57.4, 34.8, 1457 } }, e = { 6142, "Mathiel", "Darnassus", 59.2, 45.4, 1457 } },
    [1693] = { n = "Weapons of Elunite", cn = "Weapons of Elunite", l = 10, r = 10, f = "A", s = { { 6142, "Mathiel", "Darnassus", 59.2, 45.4, 1457 } }, e = { 6142, "Mathiel", "Darnassus", 59.2, 45.4, 1457 }, items = { 6966, 6968, 6969, 6967 } },
    [1698] = { n = "Yorus Barleybrew", cn = "Yorus Barleybrew", l = 20, r = 20, f = "A", s = { { 5113, "Kelv Sternhammer", "Ironforge", 70, 90.6, 1455 }, { 5479, "Wu Shen", "Stormwind City", 80.5, 59.9, 1453 }, { 7315, "Darnath Bladesinger", "Darnassus", 58.6, 35.4, 1457 } }, e = { 6166, "Yorus Barleybrew", "Redridge Mountains", 26.6, 44.8, 1433 } },
    [1699] = { n = "The Rethban Gauntlet", cn = "The Rethban Gauntlet", l = 22, r = 20, f = "A", s = { { 6166, "Yorus Barleybrew", "Redridge Mountains", 26.6, 44.8, 1433 } }, e = { 6166, "Yorus Barleybrew", "Redridge Mountains", 26.6, 44.8, 1433 }, note = "The cave is at (Redridge Mountains 20,27), soloable at Lv 20; scout and clear the mobs along the way before taking the quest, since dying and releasing midway fails it." },
    [1700] = { n = "Grimand Elmore", cn = "Grimand Elmore", l = 28, r = 20, f = "A", races = { 1 }, s = { { 5413, "Furen Longbeard", "Stormwind City", 64.6, 37.2, 1453 } }, e = { 1416, "Grimand Elmore", "Stormwind City", 59.7, 33.8, 1453 }, note = "One step of the Dwarf version of the Fire Hardened Mail chain; you must first finish the chain that starts with \"Yorus Barleybrew\"; other races each have their own follow-up version." },
    [1701] = { n = "Fire Hardened Mail", cn = "Fire Hardened Mail", l = 28, r = 20, f = "A", s = { { 5413, "Furen Longbeard", "Stormwind City", 64.6, 37.2, 1453 } }, e = { 5413, "Furen Longbeard", "Stormwind City", 64.6, 37.2, 1453 }, note = "Scorched Spider Fang x50 drop from leeches and cave lurkers at (Wetlands 54,64); Charred Horn x12 come from young chimaeras at (Stonetalon Mountains 33,72), while Electroplated Horns drop from chimaera matriarchs at the same spot — farm them together. After the breastplate, the head/hands/legs follow-ups are turned in to different NPCs depending on race." },
    [1702] = { n = "The Shieldsmith", cn = "The Shieldsmith", l = 22, r = 20, f = "A", s = { { 6166, "Yorus Barleybrew", "Redridge Mountains", 26.6, 44.8, 1433 } }, e = { 5413, "Furen Longbeard", "Stormwind City", 64.6, 37.2, 1453 }, items = { 6970 }, note = "Furen Longbeard is in Stormwind's Dwarven District (Stormwind 65,37)." },
    [1703] = { n = "Mathiel", cn = "Mathiel", l = 28, r = 20, f = "A", races = { 4 }, s = { { 5413, "Furen Longbeard", "Stormwind City", 64.6, 37.2, 1453 } }, e = { 6142, "Mathiel", "Darnassus", 59.2, 45.4, 1457 }, note = "Mathiel is on the Warrior's Terrace in Darnassus (Darnassus 59,45); available at Lv 20, and you can take it directly without Frahun's letter of introduction." },
    [1704] = { n = "Klockmort Spannerspan", cn = "Klockmort Spannerspan", l = 28, r = 20, f = "A", races = { 3, 7 }, s = { { 5413, "Furen Longbeard", "Stormwind City", 64.6, 37.2, 1453 } }, e = { 6169, "Klockmort Spannerspan", "Ironforge", 68.2, 46.2, 1455 }, note = "Klockmort is in Ironforge's Tinker Town (Ironforge 68,46), near the engineering trainer." },
    [1705] = { n = "Burning Blood", cn = "Burning Blood", l = 28, r = 20, f = "A", s = { { 1416, "Grimand Elmore", "Stormwind City", 59.7, 33.8, 1453 } }, e = { 1416, "Grimand Elmore", "Stormwind City", 59.7, 33.8, 1453 }, note = "The filthy water creatures spawn at the cave mouth (Redridge Mountains 72,74), the same area as the mobs for step 3 of the \"Forest Worgen\" chain - clear them on the way." },
    [1706] = { n = "Grimand's Armor", cn = "Grimand's Armor", l = 30, r = 20, f = "A", s = { { 1416, "Grimand Elmore", "Stormwind City", 59.7, 33.8, 1453 } }, e = { 1416, "Grimand Elmore", "Stormwind City", 59.7, 33.8, 1453 }, items = { 6971 }, note = "Part of the multi-step Fire Hardened chain starting with \"Yorus Barleybrew\"; the other Fire Hardened pieces (head/hands/legs) unlock one by one only after the chest quest is done." },
    [1708] = { n = "Iron Coral", cn = "Iron Coral", l = 29, r = 20, f = "A", s = { { 6169, "Klockmort Spannerspan", "Ironforge", 68.2, 46.2, 1455 } }, e = { 6169, "Klockmort Spannerspan", "Ironforge", 68.2, 46.2, 1455 }, note = "The iron coral is south of Menethil Harbor (Wetlands 10,66), surrounded by about 28 murlocs, so plan your pull route ahead; can be combined with the Wetlands leg of the \"Dark Chains\" quest." },
    [1709] = { n = "Klockmort's Creation", cn = "Klockmort's Creation", l = 30, r = 20, f = "A", s = { { 6169, "Klockmort Spannerspan", "Ironforge", 68.2, 46.2, 1455 } }, e = { 6169, "Klockmort Spannerspan", "Ironforge", 68.2, 46.2, 1455 }, items = { 6974 }, note = "One link of the multi-part Fire Hardened chain; the other Fire Hardened pieces (helm/gloves/legs) open only after the chest quest is done." },
    [1710] = { n = "Sunscorched Shells", cn = "Sunscorched Shells", l = 30, r = 20, f = "A", s = { { 6142, "Mathiel", "Darnassus", 59.2, 45.4, 1457 } }, e = { 6142, "Mathiel", "Darnassus", 59.2, 45.4, 1457 }, note = "The ramp up to the high plateau is at (Thousand Needles 14,33), marked by a big totem pole; the eggs are scattered on the plateau ground; the level 28-29 wyverns nearby are tough, so melee should be careful." },
    [1711] = { n = "Mathiel's Armor", cn = "Mathiel's Armor", l = 30, r = 20, f = "A", s = { { 6142, "Mathiel", "Darnassus", 59.2, 45.4, 1457 } }, e = { 6142, "Mathiel", "Darnassus", 59.2, 45.4, 1457 }, items = { 6973 }, note = "One link of the multi-part Fire Hardened chain; the other Fire Hardened pieces (helm/gloves/legs) open only after the chest quest is done." },
    [1712] = { n = "Cyclonian", cn = "Cyclonian", l = 40, r = 30, s = { { 6176, "Bath'rah the Windwatcher", "Alterac Mountains", 80.4, 66.8, 1416 } }, e = { 6176, "Bath'rah the Windwatcher", "Alterac Mountains", 80.4, 66.8, 1416 }, note = "For the Exile Essence, collect 8 each of three charms from elementals in the Arathi Highlands; troll tusks in Stranglethorn Vale share drops with \"Hunt for Yenniku\", so farm both quests together." },
    [1713] = { n = "The Summoning", cn = "The Summoning", l = 40, r = 30, s = { { 6176, "Bath'rah the Windwatcher", "Alterac Mountains", 80.4, 66.8, 1416 } }, e = { 6176, "Bath'rah the Windwatcher", "Alterac Mountains", 80.4, 66.8, 1416 }, note = "Hurricane is a level 40 elite elemental dealing mostly Nature damage; drink a Nature Protection Potion before engaging to absorb most of it, soloable at 40; watch out for knockbacks so you don't get knocked off the platform." },
    [1714] = { n = "Essence of the Exile", cn = "Essence of the Exile", l = 37, r = 30, s = { { 89931, "Bathras's Great Cauldron", "Alterac Mountains", 79.3, 66.7, 1416 } }, e = { 89931, "Bathras's Great Cauldron", "Alterac Mountains", 79.3, 66.7, 1416 }, items = { 6851 }, note = "The three charms drop from elementals near the three binding circles in west/north/east Arathi, with good drop rates; you don't need to start the \"The Trapped Princess\" chain first." },
    [1715] = { n = "The Slaughtered Lamb", cn = "The Slaughtered Lamb", l = 10, r = 10, f = "A", races = { 1, 7 }, s = { { 6120, "Lago Blackwrench", "Ironforge", 47.6, 9.6, 1455 } }, e = { 6122, "Gakin the Darkbinder", "Stormwind City", 39.2, 85.2, 1453 }, note = "This chain ends with learning Summon Voidwalker; the summoning circle is in the basement of The Slaughtered Lamb inn — go downstairs, turn left and go to the end; there is also an easy-to-miss hidden passage in the bottom-left corner." },
    [1716] = { n = "Devourer of Souls", cn = "Devourer of Souls", l = 20, r = 20, f = "A", races = { 1, 7 }, s = { { 6122, "Gakin the Darkbinder", "Stormwind City", 39.2, 85.2, 1453 } }, e = { 6244, "Takar the Seer", "The Barrens", 49.2, 57, 1413 }, note = "The target camp (The Barrens 49,57) is by the fork in the road east of Camp Taurajo; go past the lizard herds until you see two white tents; Alliance players should travel via Ashenvale, picking up the Astranaar flight point on the way." },
    [1717] = { n = "Gakin's Summons", cn = "Gakin's Summons", l = 20, r = 20, f = "A", races = { 1, 7 }, s = { { 6120, "Lago Blackwrench", "Ironforge", 47.6, 9.6, 1455 } }, e = { 6122, "Gakin the Darkbinder", "Stormwind City", 39.2, 85.2, 1453 }, note = "Starting quest of the succubus chain; the safest route is the boat from Stormwind to Auberdine and then walking, opening flight paths along the way." },
    [1718] = { n = "The Islander", cn = "The Islander", l = 30, r = 30, s = { { 3041, "Torm Ragetotem", "Thunder Bluff", 57.6, 87.2, 1456 }, { 3354, "Sorek", "Orgrimmar", 80.2, 32.4, 1454 }, { 4595, "Baltus Fowler", "Undercity", 47.2, 17, 1458 }, { 5113, "Kelv Sternhammer", "Ironforge", 70, 90.6, 1455 }, { 5479, "Wu Shen", "Stormwind City", 80.5, 59.9, 1453 } }, e = { 6236, "Klannoc Macleod", "The Barrens", 68.6, 49, 1413 }, note = "The islet is at (Stranglethorn Vale 68,49); you must wade over along the shallows from (Stranglethorn Vale 66,48), or you'll take fatigue damage. The level 26-27 challengers come one at a time, 15-20 seconds apart — take them down one by one." },
    [1719] = { n = "The Affray", cn = "The Affray", l = 30, r = 30, s = { { 6236, "Klannoc Macleod", "The Barrens", 68.6, 49, 1413 } }, e = { 6236, "Klannoc Macleod", "The Barrens", 68.6, 49, 1413 }, spells = { 2458 }, note = "A challenger joins every 10-15 seconds; when low on health use Demoralizing Shout for control and then bandage; Big Will is immune to Fear, so save your burst; completing it teaches Berserker Stance and Intercept and opens the Whirlwind Weapon chain." },
    [1738] = { n = "Heartswood", cn = "Heartswood", l = 20, r = 20, f = "A", races = { 1, 7 }, s = { { 6244, "Takar the Seer", "The Barrens", 49.2, 57, 1413 } }, e = { 6122, "Gakin the Darkbinder", "Stormwind City", 39.2, 85.2, 1453 }, note = "The Concord Tree is at (Ashenvale 31,32); clear the area first, then click the tree to get the item; hugging the wall from the Astranaar side avoids a lot of mobs; turn in back in Stormwind afterward, don't turn in at the wrong place." },
    [1739] = { n = "The Binding", cn = "The Binding", l = 20, r = 20, f = "A", races = { 1, 7 }, s = { { 6122, "Gakin the Darkbinder", "Stormwind City", 39.2, 85.2, 1453 } }, e = { 6122, "Gakin the Darkbinder", "Stormwind City", 39.2, 85.2, 1453 }, items = { 22243 }, spells = { 712 }, note = "Done at the circle in the inn basement, same as the Voidwalker; use the heartwood from the previous step to summon a level 20 Succubus and let your Voidwalker tank it — soloable at level 20." },
    [1740] = { n = "The Orb of Soran'ruk", cn = "The Orb of Soran'ruk", l = 25, r = 20, s = { { 6247, "Doan Karhan", "The Barrens", 49.2, 57.2, 1413 } }, e = { 6247, "Doan Karhan", "The Barrens", 49.2, 57.2, 1413 }, items = { 6898, 15109 }, note = "Remember you need to run two dungeons: 3 small shards from Blackfathom Deeps and 1 large shard from Shadowfang Keep; form a group in advance and do it all in one go." },
    [1758] = { n = "Tome of the Cabal", cn = "Tome of the Cabal", l = 30, r = 30, f = "A", races = { 1, 7 }, s = { { 6251, "Strahad Farsan", "The Barrens", 62.6, 35.4, 1413 } }, e = { 6294, "Krom Stoutarm", "Ironforge", 74.2, 9.8, 1455 }, note = "The Mildewed Tome is at (Dun Morogh 34,72); bring it back to the Ironforge library (Ironforge 79,4) to turn in." },
    [1778] = { n = "The Tome of Divinity", cn = "The Tome of Divinity", l = 13, r = 12, f = "A", races = { 3 }, s = { { 6175, "John Turner", "Ironforge", 23.3, 61.9, 1455 } }, e = { 6179, "Tiza Battleforge", "Ironforge", 27.4, 12, 1455 } },
    [1779] = { n = "The Tome of Divinity", cn = "The Tome of Divinity", l = 13, r = 12, f = "A", races = { 3 }, s = { { 6179, "Tiza Battleforge", "Ironforge", 27.4, 12, 1455 } }, e = { 6178, "Muiredon Battleforge", "Ironforge", 23.6, 8.6, 1455 }, note = "The target body is on the lonely island hill (Dun Morogh 78,58), just a few steps away." },
    [1780] = { n = "The Tome of Divinity", cn = "The Tome of Divinity", l = 13, r = 12, f = "A", races = { 1 }, s = { { 6174, "Stephanie Turner", "Stormwind City", 63.8, 72.2, 1453 } }, e = { 6171, "Duthorian Rall", "Stormwind City", 50.5, 47.5, 1453 } },
    [1781] = { n = "The Tome of Divinity", cn = "The Tome of Divinity", l = 13, r = 12, f = "A", races = { 1 }, s = { { 6171, "Duthorian Rall", "Stormwind City", 50.5, 47.5, 1453 } }, e = { 6173, "Gazin Tenorm", "Stormwind City", 49.5, 45.0, 1453 } },
    [1782] = { n = "Furen's Armor", cn = "Furen's Armor", l = 28, r = 20, f = "A", s = { { 5413, "Furen Longbeard", "Stormwind City", 64.6, 37.2, 1453 } }, e = { 5413, "Furen Longbeard", "Stormwind City", 64.6, 37.2, 1453 }, items = { 6972 } },
    [1783] = { n = "The Tome of Divinity", cn = "The Tome of Divinity", l = 13, r = 12, f = "A", races = { 3 }, s = { { 6178, "Muiredon Battleforge", "Ironforge", 23.6, 8.6, 1455 } }, e = { 6177, "Narm Faulk", "Dun Morogh", 78.2, 58, 1426 }, note = "Before leaving, bind your hearthstone to Ironforge or Stormwind to save a cross-map run; the remains are at (Dun Morogh 78,58), and you then need to kill Dark Iron dwarves for the manuscript." },
    [1784] = { n = "The Tome of Divinity", cn = "The Tome of Divinity", l = 13, r = 12, f = "A", races = { 3 }, s = { { 6177, "Narm Faulk", "Dun Morogh", 78.2, 58, 1426 } }, e = { 6178, "Muiredon Battleforge", "Ironforge", 23.6, 8.6, 1455 }, note = "Dark Iron Spies are in the nearby area; kill a few for the manuscript - the actual drop rate is higher than described, don't worry." },
    [1785] = { n = "The Tome of Divinity", cn = "The Tome of Divinity", l = 13, r = 12, f = "A", races = { 3 }, s = { { 6178, "Muiredon Battleforge", "Ironforge", 23.6, 8.6, 1455 } }, e = { 6179, "Tiza Battleforge", "Ironforge", 27.4, 12, 1455 }, spells = { 7328 } },
    [1786] = { n = "The Tome of Divinity", cn = "The Tome of Divinity", l = 13, r = 12, f = "A", races = { 1 }, s = { { 6173, "Gazin Tenorm", "Stormwind City", 49.5, 45.0, 1453 } }, e = { 6172, "Henze Faulk", "Elwynn Forest", 72.6, 51.4, 1429 }, note = "Henze Faulk (Elwynn Forest 72,51); the Defias nearby can be pulled one at a time, not difficult." },
    [1787] = { n = "The Tome of Divinity", cn = "The Tome of Divinity", l = 13, r = 12, f = "A", races = { 1 }, s = { { 6172, "Henze Faulk", "Elwynn Forest", 72.6, 51.4, 1429 } }, e = { 6173, "Gazin Tenorm", "Stormwind City", 49.5, 45.0, 1453 }, note = "The Defias Traitor mage is right by Mirror Lake outside Stormwind's south gate; kill one or two and the manuscript usually drops." },
    [1788] = { n = "The Tome of Divinity", cn = "The Tome of Divinity", l = 13, r = 12, f = "A", races = { 1 }, s = { { 6173, "Gazin Tenorm", "Stormwind City", 49.5, 45.0, 1453 } }, e = { 6171, "Duthorian Rall", "Stormwind City", 50.5, 47.5, 1453 }, spells = { 7328 } },
    [1789] = { n = "The Symbol of Life", cn = "The Symbol of Life", l = 12, r = 12, f = "A", races = { 3 }, s = { { 6179, "Tiza Battleforge", "Ironforge", 27.4, 12, 1455 } }, e = { 6179, "Tiza Battleforge", "Ironforge", 27.4, 12, 1455 }, items = { 6866 }, note = "If you lose the quest item along the way, Tisa Battleforge in Ironforge will hand out another for free, no extra requirements." },
    [1790] = { n = "The Symbol of Life", cn = "The Symbol of Life", l = 12, r = 12, f = "A", races = { 1 }, s = { { 6171, "Duthorian Rall", "Stormwind City", 50.5, 47.5, 1453 } }, e = { 6171, "Duthorian Rall", "Stormwind City", 50.5, 47.5, 1453 }, items = { 6866 }, note = "Human version: if you lose the quest item, go back to Stormwind Cathedral and get another from Duthorian Rall." },
    [1791] = { n = "The Windwatcher", cn = "The Windwatcher", l = 30, r = 30, s = { { 6236, "Klannoc Macleod", "The Barrens", 68.6, 49, 1413 } }, e = { 6176, "Bath'rah the Windwatcher", "Alterac Mountains", 80.4, 66.8, 1416 }, note = "Watcher Bathran (Alterac Mountains 81,67): from Hillsbrad Foothills follow the river north into Alterac; easier than taking the main road around the mob groups." },
    [1792] = { n = "Whirlwind Weapon", cn = "Whirlwind Weapon", l = 40, r = 30, s = { { 6176, "Bath'rah the Windwatcher", "Alterac Mountains", 80.4, 66.8, 1416 } }, e = { 6176, "Bath'rah the Windwatcher", "Alterac Mountains", 80.4, 66.8, 1416 }, items = { 6975, 6977, 6976 }, note = "Requires the two Berserker Stance steps (Islanders and Trial of Combat) first; maxing the new weapon skill only takes about ten minutes, no worries." },
    [1793] = { n = "The Tome of Valor", cn = "The Tome of Valor", l = 20, r = 20, f = "A", s = { { 6171, "Duthorian Rall", "Stormwind City", 50.5, 47.5, 1453 } }, e = { 6171, "Duthorian Rall", "Stormwind City", 50.5, 47.5, 1453 }, items = { 6776 }, note = "Obtained from Duthorian Rall in the Stormwind Cathedral; he has a blue question mark overhead rather than a yellow exclamation point, so don't miss it; if you abandon midway, you can pick it up again from the previous step's NPC." },
    [1794] = { n = "The Tome of Valor", cn = "The Tome of Valor", l = 20, r = 20, f = "A", s = { { 6179, "Tiza Battleforge", "Ironforge", 27.4, 12, 1455 } }, e = { 6179, "Tiza Battleforge", "Ironforge", 27.4, 12, 1455 }, items = { 6776 } },
    [1795] = { n = "The Binding", cn = "The Binding", l = 30, r = 30, s = { { 6251, "Strahad Farsan", "The Barrens", 62.6, 35.4, 1413 } }, e = { 6251, "Strahad Farsan", "The Barrens", 62.6, 35.4, 1413 }, items = { 22244 }, spells = { 691 }, note = "The summoning spot is in the warlock tent above the Ratchet flight point; you can fight with your own pet out (this demon doesn't count as your summon); if you fail, abandon the quest and pick it up again from Strahad Farsan." },
    [1796] = { n = "Components for the Enchanted Gold Bloodrobe", cn = "Components for the Enchanted Gold Bloodrobe", l = 31, r = 31, s = { { 6266, "Menara Voidrender", "The Barrens", 62.4, 35.4, 1413 } }, e = { 6266, "Menara Voidrender", "The Barrens", 62.4, 35.4, 1413 }, note = "The Arcane Robe must be made by a tailor and the pattern is rare — buying one on the Auction House is easier. Horde: when turning in, bring a Gold Bar to Booty Bay to pick up the follow-up. Farming it yourself: kill Dark Strand Voidwalkers in the northern Darkshore tower; the drop rate is about 1.25%, so be patient." },
    [1798] = { n = "Seeking Strahad", cn = "Seeking Strahad", l = 30, r = 30, f = "A", races = { 1, 7 }, s = { { 6122, "Gakin the Darkbinder", "Stormwind City", 39.2, 85.2, 1453 }, { 6120, "Lago Blackwrench", "Ironforge", 47.6, 9.6, 1455 } }, e = { 6251, "Strahad Farsan", "The Barrens", 62.6, 35.4, 1413 }, note = "This step is mostly running; unlocking all the flight paths along the way first makes it much easier." },
    [1799] = { n = "Fragments of the Orb of Orahil", cn = "Fragments of the Orb of Orahil", l = 40, r = 35, s = { { 6266, "Menara Voidrender", "The Barrens", 62.4, 35.4, 1413 } }, e = { 6546, "Tabetha", "Dustwallow Marsh", 46, 57, 1445 }, note = "The Infernal Orb doesn't come from infernals; it drops from Burning Blade Summoners; after getting the orb you must go to Tabetha's house (Dustwallow Marsh 46,57) first before continuing — doing it out of order means redoing it." },
    [1801] = { n = "Tome of the Cabal", cn = "Tome of the Cabal", l = 30, r = 30, f = "H", races = { 2, 5, 8 }, s = { { 6251, "Strahad Farsan", "The Barrens", 62.6, 35.4, 1413 } }, e = { 6293, "Jorah Annison", "Undercity", 76, 37.6, 1458 }, note = "The starting NPC is in the shop opposite the Magic Quarter in Undercity (Undercity 76,38)." },
    [1802] = { n = "Tome of the Cabal", cn = "Tome of the Cabal", l = 30, r = 30, f = "A", races = { 1, 7 }, s = { { 6294, "Krom Stoutarm", "Ironforge", 74.2, 9.8, 1455 } }, e = { 6294, "Krom Stoutarm", "Ironforge", 74.2, 9.8, 1455 }, note = "The Tattered Manuscript is deep in the cave (Thousand Needles 43,33) — turn right inside and follow the loop; the Moldy Tome is in a hut at the seaside murloc camp (Hillsbrad Foothills 28,73). Recommended kiting approach: send your voidwalker into the camp to grab it, sacrifice it when low and just run." },
    [1803] = { n = "Tome of the Cabal", cn = "Tome of the Cabal", l = 30, r = 30, f = "H", races = { 2, 5, 8 }, s = { { 6293, "Jorah Annison", "Undercity", 76, 37.6, 1458 } }, e = { 6293, "Jorah Annison", "Undercity", 76, 37.6, 1458 } },
    [1804] = { n = "Tome of the Cabal", cn = "Tome of the Cabal", l = 30, r = 30, f = "A", races = { 1, 7 }, s = { { 6294, "Krom Stoutarm", "Ironforge", 74.2, 9.8, 1455 } }, e = { 6251, "Strahad Farsan", "The Barrens", 62.6, 35.4, 1413 }, note = "The staff-dropping Dragonmaw casters are at the Angerfang Encampment (Wetlands 49,45); Shadowwarders drop it within a few kills, easy fights." },
    [1805] = { n = "Tome of the Cabal", cn = "Tome of the Cabal", l = 30, r = 30, f = "H", races = { 2, 5, 8 }, s = { { 6293, "Jorah Annison", "Undercity", 76, 37.6, 1458 } }, e = { 6251, "Strahad Farsan", "The Barrens", 62.6, 35.4, 1413 }, note = "The Dragonmaw orcs are at Angerfang Encampment (Wetlands 51,45): from Hammerfall in Arathi, follow the road south into the Wetlands; entering through the camp's back door (Wetlands 51,45) is quickest; note only caster mobs drop the quest staff." },
    [1806] = { n = "The Test of Righteousness", cn = "The Test of Righteousness", l = 22, r = 20, f = "A", races = { 1, 3 }, s = { { 6181, "Jordan Stilwell", "Dun Morogh", 52.4, 36.8, 1426 } }, e = { 6181, "Jordan Stilwell", "Dun Morogh", 52.4, 36.8, 1426 }, items = { 6953 }, note = "Classic Lv 20 Paladin quest that requires running three dungeons; it's a lot of work, but the reward weapon stays relevant until Lv 30." },
    [1818] = { n = "Speak with Dillinger", cn = "Speak with Dillinger", l = 10, r = 10, f = "H", s = { { 2131, "Austil de Mon", "Tirisfal Glades", 61.8, 52.4, 1420 }, { 4595, "Baltus Fowler", "Undercity", 47.4, 17.3, 1458 } }, e = { 1496, "Deathguard Dillinger", "Tirisfal Glades", 58.2, 51.4, 1420 }, note = "Starting NPC of the Horde warrior-only chain (Tirisfal Glades - Brill 58,51)." },
    [1819] = { n = "Ulag the Cleaver", cn = "Ulag the Cleaver", l = 10, r = 10, f = "H", s = { { 1496, "Deathguard Dillinger", "Tirisfal Glades", 58.2, 51.4, 1420 } }, e = { 1496, "Deathguard Dillinger", "Tirisfal Glades", 58.2, 51.4, 1420 }, spells = { 71 }, note = "In the graveyard north of Dillinger, there's a skull slab on the ground on the left side of the road in front of the tomb; click it to open the tomb door and release the mobs; watch out for patrolling elite guards killing them first, which won't count for the quest." },
    [1820] = { n = "Speak with Coleman", cn = "Speak with Coleman", l = 10, r = 10, f = "H", s = { { 1496, "Deathguard Dillinger", "Tirisfal Glades", 58.2, 51.4, 1420 } }, e = { 1500, "Coleman Farthing", "Tirisfal Glades", 61.8, 52.4, 1420 }, note = "Coleman is in Gallows' End Tavern, opposite Innkeeper Renee; get close and the question mark shows on the minimap." },
    [1821] = { n = "Agamand Heirlooms", cn = "Agamand Heirlooms", l = 11, r = 10, f = "H", s = { { 1500, "Coleman Farthing", "Tirisfal Glades", 61.8, 52.4, 1420 } }, e = { 1500, "Coleman Farthing", "Tirisfal Glades", 61.8, 52.4, 1420 }, note = "Crypt entrance (Tirisfal Glades 52,27); the quest item is on a weapon rack inside the crypt; pull at most three at a time, use Hamstring to slow and kite them; soloable at level 10." },
    [1822] = { n = "Heirloom Weapon", cn = "Heirloom Weapon", l = 11, r = 10, f = "H", s = { { 1500, "Coleman Farthing", "Tirisfal Glades", 61.8, 52.4, 1420 } }, e = { 1500, "Coleman Farthing", "Tirisfal Glades", 61.8, 52.4, 1420 }, items = { 7115, 7117, 7116, 7118 } },
    [1823] = { n = "Speak with Ruga", cn = "Speak with Ruga", l = 20, r = 20, f = "H", s = { { 3041, "Torm Ragetotem", "Thunder Bluff", 57.6, 87.2, 1456 }, { 3354, "Sorek", "Orgrimmar", 80.2, 32.4, 1454 }, { 4595, "Baltus Fowler", "Undercity", 47.2, 17, 1458 } }, e = { 6394, "Ruga Ragetotem", "The Barrens", 44.6, 59.4, 1413 }, note = "Ruga Ragetotem (The Barrens - Camp Taurajo 44,59); this is the start of the long Horde warrior chain; doing it with a set group gets you good level 20 armor, while soloing takes a long time." },
    [1824] = { n = "Trial at the Field of Giants", cn = "Trial at the Field of Giants", l = 20, r = 20, f = "H", s = { { 6394, "Ruga Ragetotem", "The Barrens", 44.6, 59.4, 1413 } }, e = { 6394, "Ruga Ragetotem", "The Barrens", 44.6, 59.4, 1413 }, items = { 7120 }, note = "Prioritize the creepers on the east side (The Barrens 48,70) and avoid the swarm mobs (they split into adds on death). The tentacles stay valid for about 15 minutes after being removed, so hurry. Pairs well with the 'Egg Hunt' quest from the Crossroads." },
    [1825] = { n = "Speak with Thun'grim", cn = "Speak with Thun'grim", l = 20, r = 20, f = "H", s = { { 6394, "Ruga Ragetotem", "The Barrens", 44.6, 59.4, 1413 } }, e = { 5878, "Thun'grim Firegaze", "The Barrens", 57.2, 30.2, 1413 }, note = "He's on the hilltop (The Barrens 57,30); the best route up starts at (The Barrens 54,28); don't search the mine and tower camp below the hill." },
    [1838] = { n = "Brutal Armor", cn = "Brutal Armor", l = 30, r = 20, f = "H", s = { { 5878, "Thun'grim Firegaze", "The Barrens", 57.2, 30.2, 1413 } }, e = { 5878, "Thun'grim Firegaze", "The Barrens", 57.2, 30.2, 1413 }, note = "Smoky Iron Ingots are in the Stonetalon Mountains mine (Stonetalon Mountains 74,60), dropped by kobolds, soloable in your 20s; completing it opens four sub-quests: gauntlets/breastplate/leggings/helm." },
    [1839] = { n = "Ula'elek and the Brutal Gauntlets", cn = "Ula'elek and the Brutal Gauntlets", l = 30, r = 20, f = "H", s = { { 5878, "Thun'grim Firegaze", "The Barrens", 57.2, 30.2, 1413 } }, e = { 6408, "Ula'elek", "Durotar", 56.2, 74.4, 1411 }, note = "Yuralek is in Sen'jin Village (Durotar - Sen'jin Village 56,75)." },
    [1840] = { n = "Orm Stonehoof and the Brutal Helm", cn = "Orm Stonehoof and the Brutal Helm", l = 30, r = 20, f = "H", s = { { 5878, "Thun'grim Firegaze", "The Barrens", 57.2, 30.2, 1413 } }, e = { 6410, "Orm Stonehoof", "Thunder Bluff", 39, 55.8, 1456 }, note = "After the Savage chest piece, take this from Orm Stonehoof on the hilltop; warrior head gear is scarce at low levels, so this one is worth doing." },
    [1841] = { n = "Velora Nitely and the Brutal Legguards", cn = "Velora Nitely and the Brutal Legguards", l = 30, r = 20, f = "H", s = { { 5878, "Thun'grim Firegaze", "The Barrens", 57.2, 30.2, 1413 } }, e = { 6411, "Velora Nitely", "Undercity", 62.4, 39.2, 1458 }, note = "Verola is on the Wetlands side: from Tarren Mill follow the main road through Arathi; the route is fairly safe, but watch for raptors along the way." },
    [1842] = { n = "Satyr Hooves", cn = "Satyr Hooves", l = 30, r = 20, f = "H", s = { { 6408, "Ula'elek", "Durotar", 56.2, 74.4, 1411 } }, e = { 6408, "Ula'elek", "Durotar", 56.2, 74.4, 1411 }, note = "Demon Hooves drop from the satyrs of Satyrnaar at close to 100%; pull them one by one along the edge of the camp." },
    [1843] = { n = "Brutal Gauntlets", cn = "Brutal Gauntlets", l = 30, r = 20, f = "H", s = { { 6408, "Ula'elek", "Durotar", 56.2, 74.4, 1411 } }, e = { 6408, "Ula'elek", "Durotar", 56.2, 74.4, 1411 }, items = { 7129 } },
    [1844] = { n = "Chimaeric Horn", cn = "Chimaeric Horn", l = 30, r = 20, f = "H", s = { { 6410, "Orm Stonehoof", "Thunder Bluff", 39, 55.8, 1456 } }, e = { 6410, "Orm Stonehoof", "Thunder Bluff", 39, 55.8, 1456 }, note = "Chimaera Matriarchs roam the southern cliffs of the Charred Vale; they're noticeably bigger than the young, so they're easy to spot." },
    [1845] = { n = "Brutal Helm", cn = "Brutal Helm", l = 30, r = 20, f = "H", s = { { 6410, "Orm Stonehoof", "Thunder Bluff", 39, 55.8, 1456 } }, e = { 6410, "Orm Stonehoof", "Thunder Bluff", 39, 55.8, 1456 }, items = { 7130 }, note = "Head gear is scarce at low levels, so this helm is worth getting; this chain is warrior-only, paladins can't take it." },
    [1846] = { n = "Dragonmaw Shinbones", cn = "Dragonmaw Shinbones", l = 30, r = 20, f = "H", s = { { 6411, "Velora Nitely", "Undercity", 62.4, 39.2, 1458 } }, e = { 6411, "Velora Nitely", "Undercity", 62.4, 39.2, 1458 }, note = "The Dragonmaw orcs are at the foot of the hills in central Wetlands, across the bridge south of Arathi; after a shinbone drops, right-click it to test its strength; not every one passes, so gather a few spares." },
    [1847] = { n = "Brutal Legguards", cn = "Brutal Legguards", l = 30, r = 20, f = "H", s = { { 6411, "Velora Nitely", "Undercity", 62.4, 39.2, 1458 } }, e = { 6411, "Velora Nitely", "Undercity", 62.4, 39.2, 1458 }, items = { 7132 } },
    [1848] = { n = "Brutal Hauberk", cn = "Brutal Hauberk", l = 30, r = 20, f = "H", s = { { 5878, "Thun'grim Firegaze", "The Barrens", 57.2, 30.2, 1413 } }, e = { 5878, "Thun'grim Firegaze", "The Barrens", 57.2, 30.2, 1413 }, items = { 7133 }, note = "Unlocks three follow-ups (helm/gauntlets/legs); the hub step of the whole Savage armor chain." },
    [1858] = { n = "The Shattered Hand", cn = "The Shattered Hand", l = 13, r = 10, f = "H", races = { 2, 8 }, s = { { 6446, "Therzok", "Orgrimmar", 42.8, 53.4, 1454 } }, e = { 6446, "Therzok", "Orgrimmar", 42.8, 53.4, 1454 }, items = { 7298 }, note = "Get the key by using Pick Pocket on Gamon in the Orgrimmar inn; you can also bring Thieves' Tools and pick the lock (Pick Lock is learned at Lv 16)." },
    [1859] = { n = "Therzok", cn = "Therzok", l = 10, r = 10, f = "H", races = { 2, 8 }, s = { { 3170, "Kaplak", "Durotar", 52, 43.6, 1411 } }, e = { 6446, "Therzok", "Orgrimmar", 42.8, 53.4, 1454 }, note = "Undead/Troll rogues who can't get this step can skip it - go straight to the next NPC in Orgrimmar's Cleft of Shadow to continue the chain." },
    [1860] = { n = "Speak with Jennea", cn = "Speak with Jennea", l = 10, r = 10, f = "A", races = { 1, 7, 95 }, s = { { 328, "Zaldimar Wefhellt", "Elwynn Forest", 43.2, 66.2, 1429 } }, e = { 5497, "Jennea Cannon", "Stormwind City", 49.6, 85.8, 1453 }, note = "Go to the Wizard's Sanctum in Stormwind's Mage Quarter and speak with Jennea." },
    [1861] = { n = "Mirror Lake", cn = "Mirror Lake", l = 10, r = 10, f = "A", races = { 1, 7, 95 }, s = { { 5497, "Jennea Cannon", "Stormwind City", 49.6, 85.8, 1453 } }, e = { 5497, "Jennea Cannon", "Stormwind City", 49.6, 85.8, 1453 }, items = { 7508, 9513 }, note = "Mirror Lake is at (Elwynn Forest 29,61)." },
    [1879] = { n = "Speak with Bink", cn = "Speak with Bink", l = 10, r = 10, f = "A", races = { 1, 7 }, s = { { 1228, "Magis Sparkmantle", "Dun Morogh", 47.4, 52, 1426 } }, e = { 5144, "Bink", "Ironforge", 27, 8.2, 1455 } },
    [1880] = { n = "Mage-tastic Gizmonitor", cn = "Mage-tastic Gizmonitor", l = 10, r = 10, f = "A", races = { 1, 7 }, s = { { 5144, "Bink", "Ironforge", 27, 8.2, 1455 } }, e = { 5144, "Bink", "Ironforge", 27, 8.2, 1455 }, items = { 7507, 9514 }, note = "The document storage unit is in the toolbox under the table on the ground floor of the building with the elevator (Dun Morogh 27,36)." },
    [1881] = { n = "Speak with Anastasia", cn = "Speak with Anastasia", l = 10, r = 10, f = "H", races = { 5, 8 }, s = { { 2128, "Cain Firesong", "Tirisfal Glades", 61.8, 52.4, 1420 } }, e = { 4568, "Anastasia Hartwell", "Undercity", 85, 10.2, 1458 }, note = "Anastasia is in Undercity (Undercity 85,10); even if you skip this step, you can still take the follow-up quests directly." },
    [1882] = { n = "The Balnir Farmstead", cn = "The Balnir Farmstead", l = 10, r = 10, f = "H", races = { 5, 8 }, s = { { 4568, "Anastasia Hartwell", "Undercity", 85, 10.2, 1458 } }, e = { 4568, "Anastasia Hartwell", "Undercity", 85, 10.2, 1458 }, items = { 7507, 9514 }, note = "The Balnir Farmstead is east of Brill (Tirisfal Glades 76,60); the Balnir Snapdragons you need are actually in the herb garden, don't search the farmhouse." },
    [1883] = { n = "Speak with Un'thuwa", cn = "Speak with Un'thuwa", l = 10, r = 10, f = "H", races = { 2, 5, 8 }, s = { { 3049, "Thurston Xane", "Thunder Bluff", 25, 20.6, 1456 }, { 7311, "Uthel'nay", "Orgrimmar", 39, 86, 1454 } }, e = { 5880, "Un'Thuwa", "Durotar", 56.2, 75, 1411 } },
    [1884] = { n = "Ju-Ju Heaps", cn = "Ju-Ju Heaps", l = 10, r = 10, f = "H", races = { 2, 5, 8 }, s = { { 5880, "Un'Thuwa", "Durotar", 56.2, 75, 1411 } }, e = { 5880, "Un'Thuwa", "Durotar", 56.2, 75, 1411 }, items = { 7508, 9513 }, note = "The bone piles are in the huts on Zalazane's island: two next to him and a few more north of the camp; they look like ordinary skeleton piles, but you can click them." },
    [1885] = { n = "Mennet Carkad", cn = "Mennet Carkad", l = 10, r = 10, f = "H", races = { 5 }, s = { { 2130, "Marion Call", "Tirisfal Glades", 61.6, 52, 1420 } }, e = { 6467, "Mennet Carkad", "Undercity", 83.2, 69, 1458 }, note = "Undead rogue-only quest." },
    [1886] = { n = "The Deathstalkers", cn = "The Deathstalkers", l = 13, r = 10, f = "H", races = { 5 }, s = { { 6467, "Mennet Carkad", "Undercity", 83.2, 69, 1458 } }, e = { 6467, "Mennet Carkad", "Undercity", 83.2, 69, 1458 }, note = "The target patrols the main road between Undercity and Silverpine Forest; soloable at Lv 12-14, bring some food and drink." },
    [1898] = { n = "The Deathstalkers", cn = "The Deathstalkers", l = 13, r = 10, f = "H", races = { 5 }, s = { { 6467, "Mennet Carkad", "Undercity", 83.2, 69, 1458 } }, e = { 6522, "Andron Gant", "Undercity", 54.8, 75.6, 1458 }, note = "The target is in the Undercity Apothecarium (Undercity 55,76)." },
    [1899] = { n = "The Deathstalkers", cn = "The Deathstalkers", l = 13, r = 10, f = "H", races = { 5 }, s = { { 6522, "Andron Gant", "Undercity", 54.8, 75.6, 1458 } }, e = { 6467, "Mennet Carkad", "Undercity", 83.2, 69, 1458 }, note = "Remember to take the book from the bookshelf behind him before you leave; the shelf may not be interactable while grouped - doing it solo is safest." },
    [1919] = { n = "Report to Jennea", cn = "Report to Jennea", l = 15, r = 15, f = "A", races = { 1, 7, 95 }, s = { { 328, "Zaldimar Wefhellt", "Elwynn Forest", 43.2, 66.2, 1429 }, { 7312, "Dink", "Ironforge", 26.8, 8.4, 1455 }, { 1228, "Magis Sparkmantle", "Dun Morogh", 47.4, 52, 1426 } }, e = { 5497, "Jennea Cannon", "Stormwind City", 49.6, 85.8, 1453 }, note = "Jennea is at the top of the tower in the Mage Quarter (Stormwind City 50,86): climb the spiral stairs along the side of the tower and go through the portal at the end of the blue carpet." },
    [1920] = { n = "Investigate the Blue Recluse", cn = "Investigate the Blue Recluse", l = 16, r = 15, f = "A", races = { 1, 7, 95 }, s = { { 5497, "Jennea Cannon", "Stormwind City", 49.6, 85.8, 1453 } }, e = { 5497, "Jennea Cannon", "Stormwind City", 49.6, 85.8, 1453 }, note = "Using the incantation in the basement summons only one, while using it on the first floor summons three at once; the safe approach is to move to the kitchen fireplace after each kill and recast, handling them one at a time." },
    [1921] = { n = "Gathering Materials", cn = "Gathering Materials", l = 15, r = 15, f = "A", races = { 1, 7, 95 }, s = { { 5497, "Jennea Cannon", "Stormwind City", 49.6, 85.8, 1453 } }, e = { 1309, "Wynne Larson", "Stormwind City", 51.8, 83.5, 1453 }, note = "The mine is at (Loch Modan 35,18): outer mobs are level 10-12, inside 12-14; the geomancers in the mine cast Fire Ward, so fire mages watch out for immunity." },
    [1938] = { n = "Ur's Treatise on Shadow Magic", cn = "Ur's Treatise on Shadow Magic", l = 28, r = 26, f = "A", races = { 1, 7, 95 }, s = { { 5694, "High Sorcerer Andromath", "Stormwind City", 48.7, 87.6, 1453 } }, e = { 5694, "High Sorcerer Andromath", "Stormwind City", 48.7, 87.6, 1453 }, note = "You don't need to kill Morganth at the top of the tower: keep left up the ramp to the top floor, the book is on the bookshelf on the left of the ramp; avoid his adds, grab it and go; the dogs in the cave burn mana, so save some." },
    [1939] = { n = "High Sorcerer Andromath", cn = "High Sorcerer Andromath", l = 26, r = 26, f = "A", races = { 1, 7, 95 }, s = { { 5144, "Bink", "Ironforge", 27, 8.2, 1455 }, { 5497, "Jennea Cannon", "Stormwind City", 49.6, 85.8, 1453 } }, e = { 5694, "High Sorcerer Andromath", "Stormwind City", 48.7, 87.6, 1453 }, note = "Andromath is not far from where the mage trainer portal lets out (Stormwind 49,88)." },
    [1940] = { n = "Pristine Spider Silk", cn = "Pristine Spider Silk", l = 26, r = 26, f = "A", races = { 1, 7, 95 }, s = { { 5694, "High Sorcerer Andromath", "Stormwind City", 48.7, 87.6, 1453 } }, e = { 1309, "Wynne Larson", "Stormwind City", 51.8, 83.5, 1453 } },
    [1941] = { n = "Manaweave Robe", cn = "Manaweave Robe", l = 15, r = 15, f = "A", s = { { 1309, "Wynne Larson", "Stormwind City", 51.8, 83.5, 1453 } }, e = { 1309, "Wynne Larson", "Stormwind City", 51.8, 83.5, 1453 }, items = { 7509 }, note = "Available at Lv 15; the mobs in Silver Stream Mine are tough for their level and respawn fast, and other players are often there too - grouping is safer." },
    [1942] = { n = "Astral Knot Garment", cn = "Astral Knot Garment", l = 26, r = 26, f = "A", s = { { 1309, "Wynne Larson", "Stormwind City", 51.8, 83.5, 1453 } }, e = { 1309, "Wynne Larson", "Stormwind City", 51.8, 83.5, 1453 }, items = { 7511, 9516 }, note = "Requires Lv 26; after turning in the Perfect Spider Silk from the previous step, wait a moment and the NPC will offer this step on its own." },
    [1943] = { n = "Speak with Deino", cn = "Speak with Deino", l = 26, r = 26, f = "H", races = { 2, 5, 8 }, s = { { 4568, "Anastasia Hartwell", "Undercity", 85, 10.2, 1458 } }, e = { 5885, "Deino", "Orgrimmar", 38.4, 85.8, 1454 }, note = "Deino is next to the first aid trainer in Orgrimmar (Orgrimmar 38,86); you can skip this step and take the follow-up directly, but doing it gives extra XP." },
    [1944] = { n = "Waters of Xavian", cn = "Waters of Xavian", l = 26, r = 26, f = "H", races = { 2, 5, 8 }, s = { { 5885, "Deino", "Orgrimmar", 38.4, 85.8, 1454 } }, e = { 5885, "Deino", "Orgrimmar", 38.4, 85.8, 1454 }, note = "The water source is at (Ashenvale 76,41): follow the river north of Splintertree Post to the waterfall where the two rivers meet, and go all the way in against the wall to collect; don't go deep east into Satyrnaar." },
    [1945] = { n = "Laughing Sisters", cn = "Laughing Sisters", l = 26, r = 26, f = "H", races = { 2, 5, 8 }, s = { { 5885, "Deino", "Orgrimmar", 38.4, 85.8, 1454 } }, e = { 3484, "Kil'hala", "The Barrens", 52.2, 31.6, 1413 }, note = "The Laughing Sisters are at (Ashenvale 58,50); they have very high frost resistance, so frost mages be warned." },
    [1946] = { n = "Nether-lace Garment", cn = "Nether-lace Garment", l = 26, r = 26, f = "H", s = { { 3484, "Kil'hala", "The Barrens", 52.2, 31.6, 1413 } }, e = { 3484, "Kil'hala", "The Barrens", 52.2, 31.6, 1413 }, items = { 7512, 9515 } },
    [1947] = { n = "Journey to the Marsh", cn = "Journey to the Marsh", l = 38, r = 30, s = { { 3048, "Ursyn Ghull", "Thunder Bluff", 25.6, 14.6, 1456 }, { 4568, "Anastasia Hartwell", "Undercity", 85, 10.2, 1458 }, { 5144, "Bink", "Ironforge", 27, 8.2, 1455 }, { 5497, "Jennea Cannon", "Stormwind City", 49.6, 85.8, 1453 }, { 5885, "Deino", "Orgrimmar", 38.4, 85.8, 1454 } }, e = { 6546, "Tabetha", "Dustwallow Marsh", 46, 57, 1445 }, note = "Tabetha's hut (Dustwallow Marsh 46,57): head south from Theramore along the main road, and turn onto the path when you see the ruined stone tower on the left." },
    [1948] = { n = "Items of Power", cn = "Items of Power", l = 40, r = 30, s = { { 6546, "Tabetha", "Dustwallow Marsh", 46, 57, 1445 } }, e = { 6546, "Tabetha", "Dustwallow Marsh", 46, 57, 1445 }, note = "The final staff quest requires finishing both this chain and \"Hidden Secrets\": first collect 10 Witherbark totem sticks, then visit the specified circles in Arathi in order." },
    [1949] = { n = "Hidden Secrets", cn = "Hidden Secrets", l = 38, r = 30, s = { { 6546, "Tabetha", "Dustwallow Marsh", 46, 57, 1445 } }, e = { 6548, "Magus Tirth", "Thousand Needles", 78.2, 75.8, 1441 }, note = "Before setting out, take the prerequisite \"Journey to the Marsh\" from a mage trainer, or Tabetha won't talk to you; grab the flight point in the village on the way." },
    [1950] = { n = "Get the Scoop", cn = "Get the Scoop", l = 30, r = 30, s = { { 6548, "Magus Tirth", "Thousand Needles", 78.2, 75.8, 1441 } }, e = { 6548, "Magus Tirth", "Thousand Needles", 78.2, 75.8, 1441 }, note = "The target is a chicken: click it and do the \"beckon\" emote to turn it back into human form, then talk to get the password; it's at the foot of the raceway tower (Tanaris 57,77)." },
    [1951] = { n = "Rituals of Power", cn = "Rituals of Power", l = 40, r = 30, s = { { 6548, "Magus Tirth", "Thousand Needles", 78.2, 75.8, 1441 } }, e = { 6546, "Tabetha", "Dustwallow Marsh", 46, 57, 1445 }, note = "The book is in the Scarlet Monastery Library, on the low-wall bookshelf in the last corridor before the final boss; carefully soloable at Lv 44, and a few Invisibility Potions make it safer." },
    [1952] = { n = "Mage's Wand", cn = "Mage's Wand", l = 40, r = 30, s = { { 6546, "Tabetha", "Dustwallow Marsh", 46, 57, 1445 } }, e = { 6546, "Tabetha", "Dustwallow Marsh", 46, 57, 1445 }, items = { 7514, 11263, 7513 }, note = "Tabetha only offers staff crafting after you finish both this chain and the \"Items of Power\" chain; she is out of the way, so grab the flight point early." },
    [1953] = { n = "Return to the Marsh", cn = "Return to the Marsh", l = 40, r = 35, s = { { 3048, "Ursyn Ghull", "Thunder Bluff", 25.6, 14.6, 1456 }, { 4568, "Anastasia Hartwell", "Undercity", 85, 10.2, 1458 }, { 5144, "Bink", "Ironforge", 27, 8.2, 1455 }, { 5497, "Jennea Cannon", "Stormwind City", 49.6, 85.8, 1453 }, { 5885, "Deino", "Orgrimmar", 38.4, 85.8, 1454 } }, e = { 6546, "Tabetha", "Dustwallow Marsh", 46, 57, 1445 }, note = "The Horde version is given by any mage trainer, available at Lv 30; Tabetha's hut is at (Dustwallow Marsh 46,57)." },
    [1954] = { n = "The Infernal Orb", cn = "The Infernal Orb", l = 40, r = 35, s = { { 6546, "Tabetha", "Dustwallow Marsh", 46, 57, 1445 } }, e = { 6546, "Tabetha", "Dustwallow Marsh", 46, 57, 1445 }, note = "The target mobs roam east of the Mannoroc Coven and east of Darkscreen Village; the orb is a near-guaranteed drop; it's a long trip, so plan your route ahead." },
    [1955] = { n = "The Exorcism", cn = "The Exorcism", l = 40, r = 35, s = { { 6546, "Tabetha", "Dustwallow Marsh", 46, 57, 1445 } }, e = { 6546, "Tabetha", "Dustwallow Marsh", 46, 57, 1445 }, note = "The demon is a Lv 40 elite; Lv 38-40 mages can solo it: keep Mana Shield up the whole time, and when out of mana use Frost Nova + Blink to get distance and drink, wearing it down bit by bit." },
    [1956] = { n = "Power in Uldaman", cn = "Power in Uldaman", l = 40, r = 35, s = { { 6546, "Tabetha", "Dustwallow Marsh", 46, 57, 1445 } }, e = { 6546, "Tabetha", "Dustwallow Marsh", 46, 57, 1445 }, note = "The power source drops from the Obsidian Sentinel (Badlands 67,44), in the cave at Uldaman's back door. Level 42 elite: at 75/50/25% health it splits off adds and has Magic Reflection. Hold off before each health threshold, clear the adds first, then burst." },
    [1957] = { n = "Mana Surges", cn = "Mana Surges", l = 40, r = 35, s = { { 6546, "Tabetha", "Dustwallow Marsh", 46, 57, 1445 } }, e = { 6546, "Tabetha", "Dustwallow Marsh", 46, 57, 1445 }, note = "The Mana Surges outside the hut respawn quickly, and pulling one won't bring others; Lv 40 non-elites, soloable one at a time with rests in between." },
    [1958] = { n = "Celestial Power", cn = "Celestial Power", l = 40, r = 35, s = { { 6546, "Tabetha", "Dustwallow Marsh", 46, 57, 1445 } }, e = { 6546, "Tabetha", "Dustwallow Marsh", 46, 57, 1445 }, items = { 7515, 9517 } },
    [1959] = { n = "Report to Anastasia", cn = "Report to Anastasia", l = 15, r = 15, f = "H", races = { 2, 5, 8 }, s = { { 2128, "Cain Firesong", "Tirisfal Glades", 61.8, 52.4, 1420 }, { 3049, "Thurston Xane", "Thunder Bluff", 25, 20.6, 1456 }, { 7311, "Uthel'nay", "Orgrimmar", 39, 86, 1454 }, { 5880, "Un'Thuwa", "Durotar", 56.2, 75, 1411 } }, e = { 4568, "Anastasia Hartwell", "Undercity", 85, 10.2, 1458 }, note = "The turn-in is in the Undercity (Undercity 84,10)." },
    [1960] = { n = "Investigate the Alchemist Shop", cn = "Investigate the Alchemist Shop", l = 16, r = 15, f = "H", races = { 2, 5, 8 }, s = { { 4568, "Anastasia Hartwell", "Undercity", 85, 10.2, 1458 } }, e = { 4568, "Anastasia Hartwell", "Undercity", 85, 10.2, 1458 }, note = "Stand on the steps and use the scroll; one of the ghosts will spawn closest to you: Frost Nova it and run off to draw the others away, then come back and pick them off one by one; remember to get the container and the revealing spell from the NPC first." },
    [1961] = { n = "Gathering Materials", cn = "Gathering Materials", l = 15, r = 15, f = "H", races = { 2, 5, 8 }, s = { { 4568, "Anastasia Hartwell", "Undercity", 85, 10.2, 1458 } }, e = { 4576, "Josef Gregorian", "Undercity", 70.6, 30.4, 1458 }, note = "Dalaran Apprentices are at (Silverpine Forest 50,60), level 13-14 with no Protectors, easy to kill along the road; around Ambermill (Silverpine Forest 55,65) they respawn fast and the Protectors summon small snakes, so fight on the outskirts." },
    [1962] = { n = "Spellfire Robes", cn = "Spellfire Robes", l = 15, r = 15, f = "H", s = { { 4576, "Josef Gregorian", "Undercity", 70.8, 30.7, 1458 } }, e = { 4576, "Josef Gregorian", "Undercity", 70.6, 30.4, 1458 }, items = { 7510 } },
    [1963] = { n = "The Shattered Hand", cn = "The Shattered Hand", l = 13, r = 10, f = "H", races = { 2, 8 }, s = { { 6446, "Therzok", "Orgrimmar", 42.8, 53.4, 1454 } }, e = { 6446, "Therzok", "Orgrimmar", 42.8, 53.4, 1454 }, note = "Tazan patrols up and down the hillside to the right of the pirate camp; below level 12 you can kill a mob at the bottom of the slope and wait for him to come down before engaging; the follow-up target is in the Orgrimmar inn, no need to run back to Ratchet." },
    [1978] = { n = "The Deathstalkers", cn = "The Deathstalkers", l = 13, r = 10, f = "H", races = { 5 }, s = { { 6467, "Mennet Carkad", "Undercity", 83.2, 69, 1458 } }, e = { 2425, "Varimathras", "Undercity", 56.2, 92.6, 1458 }, items = { 7298 }, note = "Turn in to Varimathras, the greater demon in the center of the Undercity Royal Quarter (Undercity 57,91); just walk straight in between the elite guards to turn in." },
    [1998] = { n = "Fenwick Thatros", cn = "Fenwick Thatros", l = 16, r = 16, f = "H", races = { 5 }, s = { { 6467, "Mennet Carkad", "Undercity", 83.2, 69, 1458 } }, e = { 6467, "Mennet Carkad", "Undercity", 83.2, 69, 1458 }, note = "Rogue-only target: a Lv 16 non-elite patrolling the docks (Tirisfal Glades 60,34), easy to deal with." },
    [1999] = { n = "Tools of the Trade", cn = "Tools of the Trade", l = 20, r = 16, f = "H", races = { 5 }, s = { { 6467, "Mennet Carkad", "Undercity", 83.2, 69, 1458 } }, e = { 6467, "Mennet Carkad", "Undercity", 83.2, 69, 1458 }, note = "The chest is on the second floor of the building at (Silverpine Forest 63,65), with three level 19 mage mobs upstairs; even Lockpicking 1 opens it in a couple of tries, no need to do the Ratchet lockpicking quest first." },
    [2205] = { n = "Seek out SI: 7", cn = "Seek out SI: 7", l = 10, r = 10, f = "A", s = { { 917, "Keryn Sylvius", "Elwynn Forest", 43.8, 65.8, 1429 } }, e = { 332, "Master Mathias Shaw", "Stormwind City", 78.3, 70.7, 1453 }, note = "Mathias is on the second floor of SI:7 in Stormwind's Old Town (Stormwind 78,71)." },
    [2206] = { n = "Snatch and Grab", cn = "Snatch and Grab", l = 10, r = 10, f = "A", s = { { 332, "Master Mathias Shaw", "Stormwind City", 78.3, 70.7, 1453 } }, e = { 332, "Master Mathias Shaw", "Stormwind City", 78.3, 70.7, 1453 }, items = { 7298 }, note = "This is a pure Pick Pocket quest: stealth behind the target and pick its pocket, killing mobs doesn't help; the target building is at Jerod's Dock (Stranglethorn Vale 47,87), with scattered mobs outside plus a patrol group, so go in stealthed." },
    [2218] = { n = "Road to Salvation", cn = "Road to Salvation", l = 10, r = 10, f = "A", s = { { 1234, "Hogral Bakkan", "Dun Morogh", 47.6, 52.6, 1426 } }, e = { 5165, "Hulfdan Blackbeard", "Ironforge", 51.6, 14.8, 1455 }, note = "The target is at the far north end of the dark cave in Darnassus (Darnassus 51,14)." },
    [2238] = { n = "Simple Subterfugin'", cn = "Simple Subterfugin'", l = 10, r = 10, f = "A", s = { { 5165, "Hulfdan Blackbeard", "Ironforge", 51.6, 14.8, 1455 } }, e = { 6886, "Onin MacHammar", "Dun Morogh", 25.2, 44.4, 1426 }, note = "The target stands invisible on top of the gnome engineering platform (Dun Morogh 25,44); do NOT walk into Gnomeregan, the Lv 25+ mobs inside will kill you." },
    [2239] = { n = "Onin's Report", cn = "Onin's Report", l = 10, r = 10, f = "A", s = { { 6886, "Onin MacHammar", "Dun Morogh", 25.2, 44.4, 1426 } }, e = { 5165, "Hulfdan Blackbeard", "Ironforge", 51.6, 14.8, 1455 }, items = { 7298 } },
    [2241] = { n = "The Apple Falls", cn = "The Apple Falls", l = 10, r = 10, f = "A", s = { { 3599, "Jannok Breezesong", "Teldrassil", 56.2, 60, 1438 } }, e = { 4163, "Syurna", "Darnassus", 36.8, 21.8, 1457 }, note = "The flower is on a small tree in the Cenarion Enclave of Darnassus (Darnassus 32,16): turn left after the big bridge and gather it from the forked small tree next to the riding instructor." },
    [2242] = { n = "Destiny Calls", cn = "Destiny Calls", l = 10, r = 10, f = "A", s = { { 4163, "Syurna", "Darnassus", 36.8, 21.8, 1457 } }, e = { 4163, "Syurna", "Darnassus", 36.8, 21.8, 1457 }, items = { 7298 }, note = "Sethir is a level 12 satyr (Teldrassil 37,22): the tree wall north of the Oracle Glade has a V-shaped gap, walk out along the branches and you'll see him; approach in stealth, Sap, then Pick Pocket for a safe completion." },
    [2259] = { n = "Erion Shadewhisper", cn = "Erion Shadewhisper", l = 16, r = 16, f = "A", s = { { 3599, "Jannok Breezesong", "Teldrassil", 56.2, 60, 1438 } }, e = { 4214, "Erion Shadewhisper", "Darnassus", 34.6, 25.6, 1457 } },
    [2260] = { n = "Erion's Behest", cn = "Erion's Behest", l = 16, r = 16, f = "A", s = { { 4214, "Erion Shadewhisper", "Darnassus", 34.6, 25.6, 1457 } }, e = { 6946, "Renzik \"The Shiv\"", "Stormwind City", 78.3, 71.1, 1453 }, note = "The target NPC is on the second floor of SI:7 in Stormwind's Old Town (Stormwind City 78,71), right next to Mathias Shaw." },
    [2281] = { n = "Redridge Rendezvous", cn = "Redridge Rendezvous", l = 16, r = 16, f = "A", s = { { 6946, "Renzik \"The Shiv\"", "Stormwind City", 78.3, 71.1, 1453 } }, e = { 6966, "Lucius", "Redridge Mountains", 28.2, 52.2, 1433 }, note = "The contact is in Lakeshire (Redridge Mountains 23,52); note that taking this line locks you out of same-level rogue lines like \"The King's Search\"; pick one." },
    [2282] = { n = "Alther's Mill", cn = "Alther's Mill", l = 20, r = 16, f = "A", s = { { 6966, "Lucius", "Redridge Mountains", 28.2, 52.2, 1433 } }, e = { 6966, "Lucius", "Redridge Mountains", 28.2, 52.2, 1433 }, items = { 7907 }, note = "Practice lockboxes are scattered around the lumber mill (Redridge Mountains 52,43): openable at Lockpicking 25, yellow at 30 and green at 55; you can train all the way from 10 to 100 here — the top lockpicking spot for rogues." },
    [2298] = { n = "Kingly Shakedown", cn = "Kingly Shakedown", l = 16, r = 16, f = "A", s = { { 5165, "Hulfdan Blackbeard", "Ironforge", 51.6, 14.8, 1455 } }, e = { 6946, "Renzik \"The Shiv\"", "Stormwind City", 78.3, 71.1, 1453 }, note = "No prerequisite needed; the target NPC is on the bottom floor of the Ironforge rogue trainer's house." },
    [2299] = { n = "To Hulfdan!", cn = "To Hulfdan!", l = 16, r = 16, f = "A", s = { { 1234, "Hogral Bakkan", "Dun Morogh", 47.6, 52.6, 1426 } }, e = { 5165, "Hulfdan Blackbeard", "Ironforge", 51.6, 14.8, 1455 }, note = "Hulfdan is in the house by the small pool in Ironforge's Forlorn Cavern (Ironforge 51,14)." },
    [2300] = { n = "SI:7", cn = "SI:7", l = 16, r = 16, f = "A", s = { { 917, "Keryn Sylvius", "Elwynn Forest", 43.8, 65.8, 1429 } }, e = { 6946, "Renzik \"The Shiv\"", "Stormwind City", 78.3, 71.1, 1453 } },
    [2359] = { n = "Klaven's Tower", cn = "Klaven's Tower", l = 24, r = 20, f = "A", s = { { 7024, "Agent Kearnen", "Westfall", 68.4, 70, 1436 } }, e = { 332, "Master Mathias Shaw", "Stormwind City", 78.3, 70.7, 1453 }, items = { 18160 }, spells = { 2842 }, note = "The key must be pickpocketed from the Malformed Defias Guards patrolling around the tower — they're often alone and easy targets. The chest at the top of the tower needs 70+ Lockpicking; the stolen key won't open it. Opening the chest inflicts Touch of Zanzil — cure it with the follow-up quest or a druid/shaman/First Aid anti-venom." },
    [2360] = { n = "Mathias and the Defias", cn = "Mathias and the Defias", l = 20, r = 20, f = "A", s = { { 332, "Master Mathias Shaw", "Stormwind City", 78.3, 70.7, 1453 } }, e = { 7024, "Agent Kearnen", "Westfall", 68.4, 70, 1436 }, note = "First stealth to the west side of the third big tree north of the tower to find Kening (Westfall 68,70), who has a yellow question mark; the Malformed guards can be pickpocketed with a few tries, use Sprint to escape if chased; soloable at level 20." },
    [2378] = { n = "Find the Shattered Hand", cn = "Find the Shattered Hand", l = 16, r = 16, f = "H", races = { 2, 5, 8 }, s = { { 6467, "Mennet Carkad", "Undercity", 83.2, 69, 1458 } }, e = { 3401, "Shenthul", "Orgrimmar", 43, 53.4, 1454 }, note = "Sintul is at (Orgrimmar 43,54)." },
    [2379] = { n = "Zando'zan", cn = "Zando'zan", l = 16, r = 16, f = "H", races = { 2, 5, 8, 96 }, s = { { 3401, "Shenthul", "Orgrimmar", 43, 53.4, 1454 } }, e = { 3402, "Zando'zan", "Orgrimmar", 42.8, 53, 1454 }, note = "Shares a slot with \"Greed\" - having one in your log blocks the other, so pick one and don't run both." },
    [2380] = { n = "To Orgrimmar!", cn = "To Orgrimmar!", l = 16, r = 16, f = "H", s = { { 3170, "Kaplak", "Durotar", 52, 43.6, 1411 } }, e = { 3401, "Shenthul", "Orgrimmar", 43, 53.4, 1454 } },
    [2381] = { n = "Plundering the Plunderers", cn = "Plundering the Plunderers", l = 18, r = 16, f = "H", races = { 2, 5, 8, 96 }, s = { { 7161, "Wrenix the Wretched", "The Barrens", 63, 36.4, 1413 } }, e = { 7161, "Wrenix the Wretched", "The Barrens", 63, 36.4, 1413 }, items = { 7676 }, note = "First get lockpicking tools and practice boxes from the robot next to the quest. Board the pirate ship (The Barrens - Merchant Coast 64,45); practice on the boxes inside by deck: orange until 30, yellow until 60, green until 100 — the ultimate lockpicking leveling spot. Watch out for the curse that turns you into a rat." },
    [2382] = { n = "Wrenix of Ratchet", cn = "Wrenix of Ratchet", l = 16, r = 16, f = "H", races = { 2, 5, 8, 96 }, s = { { 3402, "Zando'zan", "Orgrimmar", 42.8, 53, 1454 } }, e = { 7161, "Wrenix the Wretched", "The Barrens", 63, 36.4, 1413 }, note = "Vinix is in the shack next to the Ratchet bank (The Barrens - Ratchet 63,36)." },
    [2458] = { n = "Deep Cover", cn = "Deep Cover", l = 20, r = 20, f = "H", races = { 2, 5, 8, 96 }, s = { { 3401, "Shenthul", "Orgrimmar", 43, 53.4, 1454 } }, e = { 7233, "Taskmaster Fizzule", "The Barrens", 55.4, 5.6, 1413 }, items = { 8066 }, note = "Find Fizzule (The Barrens 56,6): don't panic if his name is red; fire two flares into the air and he becomes friendly; the one you want is the dwarf, not the goblin." },
    [2460] = { n = "The Shattered Salute", cn = "The Shattered Salute", l = 20, r = 20, f = "H", races = { 2, 5, 8, 96 }, s = { { 3401, "Shenthul", "Orgrimmar", 43, 53.4, 1454 } }, e = { 3401, "Shenthul", "Orgrimmar", 43, 53.4, 1454 }, note = "Target the quest NPC and do the /salute emote to complete; if nothing happens, abandon and retake the quest, then try again." },
    [2478] = { n = "Mission: Possible But Not Probable", cn = "Mission: Possible But Not Probable", l = 24, r = 20, f = "H", races = { 2, 5, 8, 96 }, s = { { 7233, "Taskmaster Fizzule", "The Barrens", 55.4, 5.6, 1413 } }, e = { 3401, "Shenthul", "Orgrimmar", 43, 53.4, 1454 }, items = { 18160 }, note = "Steal the key from Silixiz; if you fail, kill him and wait for the respawn, then try again; the mutated worker bees on the first floor can be one-shot with Ambush; the chest needs only Lockpicking 80 (100 is safer), soloable at 20-22." },
    [2479] = { n = "Hinott's Assistance", cn = "Hinott's Assistance", l = 26, r = 20, f = "H", races = { 2, 5, 8, 96 }, s = { { 3401, "Shenthul", "Orgrimmar", 43, 53.4, 1454 } }, e = { 2391, "Serge Hinott", "Hillsbrad Foothills", 61.6, 19.2, 1424 }, note = "First Aid Anti-Venom clears Touch of Zanzil, but you still have to finish the chain to learn Poisons - curing it doesn't complete the quest." },
    [2480] = { n = "Hinott's Assistance", cn = "Hinott's Assistance", l = 20, r = 20, f = "H", races = { 2, 5, 8, 96 }, s = { { 2391, "Serge Hinott", "Hillsbrad Foothills", 61.6, 19.2, 1424 } }, e = { 2391, "Serge Hinott", "Hillsbrad Foothills", 61.6, 19.2, 1424 }, items = { 8095 }, spells = { 2842 } },
    [2607] = { n = "The Touch of Zanzil", cn = "The Touch of Zanzil", l = 20, r = 20, f = "A", s = { { 332, "Master Mathias Shaw", "Stormwind City", 78.3, 70.7, 1453 } }, e = { 7207, "Doc Mixilpixil", "Stormwind City", 80.1, 69.9, 1453 }, note = "Find the doctor in the barracks basement: target him and use the \"lie down\" emote to remove the curse; buy wildflowers from the flower vendor in the Canals (about 2 silver), the Leaded Vial from a poison vendor, and the Copper Tube from an engineering supplier or the AH." },
    [2608] = { n = "The Touch of Zanzil", cn = "The Touch of Zanzil", l = 20, r = 20, f = "A", s = { { 7207, "Doc Mixilpixil", "Stormwind City", 80.1, 69.9, 1453 } }, e = { 7207, "Doc Mixilpixil", "Stormwind City", 80.1, 69.9, 1453 } },
    [2609] = { n = "The Touch of Zanzil", cn = "The Touch of Zanzil", l = 20, r = 20, f = "A", s = { { 7207, "Doc Mixilpixil", "Stormwind City", 80.1, 69.9, 1453 } }, e = { 7207, "Doc Mixilpixil", "Stormwind City", 80.1, 69.9, 1453 }, items = { 8432 } },
    [2983] = { n = "Call of Fire", cn = "Call of Fire", l = 10, r = 10, f = "H", races = { 2, 6, 8 }, s = { { 3173, "Swart", "Durotar", 54.4, 42.6, 1411 } }, e = { 5907, "Kranal Fiss", "The Barrens", 55.8, 20, 1413 }, note = "Kranal Fiss is at (The Barrens 56,20); Fire Tar drops from the Razormane quilboar around (The Barrens 54,24)." },
    [2984] = { n = "Call of Fire", cn = "Call of Fire", l = 10, r = 10, f = "H", races = { 2, 6, 8 }, s = { { 3066, "Narm Skychaser", "Mulgore", 47.4, 62.5, 1412 } }, e = { 5907, "Kranal Fiss", "The Barrens", 55.8, 20, 1413 } },
    [2985] = { n = "Call of Water", cn = "Call of Water", l = 20, r = 20, f = "H", s = { { 3173, "Swart", "Durotar", 54.4, 42.6, 1411 } }, e = { 5901, "Islen Waterseer", "The Barrens", 65.8, 43.8, 1413 } },
    [2986] = { n = "Call of Water", cn = "Call of Water", l = 20, r = 20, f = "H", s = { { 3066, "Narm Skychaser", "Mulgore", 47.4, 62.5, 1412 } }, e = { 5901, "Islen Waterseer", "The Barrens", 65.8, 43.8, 1413 } },
    [2996] = { n = "Seeking Strahad", cn = "Seeking Strahad", l = 30, r = 30, f = "H", races = { 2, 5, 8 }, s = { { 5875, "Gan'rul Bloodeye", "Orgrimmar", 48.2, 45.6, 1454 } }, e = { 6251, "Strahad Farsan", "The Barrens", 62.6, 35.4, 1413 }, note = "Steinhard is on the hillside behind the engineers' hut in Ratchet (The Barrens - Ratchet 62,35)." },
    [2997] = { n = "Tome of Divinity", cn = "Tome of Divinity", l = 12, r = 12, f = "A", races = { 3 }, s = { { 1232, "Azar Stronghammer", "Dun Morogh", 47.6, 52, 1426 } }, e = { 6179, "Tiza Battleforge", "Ironforge", 27.4, 12, 1455 }, note = "Requires Lv 12; the starting NPC is on the upper floor of the main building in the Mystic Ward of Ironforge (Ironforge 28,12); completion awards the \"Tome of Divinity\"." },
    [2998] = { n = "Tome of Divinity", cn = "Tome of Divinity", l = 12, r = 12, f = "A", races = { 1 }, s = { { 927, "Brother Wilhelm", "Elwynn Forest", 41, 66, 1429 } }, e = { 6171, "Duthorian Rall", "Stormwind City", 50.5, 47.5, 1453 } },
