    [4782] = { n = "Components for the Enchanted Gold Bloodrobe", cn = "Components for the Enchanted Gold Bloodrobe", l = 34, r = 31, s = { { 2670, "Xizk Goodstitch", "Stranglethorn Vale", 28.6, 76.8, 1434 } }, e = { 6266, "Menara Voidrender", "The Barrens", 62.4, 35.4, 1413 } },
