    [4784] = { n = "Components for the Enchanted Gold Bloodrobe", cn = "Components for the Enchanted Gold Bloodrobe", l = 37, r = 31, s = { { 6266, "Menara Voidrender", "The Barrens", 62.4, 35.4, 1413 } }, e = { 6266, "Menara Voidrender", "The Barrens", 62.4, 35.4, 1413 }, note = "Smoldering Coals drop from Burning Exiles in the Arathi Highlands; the mobs are Lv 38-39, so it's tough at Lv 30-32; group up or bring elemental charms." },
    [4785] = { n = "Fine Gold Thread", cn = "Fine Gold Thread", l = 37, r = 31, s = { { 2670, "Xizk Goodstitch", "Stranglethorn Vale", 28.6, 76.8, 1434 } }, e = { 2670, "Xizk Goodstitch", "Stranglethorn Vale", 28.6, 76.8, 1434 }, items = { 12293 }, note = "The gold thread is only handed out at step six of the chain: go back to the hut on the top floor of the Booty Bay tailor shop and get it from the kobold waiting for gold bars." },
    [4786] = { n = "The Completed Robe", cn = "The Completed Robe", l = 38, r = 31, s = { { 6266, "Menara Voidrender", "The Barrens", 62.4, 35.4, 1413 } }, e = { 6266, "Menara Voidrender", "The Barrens", 62.4, 35.4, 1413 }, items = { 6900 } },
    [4961] = { n = "Cleansing of the Orb of Orahil", cn = "Cleansing of the Orb of Orahil", l = 40, r = 35, s = { { 6546, "Tabetha", "Dustwallow Marsh", 46, 57, 1445 } }, e = { 6546, "Tabetha", "Dustwallow Marsh", 46, 57, 1445 }, items = { 12642 }, note = "Soloable at 36-37: the safe approach is Voidwalker tanking and curses draining health, recover with Life Tap, and be careful not to pull aggro; clear nearby mobs before starting." },
    [4962] = { n = "Shard of a Felhound", cn = "Shard of a Felhound", l = 40, r = 35, s = { { 6254, "Acolyte Wytula", "The Barrens", 62.6, 35.2, 1413 } }, e = { 6266, "Menara Voidrender", "The Barrens", 62.4, 35.4, 1413 }, note = "Behind Menara there is a branch option on each side, leading to different follow-up gear; the objective is to steal a Felhound soul in Desolace, and the target mobs are around Mannoroc Coven (Desolace 50,78)." },
    [4963] = { n = "Shard of an Infernal", cn = "Shard of an Infernal", l = 40, r = 35, s = { { 6252, "Acolyte Magaz", "The Barrens", 62.6, 35.2, 1413 } }, e = { 6266, "Menara Voidrender", "The Barrens", 62.4, 35.4, 1413 }, note = "Steal the Infernal Soul in Desolace; there's a branch NPC on each side behind Menara Voidrender, and this step continues the staff line." },
