    [5921] = { n = "Moonglade", cn = "Moonglade", l = 10, r = 10, f = "A", races = { 4 }, s = { { 4217, "Mathrengyl Bearwalker", "Darnassus", 35.2, 8, 1457 } }, e = { 11802, "Dendrite Starblaze", "Moonglade", 56.2, 30.4, 1450 }, note = "After teleporting to Moonglade you land in front of a house: go past the light armor vendor and up the stairs; Starblaze (Moonglade 56,30) gives the next step." },
    [5922] = { n = "Moonglade", cn = "Moonglade", l = 10, r = 10, f = "H", races = { 6 }, s = { { 3033, "Turak Runetotem", "Thunder Bluff", 76.4, 27.6, 1456 } }, e = { 11802, "Dendrite Starblaze", "Moonglade", 56.2, 30.4, 1450 }, note = "No need to worry about your hearthstone cooldown after turning in - the Moonglade flight point is free for druids." },
    [5923] = { n = "Heeding the Call", cn = "Heeding the Call", l = 10, r = 10, f = "A", races = { 4 }, s = { { 4218, "Denatharion", "Darnassus", 34.8, 7.4, 1457 } }, e = { 4217, "Mathrengyl Bearwalker", "Darnassus", 35.2, 8, 1457 }, note = "The Alliance version starts from Kal and is turned in to Mathrengyl Bearwalker." },
