    [5926] = { n = "Heeding the Call", cn = "Heeding the Call", l = 10, r = 10, f = "H", races = { 6 }, s = { { 6746, "Innkeeper Pala", "Thunder Bluff", 45.8, 64.7, 1456 } }, e = { 3033, "Turak Runetotem", "Thunder Bluff", 76.4, 27.6, 1456 }, note = "The Horde version starts with Gennia Runetotem in Mulgore, and the Thunder Bluff version turns in to Turak Runetotem; the same-named quests from the two innkeepers are just normal quests, not class quests." },
    [5927] = { n = "Heeding the Call", cn = "Heeding the Call", l = 10, r = 10, f = "H", races = { 6 }, s = { { 3060, "Gart Mistrunner", "Mulgore", 44.7, 76.6, 1412 } }, e = { 3033, "Turak Runetotem", "Thunder Bluff", 76.4, 27.6, 1456 } },
