    [5929] = { n = "Great Bear Spirit", cn = "Great Bear Spirit", l = 10, r = 10, f = "A", races = { 4 }, s = { { 11802, "Dendrite Starblaze", "Moonglade", 56.2, 30.4, 1450 } }, e = { 11802, "Dendrite Starblaze", "Moonglade", 56.2, 30.4, 1450 } },
    [5930] = { n = "Great Bear Spirit", cn = "Great Bear Spirit", l = 10, r = 10, f = "H", races = { 6 }, s = { { 11802, "Dendrite Starblaze", "Moonglade", 56.2, 30.4, 1450 } }, e = { 11802, "Dendrite Starblaze", "Moonglade", 56.2, 30.4, 1450 }, note = "The Great Bear Spirit is at (Moonglade 39,27), a short way north out of town; after talking to it, teleport back to town to turn in fastest." },
    [5931] = { n = "Back to Darnassus", cn = "Back to Darnassus", l = 10, r = 10, f = "A", races = { 4 }, s = { { 11802, "Dendrite Starblaze", "Moonglade", 56.2, 30.4, 1450 } }, e = { 4217, "Mathrengyl Bearwalker", "Darnassus", 35.2, 8, 1457 }, note = "The druid-only flight point in Moonglade is at (Moonglade 44,45) and flies directly to Darnassus." },
    [5932] = { n = "Back to Thunder Bluff", cn = "Back to Thunder Bluff", l = 10, r = 10, f = "H", races = { 6 }, s = { { 11802, "Dendrite Starblaze", "Moonglade", 56.2, 30.4, 1450 } }, e = { 3033, "Turak Runetotem", "Thunder Bluff", 76.4, 27.6, 1456 }, note = "Fly back to Thunder Bluff from the flight point in the southwest corner of Nighthaven (Moonglade 44,45); there's also an Alliance flight master south of the lake, don't talk to the wrong one." },
    [6001] = { n = "Body and Heart", cn = "Body and Heart", l = 10, r = 10, f = "A", races = { 4 }, s = { { 4217, "Mathrengyl Bearwalker", "Darnassus", 35.2, 8, 1457 } }, e = { 4217, "Mathrengyl Bearwalker", "Darnassus", 35.2, 8, 1457 }, spells = { 5487 }, note = "The Moonkin Stone is in the cave (Darkshore 43,46); after sprinkling the powder Lunaclaw charges into the cave on its own; it's much weaker than the mobs outside and loses health slowly, so it's an easy solo, and there's no need to clear outside." },
    [6002] = { n = "Body and Heart", cn = "Body and Heart", l = 10, r = 10, f = "H", races = { 6 }, s = { { 3033, "Turak Runetotem", "Thunder Bluff", 76.4, 27.6, 1456 } }, e = { 3033, "Turak Runetotem", "Thunder Bluff", 76.4, 27.6, 1456 }, spells = { 5487 }, note = "The Moonkin Stone is behind the first house on the right as you leave Mulgore into the Barrens (The Barrens 42,61); avoid the level 20 Thunderhead elementals nearby, and fly back from Camp Taurajo afterward for speed." },
    [6061] = { n = "Taming the Beast", cn = "Taming the Beast", l = 10, r = 10, f = "H", races = { 6 }, s = { { 3065, "Yaw Sharpmane", "Mulgore", 46.8, 59.6, 1412 } }, e = { 3065, "Yaw Sharpmane", "Mulgore", 46.8, 59.6, 1412 } },
    [6062] = { n = "Taming the Beast", cn = "Taming the Beast", l = 10, r = 10, f = "H", races = { 2, 8 }, s = { { 3171, "Thotar", "Durotar", 51.8, 43.4, 1411 } }, e = { 3171, "Thotar", "Durotar", 51.8, 43.4, 1411 }, note = "Don't use your hearthstone while taming, or the target beast will disappear (though once the tame itself is done, quest credit isn't affected)." },
    [6063] = { n = "Taming the Beast", cn = "Taming the Beast", l = 10, r = 10, f = "A", races = { 4 }, s = { { 3601, "Dazalar", "Teldrassil", 56.6, 59.6, 1438 } }, e = { 3601, "Dazalar", "Teldrassil", 56.6, 59.6, 1438 }, note = "When the Taming Rod runs out, just destroy it and abandon/re-accept the quest - no need to go back to the NPC for another fix." },
    [6064] = { n = "Taming the Beast", cn = "Taming the Beast", l = 10, r = 10, f = "A", races = { 3 }, s = { { 1231, "Grif Wildheart", "Dun Morogh", 45.8, 53, 1426 } }, e = { 1231, "Grif Wildheart", "Dun Morogh", 45.8, 53, 1426 }, note = "All three beasts can be found in the two small clearings south of Kharanos, no need to run to Brill; boars, snow leopards and Ice Claw Bears also roam near the village." },
