    [6087] = { n = "Taming the Beast", cn = "Taming the Beast", l = 10, r = 10, f = "H", races = { 6 }, s = { { 3065, "Yaw Sharpmane", "Mulgore", 46.8, 59.6, 1412 } }, e = { 3065, "Yaw Sharpmane", "Mulgore", 46.8, 59.6, 1412 } },
    [6088] = { n = "Taming the Beast", cn = "Taming the Beast", l = 10, r = 10, f = "H", races = { 6 }, s = { { 3065, "Yaw Sharpmane", "Mulgore", 46.8, 59.6, 1412 } }, e = { 3065, "Yaw Sharpmane", "Mulgore", 46.8, 59.6, 1412 }, spells = { 1515 }, note = "The Swoop step is the hardest: you can first farm a Solvent Spirit for \"Extra-Sticky Glue\" to help control it; when its swoop stuns you, use the Taming Rod again as soon as the effect ends." },
    [6089] = { n = "Training the Beast", cn = "Training the Beast", l = 10, r = 10, f = "H", races = { 6 }, s = { { 3065, "Yaw Sharpmane", "Mulgore", 46.8, 59.6, 1412 } }, e = { 3039, "Holt Thunderhorn", "Thunder Bluff", 57.4, 89.2, 1456 }, spells = { 5149 } },
    [6101] = { n = "Taming the Beast", cn = "Taming the Beast", l = 10, r = 10, f = "A", races = { 4 }, s = { { 3601, "Dazalar", "Teldrassil", 56.6, 59.6, 1438 } }, e = { 3601, "Dazalar", "Teldrassil", 56.6, 59.6, 1438 }, note = "Nightsaber Stalkers are at (Teldrassil 56,75): straight south of Dolanaar across the lake; don't kill the ordinary Nightsabers near camp by mistake." },
    [6102] = { n = "Taming the Beast", cn = "Taming the Beast", l = 10, r = 10, f = "A", races = { 4 }, s = { { 3601, "Dazalar", "Teldrassil", 56.6, 59.6, 1438 } }, e = { 3601, "Dazalar", "Teldrassil", 56.6, 59.6, 1438 }, spells = { 1515 }, note = "The owl roams just outside Darnassus (near Teldrassil 44,50)." },
    [6103] = { n = "Training the Beast", cn = "Training the Beast", l = 10, r = 10, f = "A", races = { 4 }, s = { { 3601, "Dazalar", "Teldrassil", 56.6, 59.6, 1438 } }, e = { 4146, "Jocaste", "Darnassus", 40.2, 8.8, 1457 }, spells = { 5149 } },
    [6121] = { n = "Lessons Anew", cn = "Lessons Anew", l = 14, r = 14, f = "A", races = { 4, 95 }, s = { { 4217, "Mathrengyl Bearwalker", "Darnassus", 35.2, 8, 1457 }, { 270459, "Alfina Nightgaze", "Alterac Mountains", 11.8, 56.6, 1416 } }, e = { 11802, "Dendrite Starblaze", "Moonglade", 56.2, 30.4, 1450 }, note = "Starts with Mathrengyl Bearwalker in Darnassus; the chain's final reward is Cure Poison, and it gives plenty of XP too - worth finishing." },
    [6122] = { n = "The Principal Source", cn = "The Principal Source", l = 14, r = 14, f = "A", races = { 4, 95 }, s = { { 11802, "Dendrite Starblaze", "Moonglade", 56.2, 30.4, 1450 } }, e = { 3702, "Alanndarian Nightsong", "Darkshore", 37.6, 40.6, 1439 }, note = "Note that you take the water in Darkshore, not Moonglade: the fill point (Darkshore 54,33) is at the top of the waterfall by the cave mouth, don't fill it in the river; after filling, watch out for the level 15 naga from the cave behind you." },
    [6123] = { n = "Gathering the Cure", cn = "Gathering the Cure", l = 14, r = 14, f = "A", races = { 4, 95 }, s = { { 3702, "Alanndarian Nightsong", "Darkshore", 37.6, 40.6, 1439 } }, e = { 3702, "Alanndarian Nightsong", "Darkshore", 37.6, 40.6, 1439 }, note = "Moon mushrooms are in several spots in the owlkin cave (Darkshore 43,45); just buy Earthroot from a herbalism vendor instead of gathering it." },
    [6124] = { n = "Curing the Sick", cn = "Curing the Sick", l = 14, r = 14, f = "A", races = { 4, 95 }, s = { { 3702, "Alanndarian Nightsong", "Darkshore", 37.6, 40.6, 1439 } }, e = { 11802, "Dendrite Starblaze", "Moonglade", 56.2, 30.4, 1450 }, items = { 15866 }, note = "Find the deer surrounded by green disease clouds, target them and use the salve to complete; the sick deer are spread along the lake and through the woods, plenty of them." },
    [6125] = { n = "Power over Poison", cn = "Power over Poison", l = 14, r = 14, f = "A", races = { 4, 95 }, s = { { 11802, "Dendrite Starblaze", "Moonglade", 56.2, 30.4, 1450 } }, e = { 4217, "Mathrengyl Bearwalker", "Darnassus", 35.2, 8, 1457 }, spells = { 8946 }, note = "Turn in on the upper level of the central building in Darnassus's Cenarion Enclave (Darnassus 35,8); completing it teaches Cure Poison." },
    [6126] = { n = "Lessons Anew", cn = "Lessons Anew", l = 14, r = 14, f = "H", races = { 6, 96 }, s = { { 3033, "Turak Runetotem", "Thunder Bluff", 76.4, 27.6, 1456 }, { 262560, "Hana Lighthoof", "Mulgore", 33.4, 22, 1412 } }, e = { 11802, "Dendrite Starblaze", "Moonglade", 56.2, 30.4, 1450 }, note = "Starts at the class trainer in Thunder Bluff; use Teleport: Moonglade to get there; on the way back fly from the flight master (Moonglade 44,45), and remember to keep your hearthstone set near the Crossroads." },
    [6127] = { n = "The Principal Source", cn = "The Principal Source", l = 14, r = 14, f = "H", races = { 6, 96 }, s = { { 11802, "Dendrite Starblaze", "Moonglade", 56.2, 30.4, 1450 } }, e = { 3448, "Tonga Runetotem", "The Barrens", 52.2, 31.8, 1413 }, note = "Dreadmist Peak is northwest of the Crossroads (The Barrens 47,17): there's a small pond above the hilltop cave; clear the mobs around it before filling the bottle; afterward a few level 13 mobs crawl out of the ground, kill them and you're safe." },
    [6128] = { n = "Gathering the Cure", cn = "Gathering the Cure", l = 14, r = 14, f = "H", races = { 6, 96 }, s = { { 3448, "Tonga Runetotem", "The Barrens", 52.2, 31.8, 1413 } }, e = { 3448, "Tonga Runetotem", "The Barrens", 52.2, 31.8, 1413 }, note = "The Lost Barrens Kodos are in the Sludge Fen (The Barrens 55,11), 100% drop rate; no need for Herbalism for Earthroot — the apothecary at the Crossroads sells it (3 for 80 copper)." },
    [6129] = { n = "Curing the Sick", cn = "Curing the Sick", l = 14, r = 14, f = "H", races = { 6, 96 }, s = { { 3448, "Tonga Runetotem", "The Barrens", 52.2, 31.8, 1413 } }, e = { 11802, "Dendrite Starblaze", "Moonglade", 56.2, 30.4, 1450 }, items = { 15866 }, note = "Rooting the diseased animals with Entangling Roots before applying the salve is more efficient; apply it before the roots kill it - dead ones don't count." },
    [6130] = { n = "Power over Poison", cn = "Power over Poison", l = 14, r = 14, f = "H", races = { 6, 96 }, s = { { 11802, "Dendrite Starblaze", "Moonglade", 56.2, 30.4, 1450 } }, e = { 3033, "Turak Runetotem", "Thunder Bluff", 76.4, 27.6, 1456 }, spells = { 8946 }, note = "Turn in to Turak Runetotem at Elder Rise in Thunder Bluff (Thunder Bluff 76,27) to learn Cure Poison; if you're just leveling, you can skip it and learn Abolish Poison at Lv 26." },
    [6681] = { n = "The Manor, Ravenholdt", cn = "The Manor, Ravenholdt", l = 24, r = 24, e = { 6707, "Fahrad", "Alterac Mountains", 84.4, 80.2, 1416 }, note = "Requires level 24 and Detect Traps. The manor is on the hills southeast of Tarren Mill; the path up is behind the plateau north of Durnholde Keep (Hillsbrad Foothills 75,24). Opening the chest spawns a level 33 elite — have an escape plan ready." },
    [6701] = { n = "Syndicate Emblems", cn = "Syndicate Emblems", l = 60, r = 24, s = { { 6766, "Ravenholdt Guard", "Alterac Mountains", 84.4, 79.4, 1416 }, { 6766, "Ravenholdt Guard", "Hillsbrad Foothills", 77.6, 20, 1424 } }, e = { 6766, "Ravenholdt Guard", "Alterac Mountains", 84.4, 79.4, 1416 } },
    [6721] = { n = "The Hunter's Path", cn = "The Hunter's Path", l = 10, r = 10, f = "A", races = { 4 }, s = { { 5116, "Olmin Burningbeard", "Ironforge", 70.6, 83.8, 1455 } }, e = { 3601, "Dazalar", "Teldrassil", 56.6, 59.6, 1438 } },
    [6722] = { n = "The Hunter's Path", cn = "The Hunter's Path", l = 10, r = 10, f = "A", races = { 4 }, s = { { 1231, "Grif Wildheart", "Dun Morogh", 45.8, 53, 1426 } }, e = { 3601, "Dazalar", "Teldrassil", 56.6, 59.6, 1438 } },
    [7463] = { n = "Arcane Refreshment", cn = "Arcane Refreshment", l = 60, r = 60, s = { { 14368, "Lorekeeper Lydros", "Dire Maul", 0, 0 } }, e = { 14368, "Lorekeeper Lydros", "Dire Maul", 0, 0 }, spells = { 10140 }, note = "Taken from the Dire Maul library (reachable from both the West and North wings); a must-do chain for Lv 60 mages." },
    [7562] = { n = "Mor'zul Bloodbringer", cn = "Mor'zul Bloodbringer", l = 58, r = 60, s = { { 5520, "Spackle Thornberry", "Stormwind City", 39.5, 84.5, 1453 }, { 5815, "Kurgul", "Orgrimmar", 47.6, 46.8, 1454 }, { 6382, "Jubahl Corpseseeker", "Ironforge", 53, 6.2, 1455 }, { 12807, "Greshka", "Swamp of Sorrows", 48.6, 55.3, 1435 } }, e = { 14436, "Mor'zul Bloodbringer", "Burning Steppes", 12.6, 31.6, 1428 }, note = "Start of the Dreadsteed chain: Mor'zul Bloodbringer is in the Burning Steppes (Burning Steppes 12,31), requires level 60; budget at least 150 gold for the whole chain and prepare in advance." },
    [7563] = { n = "Rage of Blood", cn = "Rage of Blood", l = 58, r = 60, s = { { 14436, "Mor'zul Bloodbringer", "Burning Steppes", 12.6, 31.6, 1428 } }, e = { 14436, "Mor'zul Bloodbringer", "Burning Steppes", 12.6, 31.6, 1428 }, note = "The blood samples drop from wolf mobs around the Hidden Grove in Felwood (Felwood 65,21) at 20-48% rates, taking about an hour; can be done alongside the \"Wild Guardians\" chain on the same mobs." },
    [7564] = { n = "Wildeyes", cn = "Wildeyes", l = 58, r = 60, s = { { 14436, "Mor'zul Bloodbringer", "Burning Steppes", 12.6, 31.6, 1428 } }, e = { 14437, "Gorzeeki Wildeyes", "Burning Steppes", 12.4, 31.6, 1428 }, note = "The follow-ups are small quests for several items, and the final step is the summoning ritual inside Scholomance - don't wait out in the world for the finish." },
    [7581] = { n = "The Prison's Bindings", cn = "The Prison's Bindings", l = 60, r = 60, s = { { 14463, "Daio the Decrepit", "Blasted Lands", 34, 50.2, 1419 } }, e = { 14463, "Daio the Decrepit", "Blasted Lands", 34, 50.2, 1419 }, note = "Enter Dire Maul through the back door in Feralas; four-person tactics: have the voidwalker hold the rogue, banish the other, and slowly DoT them down one by one." },
    [7582] = { n = "The Prison's Casing", cn = "The Prison's Casing", l = 60, r = 60, s = { { 14463, "Daio the Decrepit", "Blasted Lands", 34, 50.2, 1419 } }, e = { 14463, "Daio the Decrepit", "Blasted Lands", 34, 50.2, 1419 }, note = "The mobs can be feared and banished: Curse of Doom, then alternate Banish for 30s and then 20s; the drop rate is low, so be patient." },
    [7583] = { n = "Suppression", cn = "Suppression", l = 60, r = 60, s = { { 14463, "Daio the Decrepit", "Blasted Lands", 34, 50.2, 1419 } }, e = { 14463, "Daio the Decrepit", "Blasted Lands", 34, 50.2, 1419 }, items = { 18602 }, spells = { 18540 }, note = "The Doomguard Captain is south of the quest spot (Blasted Lands 34,63), surrounded by a ring of Felclaw elites, but they're spread out; pull them away one at a time, then fight the captain alone." },
    [7601] = { n = "What Niby Commands", cn = "What Niby Commands", l = 50, r = 50, s = { { 14469, "Niby the Almighty", "Felwood", 41.4, 44.8, 1448 } }, e = { 14470, "Impsy", "Felwood", 41.4, 44.8, 1448 }, note = "Impsy is in Felwood (Felwood 41,45); the quest is available at Lv 50 and obtainable at Lv 48." },
    [7602] = { n = "Flawless Fel Essence", cn = "Flawless Fel Essence", l = 55, r = 50, s = { { 14470, "Impsy", "Felwood", 41.4, 44.8, 1448 } }, e = { 14470, "Impsy", "Felwood", 41.4, 44.8, 1448 }, note = "Three essences: in Azshara, any mob at Legash Encampment (Azshara 51,19) drops it; in Felwood, the Legion soldiers under Jaedenar (Felwood 35,58) have a very low drop rate; for the Blasted Lands one, note that you kill Felguards, not Doomguards." },
    [7603] = { n = "Kroshius' Infernal Core", cn = "Kroshius' Infernal Core", l = 55, r = 50, s = { { 14470, "Impsy", "Felwood", 41.4, 44.8, 1448 } }, e = { 14469, "Niby the Almighty", "Felwood", 41.4, 44.8, 1448 }, items = { 18762 }, spells = { 1122 }, note = "Kroshius's remains are on the hillside (Burning Steppes 45,35), on the high ground just north of the crater - easy to find." },
    [7621] = { n = "A Warning", cn = "A Warning", l = 60, r = 60, s = { { 14494, "Eris Havenfire", "Eastern Plaguelands", 20.8, 18.4, 1423 } }, e = { 14494, "Eris Havenfire", "Eastern Plaguelands", 20.8, 18.4, 1423 }, note = "Priest only; you must hold the Eye of Divinity to see the target NPC, otherwise it's a wasted trip." },
    [7622] = { n = "The Balance of Light and Shadow", cn = "The Balance of Light and Shadow", l = 60, r = 60, s = { { 14494, "Eris Havenfire", "Eastern Plaguelands", 20.8, 18.4, 1423 } }, e = { 14494, "Eris Havenfire", "Eastern Plaguelands", 20.8, 18.4, 1423 }, items = { 18659 }, note = "Turn on NPC nameplates (Shift+V) to watch the peasants' health; multiple priests can take turns healing, which makes it much easier." },
    [7623] = { n = "Lord Banehollow", cn = "Lord Banehollow", l = 58, r = 60, s = { { 14437, "Gorzeeki Wildeyes", "Burning Steppes", 12.4, 31.6, 1428 } }, e = { 9516, "Lord Banehollow", "Felwood", 36, 44.6, 1448 }, note = "Drink the shadow potion at Jaedenar before moving on (all mobs along the way are green and won't attack); the target cave (Felwood 35,59) is the second cave — pass the first one and keep going until you see \"Shadow Hold\"." },
    [7624] = { n = "Ulathek the Traitor", cn = "Ulathek the Traitor", l = 58, r = 60, s = { { 9516, "Lord Banehollow", "Felwood", 36, 44.6, 1448 } }, e = { 9516, "Lord Banehollow", "Felwood", 36, 44.6, 1448 }, note = "Ulathek is deep in the cave (Felwood 41,48): from Bannehal head back toward the entrance, and after the slope take the right fork to the end." },
    [7625] = { n = "Xorothian Stardust", cn = "Xorothian Stardust", l = 60, r = 60, s = { { 9516, "Lord Banehollow", "Felwood", 36, 44.6, 1448 } }, e = { 14437, "Gorzeeki Wildeyes", "Burning Steppes", 12.4, 31.6, 1428 }, note = "This step is easy: just buy the Stardust from Banehollow for 150 gold." },
    [7626] = { n = "Bell of Dethmoora", cn = "Bell of Dethmoora", l = 60, r = 60, s = { { 14436, "Mor'zul Bloodbringer", "Burning Steppes", 12.6, 31.6, 1428 } }, e = { 14437, "Gorzeeki Wildeyes", "Burning Steppes", 12.4, 31.6, 1428 }, note = "Requires 2 Greater Shadow Energy Elixirs (3 Ghost Mushrooms each, plentiful at Skulk Rock in The Hinterlands) and 1 Arcanite Bar." },
    [7627] = { n = "Wheel of the Black March", cn = "Wheel of the Black March", l = 60, r = 60, s = { { 14436, "Mor'zul Bloodbringer", "Burning Steppes", 12.6, 31.6, 1428 } }, e = { 14437, "Gorzeeki Wildeyes", "Burning Steppes", 12.4, 31.6, 1428 }, note = "Just buy the Dark Iron Ore at the Auction House; usually cheap, about 25 is enough." },
    [7628] = { n = "Doomsday Candle", cn = "Doomsday Candle", l = 60, r = 60, s = { { 14436, "Mor'zul Bloodbringer", "Burning Steppes", 12.6, 31.6, 1428 } }, e = { 14437, "Gorzeeki Wildeyes", "Burning Steppes", 12.4, 31.6, 1428 }, note = "The items can simply be bought; have Arcanite Bars ready in advance - the next step only needs 1, don't get the count wrong." },
    [7629] = { n = "Imp Delivery", cn = "Imp Delivery", l = 60, r = 60, s = { { 14437, "Gorzeeki Wildeyes", "Burning Steppes", 12.4, 31.6, 1428 } }, e = { 14437, "Gorzeeki Wildeyes", "Burning Steppes", 12.4, 31.6, 1428 }, note = "Activate the imp at the Scholomance Alchemy Lab (in the same room as Ras Frostwhisper); afterward the imp follows you along with its jar, and the quest note is in the jar — no need to dig through your bags." },
    [7630] = { n = "Arcanite", cn = "Arcanite", l = 60, r = 60, s = { { 14437, "Gorzeeki Wildeyes", "Burning Steppes", 12.4, 31.6, 1428 } }, e = { 14437, "Gorzeeki Wildeyes", "Burning Steppes", 12.4, 31.6, 1428 } },
    [7631] = { n = "Dreadsteed of Xoroth", cn = "Dreadsteed of Xoroth", l = 60, r = 60, s = { { 14436, "Mor'zul Bloodbringer", "Burning Steppes", 12.6, 31.6, 1428 } }, e = { 14504, "Dreadsteed Spirit", "", 0, 0 }, spells = { 23161 }, note = "Finishing the whole chain raises your Riding Skill straight from 75 to 150, saving several hundred gold over buying an epic mount - a great deal." },
    [7632] = { n = "The Ancient Leaf", cn = "The Ancient Leaf", l = 60, r = 60, e = { 14524, "Vartrus the Ancient", "Felwood", 48.8, 24.2, 1448 }, note = "The Ancient Petrified Leaf comes from Molten Core: open the Cache of the Firelord after defeating Majordomo Executus; getting the leaf is the real start of the Hunter epic bow chain." },
    [7633] = { n = "An Introduction", cn = "An Introduction", l = 60, r = 60, s = { { 14524, "Vartrus the Ancient", "Felwood", 48.8, 24.2, 1448 } }, e = { 14524, "Vartrus the Ancient", "Felwood", 48.8, 24.2, 1448 } },
    [7634] = { n = "Ancient Sinew Wrapped Lamina", cn = "Ancient Sinew Wrapped Lamina", l = 60, r = 60, s = { { 14526, "Hastat the Ancient", "Felwood", 48.2, 24.2, 1448 } }, e = { 14526, "Hastat the Ancient", "Felwood", 48.2, 24.2, 1448 }, items = { 18714 }, note = "The dragon sinew drops from Azuregos or the Cobalt Scalebanes in Mazthoril, Winterspring; the quiver gives +15% ranged attack speed, the best quiver in the current version." },
    [7635] = { n = "A Proper String", cn = "A Proper String", l = 60, r = 60, s = { { 14525, "Stoma the Ancient", "Felwood", 48.6, 23.2, 1448 } }, e = { 14525, "Stoma the Ancient", "Felwood", 48.6, 23.2, 1448 }, items = { 18724 }, note = "Dragon Sinew Rope drops from Onyxia (about 20%) and can be looted without the quest; ask your raid in advance to save it for you." },
    [7636] = { n = "Stave of the Ancients", cn = "Stave of the Ancients", l = 60, r = 60, s = { { 14524, "Vartrus the Ancient", "Felwood", 48.8, 24.2, 1448 } }, e = { 14524, "Vartrus the Ancient", "Felwood", 48.8, 24.2, 1448 }, items = { 18707 }, note = "All four demon fights must be done completely solo — no pets, trinket summons or Snake Trap (Snake Trap makes the demon flee); any extra target on the threat table means failure." },
    [7637] = { n = "Emphasis on Sacrifice", cn = "Emphasis on Sacrifice", l = 60, r = 60, f = "A", races = { 1, 3 }, s = { { 928, "Lord Grayson Shadowbreaker", "Stormwind City", 48.4, 50.2, 1453 } }, e = { 11406, "High Priest Rohan", "Ironforge", 25, 8.4, 1455 }, note = "Before starting, make sure you've learned the right rank of seals (Wisdom/Righteousness/Justice); for the summoning fight, place the scryer in the northwest corner and stand in the southeast corner yourself; single-pull the first two waves and clear the last two as groups." },
    [7638] = { n = "Lord Grayson Shadowbreaker", cn = "Lord Grayson Shadowbreaker", l = 60, r = 60, f = "A", races = { 1, 3 }, s = { { 6171, "Duthorian Rall", "Stormwind City", 50.5, 47.5, 1453 } }, e = { 928, "Lord Grayson Shadowbreaker", "Stormwind City", 48.4, 50.2, 1453 } },
    [7639] = { n = "To Show Due Judgment", cn = "To Show Due Judgment", l = 60, r = 60, f = "A", races = { 1, 3 }, s = { { 11406, "High Priest Rohan", "Ironforge", 25, 8.4, 1455 } }, e = { 928, "Lord Grayson Shadowbreaker", "Stormwind City", 48.4, 50.2, 1453 } },
    [7640] = { n = "Exorcising Terrordale", cn = "Exorcising Terrordale", l = 60, r = 60, f = "A", races = { 1, 3 }, s = { { 928, "Lord Grayson Shadowbreaker", "Stormwind City", 48.4, 50.2, 1453 } }, e = { 928, "Lord Grayson Shadowbreaker", "Stormwind City", 48.4, 50.2, 1453 }, note = "The Exorcism Censer has a 30-second cooldown; plan your casts and don't stand around in a pack waiting on the CD." },
    [7641] = { n = "The Work of Grimand Elmore", cn = "The Work of Grimand Elmore", l = 60, r = 60, f = "A", races = { 1, 3 }, s = { { 928, "Lord Grayson Shadowbreaker", "Stormwind City", 48.4, 50.2, 1453 } }, e = { 1416, "Grimand Elmore", "Stormwind City", 59.7, 33.8, 1453 } },
    [7642] = { n = "Collection of Goods", cn = "Collection of Goods", l = 60, r = 60, f = "A", races = { 1, 3 }, s = { { 1416, "Grimand Elmore", "Stormwind City", 59.7, 33.8, 1453 } }, e = { 1416, "Grimand Elmore", "Stormwind City", 59.7, 33.8, 1453 }, note = "Stratholme Holy Water comes from the supply crates in the dungeon (only the glowing ones); Arthas' Tears are about 2 gold on the AH; buy a few Enriched Manna Biscuits at Chillwind Camp on the way, as later steps need them." },
    [7643] = { n = "Ancient Equine Spirit", cn = "Ancient Equine Spirit", l = 60, r = 60, f = "A", races = { 1, 3 }, s = { { 928, "Lord Grayson Shadowbreaker", "Stormwind City", 48.4, 50.2, 1453 } }, e = { 14566, "Ancient Equine Spirit", "", 0, 0 }, note = "Bring about 50 gold and 20 Enriched Manna Biscuits (sold at Chillwind Camp, requires Friendly with the Argent Dawn): make the Manna-Enriched Horse Feed at the Hillsbrad stables; inside the dungeon you can stand inside the door and clear the patrols wave by wave." },
    [7644] = { n = "Blessed Arcanite Barding", cn = "Blessed Arcanite Barding", l = 60, r = 60, f = "A", races = { 1, 3 }, s = { { 14566, "Ancient Equine Spirit", "", 0, 0 } }, e = { 928, "Lord Grayson Shadowbreaker", "Stormwind City", 48.4, 50.2, 1453 } },
    [7645] = { n = "Manna-Enriched Horse Feed", cn = "Manna-Enriched Horse Feed", l = 60, r = 60, f = "A", races = { 1, 3 }, s = { { 2357, "Merideth Carlson", "Hillsbrad Foothills", 52, 55.6, 1424 } }, e = { 2357, "Merideth Carlson", "Hillsbrad Foothills", 52, 55.6, 1424 }, items = { 18775 } },
    [7646] = { n = "The Divination Scryer", cn = "The Divination Scryer", l = 60, r = 60, f = "A", races = { 1, 3 }, s = { { 928, "Lord Grayson Shadowbreaker", "Stormwind City", 48.4, 50.2, 1453 } }, e = { 928, "Lord Grayson Shadowbreaker", "Stormwind City", 48.4, 50.2, 1453 } },
    [7647] = { n = "Judgment and Redemption", cn = "Judgment and Redemption", l = 60, r = 60, f = "A", races = { 1, 3 }, s = { { 928, "Lord Grayson Shadowbreaker", "Stormwind City", 48.4, 50.2, 1453 } }, e = { 14568, "Darkreaver's Fallen Charger", "", 0, 0 }, note = "Place the scryer at the northwest corner of the mound with the group standing diagonally; the first two waves can be pulled singly, the last two come in groups of 3+; keep Judgement of Wisdom/Light up for mitigation throughout." },
    [7648] = { n = "Grimand's Finest Work", cn = "Grimand's Finest Work", l = 60, r = 60, f = "A", races = { 1, 3 }, s = { { 1416, "Grimand Elmore", "Stormwind City", 59.7, 33.8, 1453 } }, e = { 928, "Lord Grayson Shadowbreaker", "Stormwind City", 48.4, 50.2, 1453 }, note = "After turn-in the Arcanite Barding is held temporarily and only returned once the other chain (The Path of Sacrifice) is complete - it's not lost." },
    [7666] = { n = "Again Into the Great Ossuary", cn = "Again Into the Great Ossuary", l = 60, r = 60, f = "A", s = { { 928, "Lord Grayson Shadowbreaker", "Stormwind City", 48.4, 50.2, 1453 } }, e = { 928, "Lord Grayson Shadowbreaker", "Stormwind City", 48.4, 50.2, 1453 }, items = { 18746 } },
    [7667] = { n = "Material Assistance", cn = "Material Assistance", l = 60, r = 58, f = "H", races = { 2, 6, 8, 96 }, s = { { 13417, "Sagorne Creststrider", "Orgrimmar", 38.6, 36.2, 1454 } }, e = { 13417, "Sagorne Creststrider", "Orgrimmar", 38.6, 36.2, 1454 }, note = "None of the three materials are bound; just buy them all at the Auction House, no farming needed." },
    [7668] = { n = "The Darkreaver Menace", cn = "The Darkreaver Menace", l = 60, r = 58, f = "H", s = { { 13417, "Sagorne Creststrider", "Orgrimmar", 38.6, 36.2, 1454 } }, e = { 13417, "Sagorne Creststrider", "Orgrimmar", 38.6, 36.2, 1454 }, items = { 18807 } },
    [7669] = { n = "Again Into the Great Ossuary", cn = "Again Into the Great Ossuary", l = 60, r = 58, f = "H", s = { { 13417, "Sagorne Creststrider", "Orgrimmar", 38.6, 36.2, 1454 } }, e = { 13417, "Sagorne Creststrider", "Orgrimmar", 38.6, 36.2, 1454 }, items = { 18746 } },
    [7670] = { n = "Lord Grayson Shadowbreaker", cn = "Lord Grayson Shadowbreaker", l = 60, r = 60, f = "A", races = { 1, 3 }, s = { { 5149, "Brandur Ironhammer", "Ironforge", 23.4, 6.2, 1455 } }, e = { 928, "Lord Grayson Shadowbreaker", "Stormwind City", 48.4, 50.2, 1453 }, note = "Paladin only; Grayson is in Cathedral Square in Stormwind City (Stormwind City 48,50), where two parallel epic mount chains begin." },
    [8151] = { n = "The Hunter's Charm", cn = "The Hunter's Charm", l = 52, r = 50, s = { { 3039, "Holt Thunderhorn", "Thunder Bluff", 57.4, 89.2, 1456 }, { 3352, "Ormak Grimshot", "Orgrimmar", 66.2, 18.2, 1454 }, { 4205, "Dorion", "Darnassus", 42.2, 7.6, 1457 }, { 5116, "Olmin Burningbeard", "Ironforge", 70.6, 83.8, 1455 }, { 5516, "Ulfir Ironbeard", "Stormwind City", 67.6, 35.8, 1453 } }, e = { 8405, "Ogtinc", "Azshara", 42.4, 42.6, 1447 }, note = "The target NPC is on the high ground at the edge of the ruins (Azshara 42,43): go around via the surrounding hills, don't go down into the ruins to look; the Horde version is from the hunter NPC in Orgrimmar's Valley of Honor." },
    [8153] = { n = "Courser Antlers", cn = "Courser Antlers", l = 52, r = 50, s = { { 8405, "Ogtinc", "Azshara", 42.4, 42.6, 1447 } }, e = { 8405, "Ogtinc", "Azshara", 42.4, 42.6, 1447 }, note = "Mosshoof Coursers roam both the northern and southern parts of Azshara; running back and forth between (Azshara 35,62) and (Azshara 42,72) is efficient; the drop rate is very low, so be patient." },
    [8231] = { n = "Wavethrashing", cn = "Wavethrashing", l = 52, r = 50, s = { { 8405, "Ogtinc", "Azshara", 42.4, 42.6, 1447 } }, e = { 8405, "Ogtinc", "Azshara", 42.4, 42.6, 1447 }, note = "Wavethrashers are dense in the waters around the Tower of Eldara (Azshara 86,25); elite sharks roam nearby, so if you come solo at early Lv 50, hug the shore carefully." },
    [8232] = { n = "The Green Drake", cn = "The Green Drake", l = 52, r = 50, s = { { 8405, "Ogtinc", "Azshara", 42.4, 42.6, 1447 } }, e = { 8405, "Ogtinc", "Azshara", 42.4, 42.6, 1447 }, items = { 20083, 19991, 19992 } },
    [8233] = { n = "A Simple Request", cn = "A Simple Request", l = 52, r = 50, s = { { 918, "Osborne the Night Man", "Stormwind City", 77.4, 65.3, 1453 }, { 3328, "Ormok", "Orgrimmar", 44, 54.4, 1454 }, { 4163, "Syurna", "Darnassus", 36.8, 21.8, 1457 }, { 4583, "Miles Dexter", "Undercity", 85, 71.2, 1458 }, { 5165, "Hulfdan Blackbeard", "Ironforge", 51.6, 14.8, 1455 }, { 5167, "Fenthwick", "Ironforge", 51.5, 15.3, 1455 } }, e = { 6768, "Lord Jorach Ravenholdt", "Alterac Mountains", 86, 79, 1416 }, note = "The manor entrance is at (Hillsbrad Foothills 75,23); the Horde version is picked up from Undercity rogue trainer Miles Dexter (Undercity 85,72)." },
    [8234] = { n = "Sealed Azure Bag", cn = "Sealed Azure Bag", l = 52, r = 50, s = { { 6768, "Lord Jorach Ravenholdt", "Alterac Mountains", 86, 79, 1416 } }, e = { 8379, "Archmage Xylem", "Azshara", 29.2, 40.2, 1447 }, note = "The blue bag can be pickpocketed from the shamans: Sap then Pick Pocket, usually within 8-10 tries; unrelated to Timbermaw Hold reputation, just stealth through the whole way." },
    [8235] = { n = "Encoded Fragments", cn = "Encoded Fragments", l = 52, r = 50, s = { { 8379, "Archmage Xylem", "Azshara", 29.2, 40.2, 1447 } }, e = { 8379, "Archmage Xylem", "Azshara", 29.2, 40.2, 1447 }, note = "Pick Pocket first, then kill; any beast in Azshara counts - Thunderhead Hippogryphs are especially easy and also drop the long feathers needed later." },
    [8236] = { n = "The Azure Key", cn = "The Azure Key", l = 52, r = 50, s = { { 8379, "Archmage Xylem", "Azshara", 29.2, 40.2, 1447 } }, e = { 6768, "Lord Jorach Ravenholdt", "Alterac Mountains", 86, 79, 1416 }, items = { 19984, 20255, 19982 }, note = "The two dragons are linked in the dungeon: use Vanish to pull Morphaz on his own, or pull both if you can tank it; splitting them is far easier." },
    [8249] = { n = "Junkboxes Needed", cn = "Junkboxes Needed", l = 60, r = 50, s = { { 6707, "Fahrad", "Alterac Mountains", 84.4, 80.2, 1416 } }, e = { 6707, "Fahrad", "Alterac Mountains", 84.4, 80.2, 1416 }, items = { 20086 }, note = "After opening the boxes, leave the worthless loot inside before turning in, so you get the money and keep the quest box; up to 5 per turn-in; the main source of Ravenholdt reputation." },
    [8250] = { n = "Magecraft", cn = "Magecraft", l = 52, r = 50, s = { { 331, "Maginor Dumas", "Stormwind City", 49.2, 87.8, 1453 }, { 3047, "Archmage Shymm", "Thunder Bluff", 22.6, 14.8, 1456 }, { 4567, "Pierce Shackleton", "Undercity", 85.4, 13.8, 1458 }, { 7311, "Uthel'nay", "Orgrimmar", 39, 86, 1454 }, { 7312, "Dink", "Ironforge", 26.8, 8.4, 1455 } }, e = { 8395, "Sanath Lim-yo", "Azshara", 28, 50, 1447 }, note = "Talking to Sanath teleports you up the cliff; ride the path to the top of the tower and find Selem." },
    [8251] = { n = "Magic Dust", cn = "Magic Dust", l = 52, r = 50, s = { { 8379, "Archmage Xylem", "Azshara", 29.2, 40.2, 1447 } }, e = { 8379, "Archmage Xylem", "Azshara", 29.2, 40.2, 1447 }, note = "The blood elf camp is on the hill (Azshara 55,26); the dust drop rate is average, a dozen or so kills should be enough." },
    [8252] = { n = "The Siren's Coral", cn = "The Siren's Coral", l = 52, r = 50, s = { { 8379, "Archmage Xylem", "Azshara", 29.2, 40.2, 1447 } }, e = { 8379, "Archmage Xylem", "Azshara", 29.2, 40.2, 1447 }, note = "The sirens around (Azshara 48,50) are dense and often alone, with about a one-in-three drop rate - less effort than elsewhere." },
    [8253] = { n = "Destroy Morphaz", cn = "Destroy Morphaz", l = 52, r = 50, s = { { 8379, "Archmage Xylem", "Azshara", 29.2, 40.2, 1447 } }, e = { 8379, "Archmage Xylem", "Azshara", 29.2, 40.2, 1447 }, items = { 20035, 20037, 20036 }, note = "Morphaz is on the bottom floor of the Sunken Temple, linked with another dragon; clear him while running the dungeon, not difficult." },
    [8254] = { n = "Cenarion Aid", cn = "Cenarion Aid", l = 52, r = 50, s = { { 5489, "Brother Joshua", "Stormwind City", 49.5, 45.2, 1453 }, { 6018, "Ur'kyo", "Orgrimmar", 35.6, 87.6, 1454 }, { 11406, "High Priest Rohan", "Ironforge", 25, 8.4, 1455 }, { 3045, "Malakai Cross", "Thunder Bluff", 24.6, 22.6, 1456 } }, e = { 8405, "Ogtinc", "Azshara", 42.4, 42.6, 1447 }, note = "Prepare an Ichor of Undeath in advance, it's needed in step 3; the target NPC is at (Azshara 42,42); Horde players take the equivalent from a priest trainer in Orgrimmar." },
    [8255] = { n = "Of Coursers We Know", cn = "Of Coursers We Know", l = 52, r = 50, s = { { 8405, "Ogtinc", "Azshara", 42.4, 42.6, 1447 } }, e = { 8405, "Ogtinc", "Azshara", 42.4, 42.6, 1447 }, note = "Mosshoof stags gather on the southern slopes of the mountains (around Azshara 54,25); they share spawn points with the hippogryphs, so killing a few hippogryphs when stags are scarce frees up spawns." },
    [8256] = { n = "The Ichor of Undeath", cn = "The Ichor of Undeath", l = 52, r = 50, s = { { 8405, "Ogtinc", "Azshara", 42.4, 42.6, 1447 } }, e = { 8405, "Ogtinc", "Azshara", 42.4, 42.6, 1447 }, note = "Get Ichor of Undeath beforehand by farming in the Western Plaguelands or from the Auction House; Highborne Lichlings in Azshara also drop it, but they are sparse and the drop rate is low." },
    [8257] = { n = "Blood of Morphaz", cn = "Blood of Morphaz", l = 52, r = 50, s = { { 8405, "Ogtinc", "Azshara", 42.4, 42.6, 1447 } }, e = { 10922, "Greta Mosshoof", "Felwood", 51.2, 82.2, 1448 }, items = { 19990, 20082, 20006 } },
    [8258] = { n = "The Darkreaver Menace", cn = "The Darkreaver Menace", l = 60, r = 60, f = "H", s = { { 13417, "Sagorne Creststrider", "Orgrimmar", 38.6, 36.2, 1454 } }, e = { 13417, "Sagorne Creststrider", "Orgrimmar", 38.6, 36.2, 1454 }, items = { 20134 }, note = "Clear the whole room before starting the event (the skeletons pull as soon as they spawn), and have the group fall back to the corner to the right of the basement entrance to defend; four waves in total with elite bosses between waves, so stay alert." },
    [8259] = { n = "A More Fitting Reward", cn = "A More Fitting Reward", l = 60, r = 58, f = "H", s = { { 13417, "Sagorne Creststrider", "Orgrimmar", 38.6, 36.2, 1454 } }, e = { 13417, "Sagorne Creststrider", "Orgrimmar", 38.6, 36.2, 1454 }, items = { 20134 } },
    [8410] = { n = "Elemental Mastery", cn = "Elemental Mastery", l = 52, r = 50, f = "H", races = { 2, 6, 8, 96 }, s = { { 3032, "Beram Skychaser", "Thunder Bluff", 22.2, 19, 1456 }, { 13417, "Sagorne Creststrider", "Orgrimmar", 38.6, 36.2, 1454 } }, e = { 6176, "Bath'rah the Windwatcher", "Alterac Mountains", 80.4, 66.8, 1416 }, note = "The three elemental essences come from the binding circles around Arathi with good drop rates; you only need 1 of each, no need to hoard." },
    [8411] = { n = "Mastering the Elements", cn = "Mastering the Elements", l = 52, r = 50, f = "H", s = { { 6176, "Bath'rah the Windwatcher", "Alterac Mountains", 80.4, 66.8, 1416 } }, e = { 6176, "Bath'rah the Windwatcher", "Alterac Mountains", 80.4, 66.8, 1416 } },
    [8412] = { n = "Spirit Totem", cn = "Spirit Totem", l = 52, r = 50, f = "H", races = { 2, 6, 8, 96 }, s = { { 6176, "Bath'rah the Windwatcher", "Alterac Mountains", 80.4, 66.8, 1416 } }, e = { 6176, "Bath'rah the Windwatcher", "Alterac Mountains", 80.4, 66.8, 1416 } },
    [8413] = { n = "Da Voodoo", cn = "Da Voodoo", l = 52, r = 50, f = "H", s = { { 6176, "Bath'rah the Windwatcher", "Alterac Mountains", 80.4, 66.8, 1416 } }, e = { 6176, "Bath'rah the Windwatcher", "Alterac Mountains", 80.4, 66.8, 1416 }, items = { 20369, 20503, 20556 }, note = "The trinket uses the water totem slot and is mutually exclusive with the tidal totem, so decide which to bring before pulling; later you'll need to go into the Temple of Atal'Hakkar and kill six mini-bosses." },
    [8414] = { n = "Dispelling Evil", cn = "Dispelling Evil", l = 52, r = 50, f = "A", races = { 1, 3 }, s = { { 10838, "Commander Ashlam Valorfist", "Western Plaguelands", 42.8, 84, 1422 } }, e = { 1854, "High Priest Thel'danis", "Western Plaguelands", 52, 82.8, 1422 }, note = "Don't just talk - the commission only works when equipped in a trinket slot; if quest items aren't dropping, first check that you have it equipped." },
    [8415] = { n = "Chillwind Point", cn = "Chillwind Point", l = 52, r = 50, f = "A", races = { 1, 3 }, s = { { 928, "Lord Grayson Shadowbreaker", "Stormwind City", 48.4, 50.2, 1453 }, { 5149, "Brandur Ironhammer", "Ironforge", 23.4, 6.2, 1455 } }, e = { 10838, "Commander Ashlam Valorfist", "Western Plaguelands", 42.8, 84, 1422 } },
    [8416] = { n = "Inert Scourgestones", cn = "Inert Scourgestones", l = 52, r = 50, f = "A", races = { 1, 3 }, s = { { 1854, "High Priest Thel'danis", "Western Plaguelands", 52, 82.8, 1422 } }, e = { 10838, "Commander Ashlam Valorfist", "Western Plaguelands", 42.8, 84, 1422 } },
    [8417] = { n = "A Troubled Spirit", cn = "A Troubled Spirit", l = 52, r = 50, s = { { 3354, "Sorek", "Orgrimmar", 80.2, 32.4, 1454 }, { 4593, "Christoph Walker", "Undercity", 47.2, 15.2, 1458 }, { 5113, "Kelv Sternhammer", "Ironforge", 70, 90.6, 1455 }, { 5479, "Wu Shen", "Stormwind City", 80.5, 59.9, 1453 }, { 7315, "Darnath Bladesinger", "Darnassus", 58.6, 35.4, 1457 }, { 3041, "Torm Ragetotem", "Thunder Bluff", 57.2, 87.4, 1456 } }, e = { 7572, "Fallen Hero of the Horde", "Swamp of Sorrows", 34.2, 66, 1435 }, note = "Introductory quest given by capital-city warrior trainers from Lv 50; the target, the \"Fallen Hero\", is by the road at the southern tip of the Swamp of Sorrows (Swamp of Sorrows 34,66)." },
    [8418] = { n = "Forging the Mightstone", cn = "Forging the Mightstone", l = 52, r = 50, f = "A", races = { 1, 3 }, s = { { 10838, "Commander Ashlam Valorfist", "Western Plaguelands", 42.8, 84, 1422 } }, e = { 10838, "Commander Ashlam Valorfist", "Western Plaguelands", 42.8, 84, 1422 }, items = { 20620, 20504, 20512, 20505 }, note = "The Lightforce Stone is unique and single-use, so choose your fight carefully; at Lv 50 the trinket is worth roughly 3.7% crit." },
    [8419] = { n = "An Imp's Request", cn = "An Imp's Request", l = 52, r = 50, s = { { 461, "Demisette Cloyce", "Stormwind City", 39.2, 85, 1453 }, { 3326, "Zevrost", "Orgrimmar", 48.4, 45.6, 1454 }, { 4563, "Kaal Soulreaper", "Undercity", 86, 15.6, 1458 }, { 5172, "Briarthorn", "Ironforge", 50.2, 6, 1455 } }, e = { 14470, "Impsy", "Felwood", 41.4, 44.8, 1448 }, note = "Available at level 50; the Horde version is from the demon trainer in Undercity or Orgrimmar; you can farm your own Felcloth from satyrs in Felwood, and pick up Impsy's Infernal quest on the way." },
    [8420] = { n = "Hot and Itchy", cn = "Hot and Itchy", l = 52, r = 50, s = { { 14470, "Impsy", "Felwood", 41.4, 44.8, 1448 } }, e = { 14470, "Impsy", "Felwood", 41.4, 44.8, 1448 } },
    [8421] = { n = "The Wrong Stuff", cn = "The Wrong Stuff", l = 52, r = 50, s = { { 14470, "Impsy", "Felwood", 41.4, 44.8, 1448 } }, e = { 14470, "Impsy", "Felwood", 41.4, 44.8, 1448 }, note = "Rotting Wood is in Irontree Woods (Felwood 47,26), and passing treants have a higher drop rate; Tainted Ooze farms faster by the lake (Felwood 42,45); Blood Venom Essence drops about 80% of the time." },
    [8422] = { n = "Trolls of a Feather", cn = "Trolls of a Feather", l = 52, r = 50, s = { { 14470, "Impsy", "Felwood", 41.4, 44.8, 1448 } }, e = { 14470, "Impsy", "Felwood", 41.4, 44.8, 1448 }, items = { 20536, 20534, 20530 } },
    [8423] = { n = "Warrior Kinship", cn = "Warrior Kinship", l = 52, r = 50, s = { { 7572, "Fallen Hero of the Horde", "Swamp of Sorrows", 34.2, 66, 1435 } }, e = { 7572, "Fallen Hero of the Horde", "Swamp of Sorrows", 34.2, 66, 1435 }, note = "The target herds roam west of the Dark Portal (around Blasted Lands 51,54), soloable by Lv 53 warriors; if there aren't enough, wait a few minutes for respawns." },
    [8424] = { n = "War on the Shadowsworn", cn = "War on the Shadowsworn", l = 52, r = 50, s = { { 7572, "Fallen Hero of the Horde", "Swamp of Sorrows", 34.2, 66, 1435 } }, e = { 7572, "Fallen Hero of the Horde", "Swamp of Sorrows", 34.2, 66, 1435 }, note = "The Shadowsworn are concentrated between Nethergarde Keep and the Dark Portal (Blasted Lands 64,32), with more in nearby caves; beware the \"Servant of Allistarj\" next to the crystals — it's another quest's mob, and you can't damage it unless you can use the crystal." },
    [8425] = { n = "Voodoo Feathers", cn = "Voodoo Feathers", l = 52, r = 50, s = { { 7572, "Fallen Hero of the Horde", "Swamp of Sorrows", 34.2, 66, 1435 } }, e = { 7572, "Fallen Hero of the Horde", "Swamp of Sorrows", 34.2, 66, 1435 }, items = { 20521, 20130, 20517 }, note = "On completion you get a 15-minute +400 attack power buff; you can farm mobs in the Blasted Lands for 15 minutes for the XP." },
    [9051] = { n = "Toxic Test", cn = "Toxic Test", l = 52, r = 50, s = { { 9619, "Torwa Pathfinder", "Un'Goro Crater", 71.6, 76, 1449 } }, e = { 9619, "Torwa Pathfinder", "Un'Goro Crater", 71.6, 76, 1449 }, note = "Be patient finding a Devilsaur; when you do, Hibernate it, stab it once and run, don't fight it." },
    [9052] = { n = "Bloodpetal Poison", cn = "Bloodpetal Poison", l = 52, r = 50, s = { { 9619, "Torwa Pathfinder", "Un'Goro Crater", 71.6, 76, 1449 } }, e = { 9619, "Torwa Pathfinder", "Un'Goro Crater", 71.6, 76, 1449 }, items = { 13446 }, note = "Stingers drop from the wasps at (Un'Goro Crater - The Slithering Scar 50,76) at a low rate; Bloodcaps are hidden in Bloodpetal Sprouts — sprouts holding one will sparkle, so only pick the glowing ones. Herbalists, turn off Find Herbs to avoid interference." },
    [9053] = { n = "A Better Ingredient", cn = "A Better Ingredient", l = 52, r = 50, s = { { 9619, "Torwa Pathfinder", "Un'Goro Crater", 71.6, 76, 1449 } }, e = { 9619, "Torwa Pathfinder", "Un'Goro Crater", 71.6, 76, 1449 }, items = { 22274, 22272, 22458 }, note = "Light the six statues in clock order: 6 o'clock -> 12 -> 8 -> 4 -> 10 -> 2, i.e. south, north, southwest, southeast, northwest, northeast; correct statues glow green." },
    [9063] = { n = "Torwa Pathfinder", cn = "Torwa Pathfinder", l = 52, r = 50, s = { { 3033, "Turak Runetotem", "Thunder Bluff", 76.4, 27.6, 1456 }, { 4217, "Mathrengyl Bearwalker", "Darnassus", 35.2, 8, 1457 }, { 5505, "Theridran", "Stormwind City", 36.1, 64.4, 1453 }, { 12042, "Loganaar", "Moonglade", 52.4, 40.4, 1450 } }, e = { 9619, "Torwa Pathfinder", "Un'Goro Crater", 71.6, 76, 1449 }, note = "Given by class trainers at Lv 50: Alliance from Mathrengyl Bearwalker in Darnassus (not Denatharion), Horde from Jannos Lighthoof at Camp Mojache." },
    [9362] = { n = "Warlord Krellian", cn = "Warlord Krellian", l = 60, r = 60, s = { { 8379, "Archmage Xylem", "Azshara", 29.2, 40.2, 1447 } }, e = { 8379, "Archmage Xylem", "Azshara", 29.2, 40.2, 1447 }, note = "On the way, you can go to the upper level of the temple for the rare elite \"General Fangferror\", about a 2-hour respawn and easy at Lv 60; stand downstairs and type his name into a target macro to check." },
    [9364] = { n = "Fragmented Magic", cn = "Fragmented Magic", l = 60, r = 60, s = { { 8379, "Archmage Xylem", "Azshara", 29.2, 40.2, 1447 } }, e = { 8379, "Archmage Xylem", "Azshara", 29.2, 40.2, 1447 }, spells = { 28272 }, note = "Move in close right after polymorphing the naga: it splits into 2-5 copies, and a single Arcane Explosion or Frost Nova catches them all; don't use Polymorph: Turtle — turtle form doesn't split." },
    [65593] = { n = "Hearts of the Lovers", cn = "Hearts of the Lovers", l = 20, r = 20, f = "H", races = { 2, 5, 8 }, s = { { 5693, "Godrick Farsan", "Undercity", 85, 14.8, 1458 } }, e = { 5675, "Carendin Halgar", "Undercity", 85, 25.6, 1458 } },
    [65597] = { n = "The Binding", cn = "The Binding", l = 20, r = 20, f = "H", s = { { 5675, "Carendin Halgar", "Undercity", 85, 25.6, 1458 } }, e = { 5675, "Carendin Halgar", "Undercity", 85, 25.6, 1458 }, items = { 22243 }, spells = { 713 } },
    [65601] = { n = "Love Hurts", cn = "Love Hurts", l = 20, r = 20, f = "H", races = { 2, 5, 8 }, s = { { 5909, "Cazul", "Orgrimmar", 47.2, 46.6, 1454 } }, e = { 3363, "Magar", "Orgrimmar", 63.4, 50, 1454 } },
    [65602] = { n = "What Is Love?", cn = "What Is Love?", l = 20, r = 20, f = "A", races = { 1, 7 }, s = { { 6244, "Takar the Seer", "The Barrens", 49.2, 57, 1413 } }, e = { 6122, "Gakin the Darkbinder", "Stormwind City", 39.2, 85.2, 1453 }, note = "The target carving is on the second floor inside the house, and the NPC won't let you just take it: first grab the unlit torch from the table outside. Lighting it needs a campfire — with Cooking you can build one on the spot; otherwise borrow fire from Talen's campfire on the Zoram Strand (Ashenvale 15,31). It only stays lit for 5 minutes, so don't detour — head straight back to the handcart outside the house to finish lighting it." },
    [65603] = { n = "The Binding", cn = "The Binding", l = 20, r = 20, f = "A", races = { 1, 7 }, s = { { 6122, "Gakin the Darkbinder", "Stormwind City", 39.2, 85.2, 1453 } }, e = { 6122, "Gakin the Darkbinder", "Stormwind City", 39.2, 85.2, 1453 }, items = { 22243 }, spells = { 713 } },
    [65604] = { n = "The Binding", cn = "The Binding", l = 20, r = 20, f = "H", races = { 2, 5 }, s = { { 5875, "Gan'rul Bloodeye", "Orgrimmar", 48.2, 45.6, 1454 } }, e = { 5875, "Gan'rul Bloodeye", "Orgrimmar", 48.2, 45.6, 1454 }, items = { 22243 }, spells = { 713 }, note = "Same source as the Succubus summon: Summon Incubus is a separate spell and doesn't share demon spellbooks with the Succubus; if you want to use both, buy each book separately, so pick your main one before investing." },
    [65610] = { n = "Wish You Were Here", cn = "Wish You Were Here", l = 27, r = 20, f = "H", races = { 2, 5, 8 }, s = { { 3363, "Magar", "Orgrimmar", 63.4, 50, 1454 } }, e = { 5875, "Gan'rul Bloodeye", "Orgrimmar", 48.2, 45.6, 1454 } },
    [78088] = { n = "A Strange Artifact", cn = "A Strange Artifact", l = 30, r = 22, f = "A", s = { { 409289, "Strange Orb", "Darkshore", 56.2, 26.4, 1439 } }, e = { 3663, "Delgren the Purifier", "Ashenvale", 26.2, 38.6, 1440 } },
    [78089] = { n = "Advice From Stormwind", cn = "Advice From Stormwind", l = 30, r = 22, f = "A", races = { 1, 3 }, s = { { 3663, "Delgren the Purifier", "Ashenvale", 26.2, 38.6, 1440 } }, e = { 5492, "Katherine the Pure", "Stormwind City", 48.5, 49.1, 1453 }, note = "This is one step of a chain: first go to the top floor of the Tower of Althalaxx (Darkshore 56,27) and take the prerequisite from the orb; this quest only appears after that." },
    [78090] = { n = "A Second Opinion", cn = "A Second Opinion", l = 30, r = 22, f = "A", races = { 1, 3 }, s = { { 5492, "Katherine the Pure", "Stormwind City", 48.5, 49.1, 1453 } }, e = { 5495, "Ursula Deline", "Stormwind City", 26.2, 77.4, 1453 } },
    [78091] = { n = "Earning Your Salt", cn = "Earning Your Salt", l = 30, r = 22, f = "A", races = { 1, 3 }, s = { { 5495, "Ursula Deline", "Stormwind City", 26.2, 77.4, 1453 } }, e = { 5495, "Ursula Deline", "Stormwind City", 26.2, 77.4, 1453 }, note = "The prerequisite chain starts from the orb on the top floor of the Tower of Althalaxx (Darkshore 56,27); if the NPC has no question mark, first check that the prerequisites are done." },
    [78092] = { n = "It Must Be Destroyed", cn = "It Must Be Destroyed", l = 30, r = 22, f = "A", races = { 1, 3 }, s = { { 5495, "Ursula Deline", "Stormwind City", 26.2, 77.4, 1453 } }, e = { 409311, "Spear of Mannoroth", "Ashenvale", 89.4, 77.1, 1440 } },
    [78093] = { n = "Return to Delgren", cn = "Return to Delgren", l = 30, r = 22, f = "A", races = { 1, 3 }, s = { { 409315, "Shattered Orb", "Ashenvale", 89.4, 77, 1440 } }, e = { 3663, "Delgren the Purifier", "Ashenvale", 26.2, 38.6, 1440 }, items = { 277205 } },
    [78261] = { n = "The Horn of Xelthos", cn = "The Horn of Xelthos", l = 23, r = 1, s = { { 410369, "Dead Drop", "Silverpine Forest", 47.1, 71.1, 1421 } }, e = { 410369, "Dead Drop", "Silverpine Forest", 47.1, 71.1, 1421 }, note = "Picked up from the dead drop in the house by Pyrewood Village outside Shadowfang Keep (Silverpine Forest 47,71). At level 20, max out Master of Deception (Night Elves with the racial bonus only need 1/3); at 24 or once you have Vanish, you don't need it. Approach: Sap the guard -> pull the lever -> stealth to the far end of the cage and talk; if you're knocked out of stealth, use Vanish to escape. If your stealth isn't good enough you can die on purpose: run your ghost into the cage and talk, don't resurrect yet — wait for the NPC to open the door, then release, and the cage door will stay open. If opening the chest gives an internal bag error, the key is destroyed and you won't get the horn — you'll have to abandon and retake the quest." },
    [78270] = { n = "Goblin Lockpicks", cn = "Goblin Lockpicks", l = 23, r = 1, s = { { 4086, "Veenix", "Stonetalon Mountains", 58.2, 51.6, 1442 } }, e = { 4086, "Veenix", "Stonetalon Mountains", 58.2, 51.6, 1442 }, items = { 210186 } },
    [78307] = { n = "The Horn of Xelthos", cn = "The Horn of Xelthos", l = 23, r = 1, e = { 410369, "Dead Drop", "Silverpine Forest", 47.1, 71.1, 1421 }, items = { 277210, 203994 }, note = "After this step, return to the dead drop (Silverpine Forest 47,71) for the follow-up letter; \"C\"'s next mail only arrives after a trip back to a capital city, so don't just wait around." },
    [78676] = { n = "The Eye of Bhossca", cn = "The Eye of Bhossca", l = 35, r = 25, s = { { 410369, "Dead Drop", "Silverpine Forest", 47.1, 71.1, 1421 } }, e = { 410369, "Dead Drop", "Silverpine Forest", 47.1, 71.1, 1421 }, note = "Triggered by a letter from 'C' after level 30; picked up at the same place as 'Sheltos Horn': the dead drop by Pyrewood Village (Silverpine Forest 47,71). The quest requires entering the Scarlet Monastery — first grab the Scarlet Apprentice Uniform disguise from the stable outside the monastery (Tirisfal Glades 81,32); staying disguised the whole way makes it much easier." },
    [78699] = { n = "The Eye of Bhossca", cn = "The Eye of Bhossca", l = 35, r = 25, e = { 410369, "Dead Drop", "Silverpine Forest", 47.1, 71.1, 1421 }, items = { 277246, 210979 }, note = "Wear the disguise into the graveyard flank; if an elite is guarding the sarcophagus, go around behind the northern mausoleum and open it through the wall with the interact key to avoid combat; note that afterward you still need to return to the dead drop, collect mail in a capital, then go back to the dead drop again to close the loop." },
    [78830] = { n = "Terror of the Desert Skies", cn = "Terror of the Desert Skies", l = 40, r = 26, s = { { 715, "Hemet Nesingwary", "Stranglethorn Vale", 35.6, 10.8, 1434 } }, e = { 715, "Hemet Nesingwary", "Stranglethorn Vale", 35.6, 10.8, 1434 }, items = { 277207, 277209 }, note = "Hemet is at Nesingwary's Expedition in southern Stranglethorn Vale; for the Scarlet Plumes you have to kill \"Garrick\" in the Badlands; available at level 26, but the mobs on the way are noticeably higher level than the quest, so 30+ is safer." },
    [79358] = { n = "Storm, Earth, and Fire", cn = "Storm, Earth, and Fire", l = 43, r = 30, s = { { 259023, "Veyric Thunderhame", "Arathi Highlands", 59.8, 27.6, 1417 } }, e = { 259023, "Veyric Thunderhame", "Arathi Highlands", 59.8, 27.6, 1417 }, note = "Level 43 quest; the four mob types are on four maps: around Maraudon in Desolace, the murlocs in northeast Dustwallow Marsh, the troggs in south-central Badlands, and the Lost Ones in north-central Swamp of Sorrows. Though marked Horde, the Alliance can do it too. The Desolace spot respawns slowly — chain all four maps into one route." },
    [79360] = { n = "Elemental Aid", cn = "Elemental Aid", l = 33, r = 30, f = "H", s = { { 4722, "Rau Cliffrunner", "Thousand Needles", 46, 51.6, 1441 }, { 5905, "Prate Cloudseer", "Thousand Needles", 53.6, 42.8, 1441 } }, e = { 4722, "Rau Cliffrunner", "Thousand Needles", 46, 51.6, 1441 } },
    [79361] = { n = "Storm, Earth, and Fire", cn = "Storm, Earth, and Fire", l = 43, r = 30, f = "H", races = { 2, 6, 8, 96 }, s = { { 5905, "Prate Cloudseer", "Thousand Needles", 53.6, 42.8, 1441 }, { 6176, "Bath'rah the Windwatcher", "Alterac Mountains", 80.4, 66.8, 1416 } }, e = { 6176, "Bath'rah the Windwatcher", "Alterac Mountains", 80.4, 66.8, 1416 }, note = "There are two hidden prerequisites: after completing the Air totem quest \"Call of Air\" at level 30, pick up \"Elemental Aid\" from the same NPC (requires a trip to Razorfen Kraul); this quest only appears after both are done." },
    [79364] = { n = "Eyes on the Sky", cn = "Eyes on the Sky", l = 33, r = 30, f = "H", s = { { 4722, "Rau Cliffrunner", "Thousand Needles", 46, 51.6, 1441 }, { 6176, "Bath'rah the Windwatcher", "Alterac Mountains", 80.4, 66.8, 1416 } }, e = { 5905, "Prate Cloudseer", "Thousand Needles", 53.6, 42.8, 1441 } },
    [79365] = { n = "With Wind Beneath Your Wings", cn = "With Wind Beneath Your Wings", l = 40, r = 30, f = "H", races = { 2, 6, 8 }, s = { { 6176, "Bath'rah the Windwatcher", "Alterac Mountains", 80.4, 66.8, 1416 } }, e = { 4722, "Rau Cliffrunner", "Thousand Needles", 46, 51.6, 1441 } },
    [79366] = { n = "Heed My Call", cn = "Heed My Call", l = 40, r = 30, f = "H", s = { { 4722, "Rau Cliffrunner", "Thousand Needles", 46, 51.6, 1441 }, { 5905, "Prate Cloudseer", "Thousand Needles", 53.6, 42.8, 1441 } }, e = { 4722, "Rau Cliffrunner", "Thousand Needles", 46, 51.6, 1441 }, items = { 212994, 212996, 212997 }, note = "When grouping, some members have sometimes been unable to loot the quest item after the final boss dies; if you can't loot it, check loot rights first, and kill it again solo if needed." },
    [79442] = { n = "The Tempest's Weapons", cn = "The Tempest's Weapons", l = 40, r = 30, f = "H", races = { 2, 6, 8, 96 }, s = { { 4722, "Rau Cliffrunner", "Thousand Needles", 46, 51.6, 1441 } }, e = { 6176, "Bath'rah the Windwatcher", "Alterac Mountains", 80.4, 66.8, 1416 }, items = { 213086, 280604, 280605, 280607 } },
    [79731] = { n = "The Troll Scroll", cn = "The Troll Scroll", l = 35, r = 1, e = { 715, "Hemet Nesingwary", "Stranglethorn Vale", 35.6, 10.8, 1434 } },
    [79939] = { n = "The Broken Hammer", cn = "The Broken Hammer", l = 40, r = 35, f = "A", s = { { 423703, "Broken Warhammer", "Desolace", 52.7, 84.8, 1443 } }, e = { 5492, "Katherine the Pure", "Stormwind City", 48.5, 49.1, 1453 }, note = "The starting point is the warhammer at the meeting place itself; pick it up together with the shredded letter beside it, then return to Katherine at Stormwind Cathedral." },
    [79940] = { n = "A Lost Brother", cn = "A Lost Brother", l = 40, r = 35, f = "A", s = { { 5492, "Katherine the Pure", "Stormwind City", 48.5, 49.1, 1453 } }, e = { 5492, "Katherine the Pure", "Stormwind City", 48.5, 49.1, 1453 }, note = "Dialogue only; on turn-in, immediately pick up 'Aeonas's Secret Refuge'." },
    [79945] = { n = "Orders from the Grand Crusader", cn = "Orders from the Grand Crusader", l = 40, r = 35, f = "A", e = { 5492, "Katherine the Pure", "Stormwind City", 48.5, 49.1, 1453 }, note = "Item-triggered, no NPC needed: pick up the letter at the refuge scene and bring it back to Katherine at Stormwind Cathedral." },
    [79946] = { n = "A Brother In Need", cn = "A Brother In Need", l = 40, r = 35, f = "A", s = { { 5492, "Katherine the Pure", "Stormwind City", 48.5, 49.1, 1453 } }, e = { 217996, "Aeonas", "Scarlet Monastery" }, note = "You need to find someone in the Scarlet Monastery in Tirisfal Glades: fight from the Cathedral wing all the way to the courtyard; soloing at Lv 40 is tough, group up or come back at Lv 45." },
    [79963] = { n = "By The Light's Grace", cn = "By The Light's Grace", l = 40, r = 35, f = "A", s = { { 217996, "Aeonas", "Scarlet Monastery" } }, e = { 217996, "Aeonas", "Scarlet Monastery" }, note = "In the monastery, cast heals on Aionas until he's at full health to complete; healing potions don't count." },
    [79970] = { n = "Aeonas the Vindicated", cn = "Aeonas the Vindicated", l = 40, r = 35, f = "A", s = { { 217996, "Aeonas", "Scarlet Monastery" } }, e = { 218160, "Aeonas the Vindicated", "Stormwind City", 48.5, 48.9, 1453 }, items = { 277236 }, note = "Return to Aionas at the Cathedral of Light in Stormwind; the reward is the plate shoulders \"Pauldrons of Vindication\", plenty good for the Lv 40 range." },
    [80411] = { n = "The Talisman of Kazdor", cn = "The Talisman of Kazdor", l = 50, r = 45, s = { { 6707, "Fahrad", "Alterac Mountains", 84.4, 80.2, 1416 } }, e = { 6707, "Fahrad", "Alterac Mountains", 84.4, 80.2, 1416 }, note = "The charm is in Zul'Farrak (Tanaris); the quest must be done solo and can't be turned in while grouped - leave your group before going in." },
    [80526] = { n = "Fool Me Twice", cn = "Fool Me Twice", l = 50, r = 45, s = { { 6707, "Fahrad", "Alterac Mountains", 84.4, 80.2, 1416 } }, e = { 6707, "Fahrad", "Alterac Mountains", 84.4, 80.2, 1416 }, note = "Fahrad is at Ravenholdt Manor; the path up the mountain is behind the high ground north of Durnholde Keep - just keep heading up." },
    [80453] = { n = "Best Laid Plans", cn = "Best Laid Plans", l = 50, r = 45, s = { { 6777, "Zan Shivsproket", "Alterac Mountains", 86, 80, 1416 } }, e = { 410369, "Dead Drop", "Silverpine Forest", 47.1, 71.1, 1421 }, note = "One of the final three steps of the Talisman of Kazdor chain: continue from Zan Shivsproket and leave the goods in the Dead Drop in Silverpine Forest." },
    [80454] = { n = "One Last Drop", cn = "One Last Drop", l = 50, r = 45, s = { { 6777, "Zan Shivsproket", "Alterac Mountains", 86, 80, 1416 } }, e = { 410369, "Dead Drop", "Silverpine Forest", 47.1, 71.1, 1421 }, note = "Wrapping up the Talisman of Kazdor chain: more running between Alterac and the Dead Drop in Silverpine Forest - just follow the quest tracker." },
    [80455] = { n = "Biding Our Time", cn = "Biding Our Time", l = 50, r = 45, s = { { 410369, "Dead Drop", "Silverpine Forest", 47.1, 71.1, 1421 } }, e = { 6707, "Fahrad", "Alterac Mountains", 84.4, 80.2, 1416 }, items = { 219343, 217736 }, note = "Last step of the Talisman of Kazdor chain: collect the items from the Dead Drop and return them to Fahrad at Ravenholdt Manor. Rewards Filcher's Cowl and Rune of the Coterie." },
    [81762] = { n = "Some Good News", cn = "Some Good News", l = 50, r = 45, f = "A", s = { { 218160, "Aeonas the Vindicated", "Stormwind City", 48.5, 48.9, 1453 } }, e = { 5492, "Katherine the Pure", "Stormwind City", 48.5, 49.1, 1453 }, note = "Dialogue-only quest available at level 45; both NPCs are in the Cathedral of Light." },
    [81764] = { n = "The Mysterious Merchant", cn = "The Mysterious Merchant", l = 50, r = 45, f = "A", s = { { 5492, "Katherine the Pure", "Stormwind City", 48.5, 49.1, 1453 } }, e = { 221575, "Elrick", "Dustwallow Marsh", 66.4, 45.4, 1445 }, note = "Theramore is on the southeast coast of Dustwallow Marsh and the merchant is right by the inn door; take the boat or fly straight to Theramore." },
    [81765] = { n = "Elrick, Paladin of the Silver Hand", cn = "Elrick, Paladin of the Silver Hand", l = 50, r = 45, f = "A", s = { { 221575, "Elrick", "Dustwallow Marsh", 66.4, 45.4, 1445 } }, e = { 6272, "Innkeeper Janene", "Dustwallow Marsh", 66.6, 45.2, 1445 }, note = "Talk to Elric first, then go into the Theramore inn and speak with Innkeeper Janene." },
    [81766] = { n = "The Bloody Missive", cn = "The Bloody Missive", l = 50, r = 45, f = "A", e = { 5492, "Katherine the Pure", "Stormwind City", 48.5, 49.1, 1453 }, note = "Item-triggered: the letter is looted from Elric; after reading it, take it to Katherine at Stormwind Cathedral." },
    [81790] = { n = "Materials of Significance", cn = "Materials of Significance", l = 53, r = 45, f = "A", s = { { 221636, "Gregory", "Felwood", 44.6, 52, 1448 } }, e = { 221636, "Gregory", "Felwood", 44.6, 52, 1448 } },
    [81885] = { n = "The Ritual", cn = "The Ritual", l = 53, r = 45, f = "A", s = { { 221587, "Aeonas the Vindicated", "Felwood", 45, 52, 1448 } }, e = { 221587, "Aeonas the Vindicated", "Felwood", 45, 52, 1448 } },
    [81944] = { n = "A Newly Discovered Purpose...", cn = "A Newly Discovered Purpose...", l = 53, r = 45, f = "A", s = { { 214529, "Brave Stonetorch", "Hillsbrad Foothills", 65.8, 19.6, 1424 } }, e = { 214529, "Brave Stonetorch", "Hillsbrad Foothills", 65.8, 19.6, 1424 } },
    [82135] = { n = "The Price of Hope", cn = "The Price of Hope", l = 53, r = 45, f = "A", s = { { 221587, "Aeonas the Vindicated", "Felwood", 45, 52, 1448 } }, e = { 5492, "Katherine the Pure", "Stormwind City", 48.5, 49.1, 1453 } },
    [81924] = { n = "Wisdom of the Guardians", cn = "Wisdom of the Guardians", l = 50, r = 40, s = { { 221985, "Tyrisius", "Feralas", 57.2, 69, 1444 } }, e = { 221985, "Tyrisius", "Feralas", 57.2, 69, 1444 }, note = "Prove yourself to the guardian spirits in Feralas, The Hinterlands and Azshara, in any order; all are reach-and-talk objectives; when done, return to Tirisius in Feralas." },
    [82084] = { n = "A Lesson in Literacy", cn = "A Lesson in Literacy", l = 45, r = 42, s = { { 211033, "Garion Wendell", "Stormwind City", 48.9, 86.5, 1453 }, { 211022, "Owen Thadd", "Undercity", 73.6, 33, 1458 } }, e = { 211022, "Owen Thadd", "Undercity", 73.6, 33, 1458 }, items = { 221344 }, note = "Requires 1 Pristine Owlbeast Feather, 5 Zukash Insect Resin and 8 Farraki Papyrus; all three are tradeable and can be bought at the Auction House." },
    [84318] = { n = "Oi!", cn = "Oi!", l = 57, r = 54, s = { { 228619, "Orthas", "Eastern Plaguelands", 61.2, 69.2, 1423 } }, e = { 228619, "Orthas", "Eastern Plaguelands", 61.2, 69.2, 1423 }, note = "Ortaz is at Corin's Crossing and the warhammer is lying on the ground nearby; just pick it up and bring it to him, no need to wander off." },
    [84319] = { n = "Oh No Ye Don't!", cn = "Oh No Ye Don't!", l = 57, r = 54, s = { { 228619, "Orthas", "Eastern Plaguelands", 61.2, 69.2, 1423 } }, e = { 228619, "Orthas", "Eastern Plaguelands", 61.2, 69.2, 1423 } },
    [84330] = { n = "A Wee Bit O' Necromancy", cn = "A Wee Bit O' Necromancy", l = 59, r = 54, s = { { 228619, "Orthas", "Eastern Plaguelands", 61.2, 69.2, 1423 } }, e = { 229018, "Rotting Dwarf Corpse", "Eastern Plaguelands", 23.1, 73.3, 1423 } },
    [84332] = { n = "A Thane's Gratitude", cn = "A Thane's Gratitude", l = 57, r = 54, s = { { 462236, "Chest", "Eastern Plaguelands", 27.5, 85.8, 1423 } }, e = { 462236, "Chest", "Eastern Plaguelands", 27.5, 85.8, 1423 } },
    [84414] = { n = "Send Me On Me Way", cn = "Send Me On Me Way", l = 57, r = 54, s = { { 229018, "Rotting Dwarf Corpse", "Eastern Plaguelands", 23.1, 73.3, 1423 } }, e = { 462236, "Chest", "Eastern Plaguelands", 27.5, 85.8, 1423 } },
    [90789] = { n = "Scalebeard", cn = "Scalebeard", l = 60, r = 60, s = { { 8379, "Archmage Xylem", "Azshara", 29.2, 40.2, 1447 } }, e = { 8379, "Archmage Xylem", "Azshara", 29.2, 40.2, 1447 }, note = "Archmage Xylem is in the tower on the Azshara cliffs; the Iridescent Shells are underwater along the Azshara coast - collect them and bring them back up to him." },
    [90902] = { n = "Rediscovering the Light", cn = "Rediscovering the Light", l = 2, r = 2, f = "H", races = { 5 }, s = { { 244808, "Aramis Hammerhand", "Tirisfal Glades", 31, 66.2, 1420 } }, e = { 244808, "Aramis Hammerhand", "Tirisfal Glades", 31, 66.2, 1420 }, spells = { 635 }, note = "The actual prerequisites are \"The Mindless Ones\" -> \"The Hard Way\"; both must be done before this quest opens - don't waste trips on the prerequisite listed on the page." },
    [91208] = { n = "Coming to Terms", cn = "Coming to Terms", l = 4, r = 4, f = "H", races = { 5 }, s = { { 244808, "Aramis Hammerhand", "Tirisfal Glades", 31, 66.2, 1420 } }, e = { 244808, "Aramis Hammerhand", "Tirisfal Glades", 31, 66.2, 1420 }, note = "The target spot is just south of the bat cave (27.7,63.8); if you can't find it near the cave mouth, look further south." },
    [91209] = { n = "Continue Your Training", cn = "Continue Your Training", l = 4, r = 4, f = "H", races = { 5 }, s = { { 244808, "Aramis Hammerhand", "Tirisfal Glades", 31, 66.2, 1420 } }, e = { 246152, "Shari Stilwell", "Tirisfal Glades", 60.2, 52.6, 1420 } },
    [91282] = { n = "A Second Home", cn = "A Second Home", l = 11, r = 8, f = "H", races = { 5 }, s = { { 246152, "Shari Stilwell", "Tirisfal Glades", 60.2, 52.6, 1420 } }, e = { 246349, "Breton Samuels", "Tirisfal Glades", 21.8, 45.2, 1420 } },
    [91285] = { n = "Murlocs at the Gates", cn = "Murlocs at the Gates", l = 11, r = 7, f = "H", races = { 5 }, s = { { 246349, "Breton Samuels", "Tirisfal Glades", 21.8, 45.2, 1420 } }, e = { 246349, "Breton Samuels", "Tirisfal Glades", 21.8, 45.2, 1420 }, items = { 246164, 246165 } },
    [91294] = { n = "Touring the Grounds", cn = "Touring the Grounds", l = 11, r = 8, f = "H", races = { 5 }, s = { { 246349, "Breton Samuels", "Tirisfal Glades", 21.8, 45.2, 1420 } }, e = { 246378, "Danitha Morr", "Tirisfal Glades", 22, 44.6, 1420 } },
    [91316] = { n = "Making Repairs", cn = "Making Repairs", l = 11, r = 8, f = "H", races = { 5 }, s = { { 246393, "Jorin Croge", "Tirisfal Glades", 22.6, 44.8, 1420 } }, e = { 246393, "Jorin Croge", "Tirisfal Glades", 22.6, 44.8, 1420 }, items = { 246265 }, note = "The quest objects are piles of wooden beams on the floor inside the Shadow Vale Crypt; the crypt entrance is at (12.9,65.9)." },
    [91317] = { n = "The Tarnished", cn = "The Tarnished", l = 12, r = 9, f = "H", races = { 5 }, s = { { 246378, "Danitha Morr", "Tirisfal Glades", 22, 44.6, 1420 } }, e = { 246378, "Danitha Morr", "Tirisfal Glades", 22, 44.6, 1420 }, note = "Rudolph Gerhardt is on the second floor of a house (11.6,64.2), with three laborers guarding downstairs; check the stairway before going up." },
    [91858] = { n = "Diplomatic Incident", cn = "Diplomatic Incident", l = 22, r = 18, f = "H", races = { 5 }, s = { { 246378, "Danitha Morr", "Tirisfal Glades", 22, 44.6, 1420 } }, e = { 248840, "Trevan Rol", "Silverpine Forest", 43.4, 41, 1421 } },
    [91859] = { n = "A Curious Pair", cn = "A Curious Pair", l = 22, r = 18, f = "H", races = { 5 }, s = { { 248840, "Trevan Rol", "Silverpine Forest", 43.4, 41, 1421 } }, e = { 259611, "Deathguard Baldren", "Silverpine Forest", 45.8, 41.8, 1421 } },
    [91860] = { n = "A Grim Fate", cn = "A Grim Fate", l = 22, r = 18, f = "H", races = { 5 }, s = { { 259611, "Deathguard Baldren", "Silverpine Forest", 45.8, 41.8, 1421 } }, e = { 566037, "Charred Remains", "Silverpine Forest", 65, 34.2, 1421 } },
    [91861] = { n = "Into Fenris Keep", cn = "Into Fenris Keep", l = 22, r = 18, f = "H", races = { 5 }, s = { { 566037, "Charred Remains", "Silverpine Forest", 65, 34.2, 1421 } }, e = { 248755, "Lumina Windsinger", "Silverpine Forest", 65.5, 23.3, 1421 }, note = "The Blood Elf member is held in the basement of the Fenris Isle keep; he gives a follow-up to kill gnolls for the key; the key drop rate is high, usually within one or two kills." },
    [91862] = { n = "Lumina Windsinger", cn = "Lumina Windsinger", l = 22, r = 18, f = "H", races = { 5 }, s = { { 248755, "Lumina Windsinger", "Silverpine Forest", 65.5, 23.3, 1421 } }, e = { 248755, "Lumina Windsinger", "Silverpine Forest", 65.5, 23.3, 1421 }, note = "Chain: 'A Diplomatic Incident' (Bandarion Keep, Danessa Mor) -> return to the graveyard and talk to Trevan Rol -> investigate the tauren remains on the pyre on Fenris Isle -> pick up this step at the remains. Lumina is in a cage in the Fenris Keep basement; if the cage is empty, another player is probably escorting her out — wait for her to respawn." },
    [92466] = { n = "Call of Earth", cn = "Call of Earth", l = 4, r = 3, f = "H", races = { 6 }, s = { { 251374, "Windshaper Boro", "Zephras Isle", 42.8, 23.6, 2521 } }, e = { 251374, "Windshaper Boro", "Zephras Isle", 42.8, 23.6, 2521 } },
    [92467] = { n = "Call of Earth", cn = "Call of Earth", l = 4, r = 3, f = "H", races = { 6, 8 }, s = { { 251374, "Windshaper Boro", "Zephras Isle", 42.8, 23.6, 2521 } }, e = { 251166, "Minor Manifestation of Earth", "Zephras Isle", 49.6, 24, 2521 }, note = "The uphill trail is on the slope where you kill the flies; it starts at (47.5,25.3) - follow it up to get there." },
    [92468] = { n = "Call of Earth", cn = "Call of Earth", l = 4, r = 3, f = "H", races = { 6 }, s = { { 251166, "Minor Manifestation of Earth", "Zephras Isle", 49.6, 24, 2521 } }, e = { 251374, "Windshaper Boro", "Zephras Isle", 42.8, 23.6, 2521 }, items = { 5175 }, spells = { 8071 } },
