    [94427] = { n = "A Lesson in Divinity", cn = "A Lesson in Divinity", l = 12, r = 12, f = "H", races = { 5 }, s = { { 246378, "Danitha Morr", "Tirisfal Glades", 22, 44.6, 1420 } }, e = { 257648, "Tanis Alderwood", "Undercity", 65.6, 37.8, 1458 } },
    [94434] = { n = "A Lesson in Divinity", cn = "A Lesson in Divinity", l = 12, r = 12, f = "H", races = { 5 }, s = { { 257648, "Tanis Alderwood", "Undercity", 65.6, 37.8, 1458 } }, e = { 257648, "Tanis Alderwood", "Undercity", 65.6, 37.8, 1458 }, note = "Requires 'A Second Home' first. The whole chain starts with Danessa Mor's leader quest at Bandarion Keep and ends with learning Redemption. Lots of running back and forth — consider coming back once you have a mount; no need to force it before level 12." },
    [94435] = { n = "A Lesson in Divinity", cn = "A Lesson in Divinity", l = 12, r = 12, f = "H", races = { 5 }, s = { { 257648, "Tanis Alderwood", "Undercity", 65.6, 37.8, 1458 } }, e = { 246378, "Danitha Morr", "Tirisfal Glades", 22, 44.6, 1420 }, items = { 6866 } },
    [94436] = { n = "A Lesson in Divinity", cn = "A Lesson in Divinity", l = 12, r = 12, f = "H", races = { 5 }, s = { { 246378, "Danitha Morr", "Tirisfal Glades", 22, 44.6, 1420 } }, e = { 257655, "Deathguard Billmuth", "Tirisfal Glades", 22, 44.6, 1420 } },
    [94438] = { n = "A Lesson in Divinity", cn = "A Lesson in Divinity", l = 12, r = 12, f = "H", races = { 5 }, s = { { 257655, "Deathguard Billmuth", "Tirisfal Glades", 22, 44.6, 1420 } }, e = { 257663, "Deathguard Falgan", "Tirisfal Glades", 86.6, 47.6, 1420 }, note = "Deathguard Falgan's location has a turn-in marker on the minimap — go straight to it, no need to search for the body around the Scarlet camp yourself. Turn in right after accepting; if you wait too long he dies again. If he's already dead, go back to Bandarion Keep and get another Rune of Life from Danessa Mor to revive him and continue." },
    [94440] = { n = "A Lesson in Divinity", cn = "A Lesson in Divinity", l = 12, r = 12, f = "H", races = { 5 }, s = { { 257663, "Deathguard Falgan", "Tirisfal Glades", 86.6, 47.6, 1420 } }, e = { 257655, "Deathguard Billmuth", "Tirisfal Glades", 22, 44.6, 1420 } },
    [94441] = { n = "A Lesson in Divinity", cn = "A Lesson in Divinity", l = 12, r = 12, f = "H", races = { 5 }, s = { { 257655, "Deathguard Billmuth", "Tirisfal Glades", 22, 44.6, 1420 } }, e = { 246378, "Danitha Morr", "Tirisfal Glades", 22, 44.6, 1420 }, spells = { 7328 }, note = "End of the chain: you finally learn Redemption; the whole chain runs back and forth across the map (players jokingly call it \"Undead Paladin cardio\"), so doing it after getting a mount is strongly recommended." },
    [94449] = { n = "Call of Fire", cn = "Call of Fire", l = 10, r = 10, f = "A", races = { 3 }, s = { { 258098, "Eldrun Stormbreaker", "Ironforge", 47.4, 13.6, 1455 }, { 258113, "Ingrid Dunwald", "Dun Morogh", 47.4, 52, 1426 }, { 257446, "Teo Hammerstorm", "Dun Morogh", 28.7, 66.1, 1426 } }, e = { 257597, "Bruegs Kindleborn", "Dun Morogh", 87.6, 43.6, 1426 }, note = "Start of the mountain path (Dun Morogh 86.5,47.2): go through the South Gate Outpost tunnel; after exiting the first tunnel, keep left around the tower and the Barleybrew patrols. The path is near (Dun Morogh 86,47) and visible on the minimap; turn in at the cave at the top (Dun Morogh 89.7,44.6)." },
    [94465] = { n = "Call of Fire", cn = "Call of Fire", l = 11, r = 10, f = "A", races = { 3 }, s = { { 257597, "Bruegs Kindleborn", "Dun Morogh", 87.6, 43.6, 1426 } }, e = { 257808, "Braldir Ashmantle", "Loch Modan", 32, 66, 1432 }, note = "The trail starts at (31.4,58.2); follow the cliffside path past the stone totems to get there." },
