    [94912] = { n = "Child of Nature", cn = "Child of Nature", l = 10, r = 10, f = "A", races = { 95 }, s = { { 2543, "Archmage Ansirem Runeweaver", "Alterac Mountains", 18.8, 78.6, 1416 }, { 270459, "Alfina Nightgaze", "Alterac Mountains", 11.8, 56.6, 1416 } }, e = { 5504, "Sheldras Moontree", "Stormwind City", 21, 55.4, 1453 } },
    [94913] = { n = "Moonglade", cn = "Moonglade", l = 10, r = 10, f = "H", s = { { 3033, "Turak Runetotem", "Thunder Bluff", 76.4, 27.6, 1456 } }, e = { 11802, "Dendrite Starblaze", "Moonglade", 56.2, 30.4, 1450 } },
    [94914] = { n = "Moonglade", cn = "Moonglade", l = 10, r = 10, f = "A", races = { 95 }, s = { { 5504, "Sheldras Moontree", "Stormwind City", 21, 55.4, 1453 } }, e = { 11802, "Dendrite Starblaze", "Moonglade", 56.2, 30.4, 1450 } },
    [94971] = { n = "A Paladin's Steed", cn = "A Paladin's Steed", l = 40, r = 40, f = "H", races = { 5 }, s = { { 246378, "Danitha Morr", "Tirisfal Glades", 22, 44.6, 1420 } }, e = { 246378, "Danitha Morr", "Tirisfal Glades", 22, 44.6, 1420 }, spells = { 1279399 } },
    [94978] = { n = "Taming the Beast", cn = "Taming the Beast", l = 10, r = 10, races = { 95, 96 }, s = { { 252389, "Quel'ana Quickgale", "Zephras Isle", 59.6, 72.6, 2521 } }, e = { 252389, "Quel'ana Quickgale", "Zephras Isle", 59.6, 72.6, 2521 } },
    [94979] = { n = "Taming the Beast", cn = "Taming the Beast", l = 10, r = 10, races = { 95, 96 }, s = { { 252389, "Quel'ana Quickgale", "Zephras Isle", 59.6, 72.6, 2521 } }, e = { 252389, "Quel'ana Quickgale", "Zephras Isle", 59.6, 72.6, 2521 } },
    [95034] = { n = "The Debt", cn = "The Debt", l = 24, r = 18, f = "H", races = { 5 }, s = { { 259620, "Lumina Windsinger", "Silverpine Forest", 43.2, 41, 1421 } }, e = { 259620, "Lumina Windsinger", "Silverpine Forest", 43.2, 41, 1421 }, note = "Click through all of her dialogue to complete it, and you can go straight on to 'The Moonkissed Blade'." },
    [95036] = { n = "A Moon-Kissed Blade", cn = "A Moon-Kissed Blade", l = 25, r = 20, f = "H", races = { 5, 6 }, s = { { 259620, "Lumina Windsinger", "Silverpine Forest", 43.2, 41, 1421 } }, e = { 248840, "Trevan Rol", "Silverpine Forest", 43.4, 41, 1421 }, note = "Three materials: White Oak — drops from the goblins in Sneed's room in the Deadmines (almost guaranteed on the first kill); Enchanted Silver Bar — take it straight from the glowing table next to Arugal at the end of Shadowfang Keep (running through someone else's cleared instance also works); Purified Kor Gem — first get 'Search for the Kor Gem' from Ulrik Frostveil on Zoram Strand, then kill naga priestesses in front of the Blackfathom Deeps entrance (usually within about ten, but not guaranteed)." },
    [95042] = { n = "Seeking the Kor Gem", cn = "Seeking the Kor Gem", l = 25, r = 20, f = "H", races = { 5 }, s = { { 259649, "Ulric Frostveil", "Ashenvale", 11.8, 34.4, 1440 } }, e = { 259649, "Ulric Frostveil", "Ashenvale", 11.8, 34.4, 1440 }, items = { 272448 }, note = "Ott is in the southeast corner of Tarren Mill next to the Horde wagon; after turning in, watch him forge the sword for half a minute, then take the next step." },
    [95111] = { n = "An Underrated Talent", cn = "An Underrated Talent", l = 25, r = 20, f = "H", races = { 5 }, s = { { 248840, "Trevan Rol", "Silverpine Forest", 43.4, 41, 1421 } }, e = { 3539, "Ott", "Hillsbrad Foothills", 60.4, 26, 1424 } },
    [95125] = { n = "Ott's Masterwork", cn = "Ott's Masterwork", l = 25, r = 20, f = "H", races = { 5 }, s = { { 3539, "Ott", "Hillsbrad Foothills", 60.4, 26, 1424 } }, e = { 3539, "Ott", "Hillsbrad Foothills", 60.4, 26, 1424 }, note = "Pure waiting step: just stand by and watch him finish forging the weapon." },
    [95126] = { n = "The Moonsilver Blade", cn = "The Moonsilver Blade", l = 25, r = 20, f = "H", races = { 5 }, s = { { 3539, "Ott", "Hillsbrad Foothills", 60.4, 26, 1424 } }, e = { 248840, "Trevan Rol", "Silverpine Forest", 43.4, 41, 1421 }, items = { 268484 }, note = "Horde version of the Lv 20 Paladin weapon chain (the counterpart of the Alliance's Verigan's Fist); turn in the sword in the graveyard basement, then take the follow-up from Lumina next to you." },
    [95140] = { n = "Old Fire-Eye", cn = "Old Fire-Eye", l = 26, r = 20, f = "H", races = { 5 }, s = { { 259620, "Lumina Windsinger", "Silverpine Forest", 43.2, 41, 1421 } }, e = { 259620, "Lumina Windsinger", "Silverpine Forest", 43.2, 41, 1421 }, items = { 267369 }, note = "Before setting out, learn Two-Handed Swords from Weapon Master Archibald in the War Quarter (57.1,32.5) and get enough skill to fight a level 25 elite. Old Fire-Eye patrols around southern Silverpine Forest (48,80) (hugging the Greymane Wall, with a very wide north-south range; a few spawn points reach the y~41 area). He has a deep purple shield aura; your first auto-attack with the Moonsilver Blade equipped breaks the shield (an event message appears). Grouping is recommended; at level 25 with 110 Two-Handed Swords skill you can also solo him (Seals + Smite to grind him down)." },
    [95753] = { n = "Challenge of the Desert Wolf", cn = "Challenge of the Desert Wolf", l = 45, r = 37, s = { { 222856, "Odd Totem", "Tanaris", 43, 41.2, 1446 } }, e = { 222857, "Odd Totem", "Tanaris", 45.6, 37.8, 1446 }, note = "The two totems are at either end of the giant skeleton in southern Tanaris; run to the other one within the time limit to complete; clear the mobs along the way first so you don't get held up during the countdown." },
    [95803] = { n = "A Token of Good Faith", cn = "A Token of Good Faith", l = 12, r = 9, f = "H", races = { 5 }, s = { { 246378, "Danitha Morr", "Tirisfal Glades", 22, 44.6, 1420 } }, e = { 10181, "Lady Sylvanas Windrunner", "Undercity", 57.8, 91.8, 1458 } },
    [96016] = { n = "The Tempest's Weapons", cn = "The Tempest's Weapons", l = 40, r = 30, f = "A", s = { { 259023, "Veyric Thunderhame", "Arathi Highlands", 59.8, 27.6, 1417 } }, e = { 6176, "Bath'rah the Windwatcher", "Alterac Mountains", 80.4, 66.8, 1416 }, items = { 280696, 280607, 280605, 280604 }, note = "High demand: the mobs are often contested (grouping splits quest items, and the drop rate is mediocre), and on PvP servers the opposing faction camps the area long-term; the rewards are good, but prepare for a long grind." },
    [96020] = { n = "Playing with Fire", cn = "Playing with Fire", l = 35, r = 29, e = { { 461, "Demisette Cloyce", "Stormwind City", 39.2, 85, 1453 }, { 5172, "Briarthorn", "Ironforge", 50.4, 5.7, 1455 }, { 3326, "Zevrost", "Orgrimmar", 48.5, 45.4, 1454 }, { 4563, "Kaal Soulreaper", "Undercity", 86.2, 15.9, 1458 } }, note = "The starting item \"Nitre-Sulfur Carving\" is looted from a charred corpse and starts the quest when read; turn in the \"Activated Sulfur Carving\" to a warlock trainer in any capital city of your faction." },
    [96135] = { n = "Heed My Call", cn = "Heed My Call", l = 40, r = 30, f = "A", s = { { 259023, "Veyric Thunderhame", "Arathi Highlands", 59.8, 27.6, 1417 } }, e = { 259023, "Veyric Thunderhame", "Arathi Highlands", 59.8, 27.6, 1417 } },
    [96136] = { n = "Call of Air", cn = "Call of Air", l = 35, r = 30, f = "H", races = { 96 }, s = { { 259119, "Alaana Stormwalker", "Mulgore", 33.4, 22.6, 1412 } }, e = { 5905, "Prate Cloudseer", "Thousand Needles", 53.6, 42.8, 1413 }, items = { 5178 } },
    [96204] = { n = "The Windshaper's Wrath", cn = "The Windshaper's Wrath", l = 22, r = 18, f = "H", races = { 5 }, s = { { 248755, "Lumina Windsinger", "Silverpine Forest", 65.5, 23.3, 1421 } }, e = { 259620, "Lumina Windsinger", "Silverpine Forest", 43.2, 41, 1421 }, note = "Opening the cage starts an escort: she walks out of the keep through the war zone, says 'almost free' at the gate, then runs for the docks. As she nears the docks she returns to the graveyard on her own; the escort then completes and you get 'Debt'. Don't stray too far — leaving combat or losing track of her easily fails it." },
    [96243] = { n = "Call of Earth", cn = "Call of Earth", l = 4, r = 4, f = "A", s = { { 258098, "Eldrun Stormbreaker", "Ironforge", 47.4, 13.6, 1455 }, { 258113, "Ingrid Dunwald", "Dun Morogh", 47.4, 52, 1426 } }, e = { 257446, "Teo Hammerstorm", "Dun Morogh", 28.7, 66.1, 1426 } },
    [96264] = { n = "Elemental Aid", cn = "Elemental Aid", l = 33, r = 30, f = "A", s = { { 259023, "Veyric Thunderhame", "Arathi Highlands", 59.8, 27.6, 1417 } }, e = { 259023, "Veyric Thunderhame", "Arathi Highlands", 59.8, 27.6, 1417 } },
    [96438] = { n = "Battle at the Mannoroc Coven", cn = "Battle at the Mannoroc Coven", l = 40, r = 35, f = "A", s = { { 5492, "Katherine the Pure", "Stormwind City", 48.5, 49.1, 1453 } }, e = { 423703, "Broken Warhammer", "Desolace", 52.7, 84.8, 1443 }, note = "The meeting place is in the southeast corner of Desolace: from Shadowprey Village follow the main road south, then east; on site, investigate the warhammer and the shredded letter on the ground." },
    [96449] = { n = "Aeonas's Secret Refuge", cn = "Aeonas's Secret Refuge", l = 40, r = 35, f = "A", s = { { 3179, "Harold Riggs", "Wetlands", 8.2, 58.6, 1437 } }, e = { 217957, "Slain Scarlet Crusader", "Dun Morogh", 10.5, 74.8, 1426 }, note = "Find Harold Riggs at the northernmost dock in Menethil Harbor and ride his battered skiff to the refuge; once there, progress through the scripted dialogue — this step has no end coordinate to run to." },
    [96476] = { n = "In Search of Aeonas", cn = "In Search of Aeonas", l = 53, r = 45, f = "A", s = { { 5492, "Katherine the Pure", "Stormwind City", 48.5, 49.1, 1453 } }, e = { 221587, "Aeonas the Vindicated", "Felwood", 45, 52, 1448 }, note = "Fly to the Emerald Sanctuary in east-central Felwood; the scenario triggers on arrival, don't get interrupted on the way." },
    [96779] = { n = "Syndicate Sabotage", cn = "Syndicate Sabotage", l = 24, r = 24, s = { { 13085, "Myrokos Silentform", "Alterac Mountains", 85, 80.4, 1416 } }, e = { 13085, "Myrokos Silentform", "Alterac Mountains", 85, 80.4, 1416 } },
    [96781] = { n = "What's the Big Idea?", cn = "What's the Big Idea?", l = 36, r = 24, s = { { 13085, "Myrokos Silentform", "Alterac Mountains", 85, 80.4, 1416 } }, e = { 13085, "Myrokos Silentform", "Alterac Mountains", 85, 80.4, 1416 }, note = "The target is inside Stanblade's house (63,44); just pick his pocket. There are stealthed mobs around. If you're below his level, max Master of Deception and use Distract + Vanish as a fallback. At 29 without Flash Powder it takes many tries — better to come back at 30." },
    [96782] = { n = "Covert Extraction", cn = "Covert Extraction", l = 36, r = 24, s = { { 13085, "Myrokos Silentform", "Alterac Mountains", 85, 80.4, 1416 } }, e = { 13085, "Myrokos Silentform", "Alterac Mountains", 85, 80.4, 1416 }, note = "Much easier at 30 with Master of Deception maxed. The shield is inside the tower (41.4,40.2); the sword is in the tower at (38.5,58), surrounded by elites. Nothing guards the items directly — grab and go. No follow-up quest for now." },
    [96783] = { n = "A Way In", cn = "A Way In", l = 34, r = 24, s = { { 13085, "Myrokos Silentform", "Alterac Mountains", 85, 80.4, 1416 } }, e = { 656157, "Syndicate Strongbox", "Arathi Highlands", 32.4, 26.7, 1417 }, note = "The target item is at (Arathi Highlands 32.3,26.6)." },
    [96784] = { n = "Master of Disguise", cn = "Master of Disguise", l = 36, r = 24, s = { { 656157, "Syndicate Strongbox", "Arathi Highlands", 32.4, 26.7, 1417 } }, e = { 266847, "Anastasia Miller", "Arathi Highlands", 26.8, 64.4, 1417 }, note = "Anastasia Miller is on the rock ledge outside the keep (26.8,64.4); jump up from the house next to it." },
    [96785] = { n = "Ain't No Telling", cn = "Ain't No Telling", l = 36, r = 24, s = { { 266847, "Anastasia Miller", "Arathi Highlands", 26.8, 64.4, 1417 } }, e = { 266847, "Anastasia Miller", "Arathi Highlands", 26.8, 64.4, 1417 }, note = "Anastasia's hideout is on the second floor of a house next to the castle (29.5,65.1); get the stolen funds and return them." },
    [96786] = { n = "The Syndicate Sting", cn = "The Syndicate Sting", l = 34, r = 24, s = { { 266847, "Anastasia Miller", "Arathi Highlands", 26.8, 64.4, 1417 } }, e = { 13085, "Myrokos Silentform", "Alterac Mountains", 85, 80.4, 1416 }, note = "The chest is at (Arathi Highlands 15.5,43), guarded by two NPCs." },
    [97022] = { n = "Report to Danitha", cn = "Report to Danitha", l = 40, r = 40, f = "H", races = { 5 }, s = { { 260093, "Garen Largo", "Undercity", 47.5, 15, 1458 }, { 246344, "Alodan the Hopeful", "Thunder Bluff", 25.4, 14.7, 1456 } }, e = { 246378, "Danitha Morr", "Tirisfal Glades", 22, 44.6, 1420 } },
    [97168] = { n = "Material Assistance", cn = "Material Assistance", l = 60, r = 58, f = "A", s = { { 258098, "Eldrun Stormbreaker", "Ironforge", 47.4, 13.6, 1455 } }, e = { 258098, "Eldrun Stormbreaker", "Ironforge", 47.4, 13.6, 1455 }, note = "Needs an Azerothian Diamond and a Pristine Black Diamond, both buyable materials - get them at the auction house before coming back." },
    [97169] = { n = "The Darkreaver Menace", cn = "The Darkreaver Menace", l = 60, r = 58, f = "A", s = { { 258098, "Eldrun Stormbreaker", "Ironforge", 47.4, 13.6, 1455 } }, e = { 258098, "Eldrun Stormbreaker", "Ironforge", 47.4, 13.6, 1455 }, note = "In Scholomance, go to the center of the basement of the Ossuary and use the Divination Scryer to draw out several waves of the dead; once they're cleared, Darkreaver appears; kill him for the insignia and return to Ironforge." },
    [97174] = { n = "A Worthy Endeavor", cn = "A Worthy Endeavor", l = 60, r = 60, f = "H", races = { 5 }, s = { { 246378, "Danitha Morr", "Tirisfal Glades", 22, 44.6, 1420 } }, e = { 246378, "Danitha Morr", "Tirisfal Glades", 22, 44.6, 1420 }, note = "Bandarion Keep is in southeastern Tirisfal Glades; head south from Brill along the main road." },
    [97175] = { n = "Due Sacrifice", cn = "Due Sacrifice", l = 60, r = 60, f = "H", races = { 5 }, s = { { 246378, "Danitha Morr", "Tirisfal Glades", 22, 44.6, 1420 } }, e = { 5994, "Zayus", "Orgrimmar", 35.8, 87.6, 1454 }, note = "Sayus is in Orgrimmar's Valley of Wisdom; the Exorcism Censer requires a 150 gold donation first - without the money you can't get the next step." },
    [97176] = { n = "Exorcising Terrordale", cn = "Exorcising Terrordale", l = 60, r = 60, f = "H", races = { 5 }, s = { { 246378, "Danitha Morr", "Tirisfal Glades", 22, 44.6, 1420 } }, e = { 246378, "Danitha Morr", "Tirisfal Glades", 22, 44.6, 1420 }, note = "The Vale of Fear is in northeastern Tirisfal Glades; use the censer to dispel 25 wailing spirits. Put the censer on your action bar and spam it; spirits only count once dispersed." },
    [97177] = { n = "Acts of Mercy", cn = "Acts of Mercy", l = 60, r = 60, f = "H", races = { 5 }, s = { { 5994, "Zayus", "Orgrimmar", 35.8, 87.6, 1454 } }, e = { 246378, "Danitha Morr", "Tirisfal Glades", 22, 44.6, 1420 }, note = "Bring the censer back to Bandarion Keep; on turn-in, immediately pick up 'The Spirits of Terrordale'." },
    [97178] = { n = "Ott of Tarren Mill", cn = "Ott of Tarren Mill", l = 60, r = 60, races = { 5 }, e = { 3539, "Ott", "Hillsbrad Foothills", 60.4, 26, 1424 }, note = "Continues straight from 'The Spirits of Terrordale'; go to the Tarren Mill smithy and find Ott." },
    [97179] = { n = "Collection of Goods", cn = "Collection of Goods", l = 60, r = 60, f = "H", races = { 5 }, s = { { 3539, "Ott", "Hillsbrad Foothills", 60.4, 26, 1424 } }, e = { 3539, "Ott", "Hillsbrad Foothills", 60.4, 26, 1424 }, note = "Requires 40 Runecloth, 6 Arcanite Bars, 10 Arthas' Tears and 5 Stratholme Holy Water, plus 150 gold; the Arcanite Bars and Holy Water are the main expenses, so stock up at the AH ahead of time." },
    [97180] = { n = "Ott's Finest Work", cn = "Ott's Finest Work", l = 60, r = 60, f = "H", races = { 5 }, s = { { 3539, "Ott", "Hillsbrad Foothills", 60.4, 26, 1424 } }, e = { 246378, "Danitha Morr", "Tirisfal Glades", 22, 44.6, 1420 }, note = "Obtain the Arcanite Barding and bring it back to Bandarion Keep." },
    [97182] = { n = "An Offering of Vengeance", cn = "An Offering of Vengeance", l = 60, r = 60, f = "H", races = { 5 }, s = { { 246378, "Danitha Morr", "Tirisfal Glades", 22, 44.6, 1420 } }, e = { 14566, "Ancient Equine Spirit", "", 0, 0 }, note = "Take the Arcanite Barding and Enchanted Forage to Dire Maul West and kill Tendris Warpwood; after freeing the Ancient Equine Spirit, present the barding; get the Enchanted Forage from Nathanos Blightcaller in the Eastern Plaguelands." },
    [97183] = { n = "Blessed Arcanite Barding", cn = "Blessed Arcanite Barding", l = 60, r = 60, s = { { 14566, "Ancient Equine Spirit", "", 0, 0 } }, e = { 246378, "Danitha Morr", "Tirisfal Glades", 22, 44.6, 1420 } },
    [97184] = { n = "The Divination Scryer", cn = "The Divination Scryer", l = 60, r = 60, f = "H", races = { 5 }, s = { { 246378, "Danitha Morr", "Tirisfal Glades", 22, 44.6, 1420 } }, e = { 246378, "Danitha Morr", "Tirisfal Glades", 22, 44.6, 1420 } },
    [97185] = { n = "Justice and Retribution", cn = "Justice and Retribution", l = 60, r = 60, s = { { 246378, "Danitha Morr", "Tirisfal Glades", 22, 44.6, 1420 } }, e = { 14568, "Darkreaver's Fallen Charger", "", 0, 0 }, spells = { 1296534 } },
    [97186] = { n = "Manna-Enriched Horse Feed", cn = "Manna-Enriched Horse Feed", l = 60, r = 60, s = { { 11878, "Nathanos Blightcaller", "Eastern Plaguelands", 26.6, 74.8, 1423 } }, e = { 11878, "Nathanos Blightcaller", "Eastern Plaguelands", 26.6, 74.8, 1423 }, items = { 18775 } },
    [97243] = { n = "Call of Fire", cn = "Call of Fire", l = 10, r = 10, f = "H", s = { { 252382, "Sessaria Skystride", "Zephras Isle", 58.2, 78.4, 2521 }, { 254082, "Aarnor Galestrike", "Zephras Isle", 43.4, 44.8, 2521 } }, e = { 268592, "Olariaan Swiftburn", "Zephras Isle", 51.2, 86, 2521 } },
    [97244] = { n = "Call of Fire", cn = "Call of Fire", l = 10, r = 10, f = "H", s = { { 268592, "Olariaan Swiftburn", "Zephras Isle", 51.2, 86, 2521 } }, e = { 268592, "Olariaan Swiftburn", "Zephras Isle", 51.2, 86, 2521 } },
    [97245] = { n = "Call of Fire", cn = "Call of Fire", l = 10, r = 10, f = "H", s = { { 268592, "Olariaan Swiftburn", "Zephras Isle", 51.2, 86, 2521 } }, e = { 268592, "Olariaan Swiftburn", "Zephras Isle", 51.2, 86, 2521 }, note = "Before setting out, visit your shaman trainer and learn all your Fire spells; don't go in under-skilled." },
    [97257] = { n = "Call of Fire", cn = "Call of Fire", l = 10, r = 10, f = "H", s = { { 268592, "Olariaan Swiftburn", "Zephras Isle", 51.2, 86, 2521 } }, e = { 252382, "Sessaria Skystride", "Zephras Isle", 58.2, 78.4, 2521 }, items = { 5176, 263412 }, spells = { 3599 } },
    [97286] = { n = "Research Access", cn = "Research Access", l = 20, r = 1, s = { { 211033, "Garion Wendell", "Stormwind City", 48.9, 86.5, 1453 }, { 211022, "Owen Thadd", "Undercity", 73.4, 33.0, 1458 } }, e = { 211033, "Garion Wendell", "Stormwind City", 48.9, 86.5, 1453 } },
    [98340] = { n = "The Great Cat Spirit", cn = "The Great Cat Spirit", l = 20, r = 20, f = "H", races = { 6, 96 }, s = { { 3033, "Turak Runetotem", "Thunder Bluff", 76.4, 27.6, 1456 } }, e = { 11802, "Dendrite Starblaze", "Moonglade", 56.2, 30.4, 1450 } },
    [98341] = { n = "The Great Windborne Cat Spirit", cn = "The Great Windborne Cat Spirit", l = 20, r = 20, races = { 95, 96 }, s = { { 11802, "Dendrite Starblaze", "Moonglade", 56.2, 30.4, 1450 } }, e = { 272054, "Avatar of Saeyleenan", "Moonglade", 43.9, 73.4, 1450 }, note = "Selena is at (44,73); you have to climb a small hill before you can see her - very hard to find." },
